INSERT INTO `history` (`id`, `title`, `content`, `created_at`) VALUES
(18, '2024', 'КОЛЛЕДЖ ОТКРЫВАЕТ НОВУЮ СПЕЦИАЛЬНОСТЬ ДЛЯ СОВРЕМЕННОГО РЫНКА ТРУДА ПО СПЕЦИАЛЬНОСТИ «УПРАВЛЕНИЕ НЕДВИЖИМОСТЬЮ», КВАЛИФИКАЦИЯ «МАСТЕР-ХАУС»', '2025-01-05 04:07:59'),
(19, '2023', 'КОЛЛЕДЖ ОТКРЫЛ НОВУЮ СПЕЦИАЛЬНОСТЬ «АВТОМАТИЗИРОВАННЫЕ СИСТЕМЫ ПРОЕКТИРОВАНИЯ И ЭКСПЛУАТАЦИИ ЗДАНИЙ (BIM)»\r\n', '2025-01-05 04:08:13'),
(20, '2022', 'ВПЕРВЫЕ В РЕСПУБЛИКЕ КАЗАХСТАН НА БАЗЕ КОЛЛЕДЖА СОСТОЯЛИСЬ РЕГИОНАЛЬНЫЙ, А ЗАТЕМ НАЦИОНАЛЬНЫЙ КОНКУРС ПРОФЕССИОНАЛЬНОГО МАСТЕРСТВА СРЕДИ ПЕДАГОГО ТЕХНИЧЕСКОГО И ПРОФЕССИОНАЛЬНОГО, ПОСЛЕСРЕДНЕГО ОБРАЗОВАНИЯ ПО ПРОФИЛЮ «СТРОИТЕЛЬСТВО»\r\n', '2025-01-05 04:08:26'),
(21, '2021', 'КГУ КАРАГАНДИНСКИЙ ТЕХНИКО-СТРОИТЕЛЬНЫЙ КОЛЛЕДЖ ПРЕОБРАЗОВАН В КГКП КАРАГАНДИНСКИЙ ТЕХНИКО-СТРОИТЕЛЬНЫЙ КОЛЛЕДЖ ДЕМОНСТРАЦИОННЫЕ ЭКЗАМЕНЫ ВВЕДЕНЫ ПО КОМПЕТЕНЦИЯМ «КИРПИЧНАЯ КЛАДКА», «ЭЛЕКТРОМОНТАЖ, «СВАРОЧНЫЕ ТЕХНОЛОГИИ», «ОБЛИЦОВКА ПЛИТКОЙ» 17 ФЕВРАЛЯ СОСТОЯЛОСЬ ТОРЖЕСТВЕННОЕ ОТКРЫТИЕ ЦЕНТРА КОМПЕТЕНЦИЙ\r\n', '2025-01-05 04:08:39'),
(22, '2020', 'РЕГИОНАЛЬНЫЙ ЧЕМПИОНАТ «WORLDSKILLS-2020» - ШЕСТЬ ПЕРВЫХ, ОДНО ВТОРОЕ, ОДНО ТРЕТЬЕ МЕСТА КОЛЛЕДЖ СТАЛ УЧАСТНИКОМ РЕСПУБЛИКАНСКОГО ПРОЕКТВ «ЖАС МАМАН» ПО 10-ТИ ПРОФЕССИЯМ: СВАРЩИКИ И ГАЗОРЕЗЧИКИ, СУПЕРВАЙЗЕРЫ СТРОИТЕЛЬСТВА, ДИЗАЙНЕРЫ ИНТЕРЬЕРА И ДЕКОРАТОРЫ, КАМЕНЩИКИ, СЛЕСАРИ ПРОМЫШЛЕННОГО ОБОРУДОВАНИЯ, ШТУКАТУРЫ, КРАСНОДЕРЕВЩИКИ И МЕБЕЛЬЩИКИ, НАСТИЛЬЩИКИ ПОЛОВ И ПЛИТОЧНИКИ, САНТЕХНИКИ И ТРУБОПРОВОДЧИКИ, СТРОИТЕЛЬНЫЕ МАЛЯРЫ НАГРУДНЫМ ЗНАКОМ «АЛТЫН БАРС» И БЛАГОДАРСТВЕННОЙ ГРАМОТОЙ ПРЕЗИДЕНТА РЕСПУБЛИКИ КАЗАХСТАН УДОСТОЕНА ПЕДАГОГ КОЛЛЕДЖА БАХТЫБАЕВА А.Т.\r\n', '2025-01-05 04:08:48'),
(23, '2018', 'НАЦИОНАЛЬНЫЙ ЧЕМПИОНАТ «WORLDSKILLS-2018, 2019» - ТРИ ПЕРВЫХ МЕСТА И ДВА УЧАСТНИКА «WORLDSKILLS BELARUS» КОЛЛЕДЖ ПРОШЕЛ ИНСТИТУЦИОНАЛЬНУЮ И СПЕЦИАЛИЗИРОВАННУЮ АККРЕДИТАЦИЮ ПО СПЕЦИАЛЬНОСТЯМ «СТРОИТЕЛЬСТВО», «ТЕХНИЧЕСКАЯ ЭКСПЛУАТАЦИЯ ДОРОЖНО-СТРОИТЕЛЬНЫХ МАШИН» ВТОРЫЕ МЕЖДУНАРОДНЫЕ ПАРАДЕЛЬФИЙКИЕ ИГРЫ 11-17 НОЯБРЯ 2018г. ИЖЕВСК-УДМУРСКАЯ РЕСПУБЛИКА-РОССИЯ. УЧАСТИЕ ПРИНЯЛИ 7 СТУДЕНТОВ И 5 РУКОВОДИТЕЛЕЕЙ ОТ КОЛЛЕДЖА В НОМИНАЦИЯХ ЖИВОПИСЬ, ГРАФИКА, БИСЕРОПЛЕТЕНИЕ, ИЗДЕЛИЯ ИЗ КОЖИ, КВИЛИНГ, ЛИТЕРАТУРА II НАЦИОНАЛЬНЫЙ ЧЕМПИОНАТ ПО ПРОФЕССИОНАЛЬНОМУ МАСТЕРСТВУ«ABILYMPICS-2019», II НАЦИОНАЛЬНЫЙ ЧЕМПИОНАТ ПО ПРОФЕССИОНАЛЬНОМУ МАСТЕРСТВУ «DEAFSKILLS-2019» В КОМПЕТЕНЦИЯХ ЖИВОПИСЬ, ЭПОКСИДНАЯ СМОЛА, РАБОТА С КОЖЕЙ, ЮВЕЛИРНО-МОНТАЖНЫЕ РАБОТЫ. ЗАНЯТЫ ПРИЗОВЫЕ ПЕРВЫЕ МЕСТА ПО ДВУМ КОМПЕТЕНЦИЯМ\r\n', '2025-01-05 04:10:52'),
(24, '2017', 'НАЦИОНАЛЬНЫЙ ЧЕМПИОНАТ «WORLDSKILLS-2017» - ДВА ПЕРВЫХ МЕСТА И ОДНО ТРЕТЬЕ МЕСТО КАЗАХСТАН ВПЕРВЫЕ СТАЛ УЧАСТНИКОМ МИРОВОГО ДВИЖЕНИЯ «ABILYMPICS». УЧАСТИЕ СТУДЕНТОВ КОЛЛЕДЖА В НАЦИОНАЛЬНОМ ЧЕМПИОНАТЕ, В ЧЕМПИОНАТЕ ПО ПРОФЕССИОНАЛЬНОМУ МАСТЕРСТВУ «ABILYMPICS-2017» В Г. МОСКВЕ, В МЕЖДУНАРОДНОМ ЧЕМПИОНАТЕ ПРОФЕССИОНАЛЬНОГО МАСТЕРСТВА ДЛЯ ЛИЦ С НАРУШЕНИЕМ СЛУХА «DEAFSKILLS» ЧЕМПИОНАТЕ WORLDSKILLS ABU-DHABI-2017\r\n', '2025-01-05 04:11:11'),
(25, '2016', 'НАЦИОНАЛЬНЫЙ ЧЕМПИОНАТ ПО КОМПЕТЕНЦИЯМ «ОБЛИЦОВКА ПЛИТКОЙ», «КЛАДКА КИРПИЧА» - 1, 3 МЕСТА УЧАСТИЕ В EUROSKILLS-2016 В ГОРОДЕ ГЕТЕБОРГ, ШВЕЦИЯ КОЛЛЕДЖ ОРГАНИЗАТОР ПЕРВОГО РЕСПУБЛИКАНСКОГО СЕМИНАРА ПО ВОПРОСАМ ИНКЛЮЗИВНОГО ОБРАЗОВАНИЯ «ИНКЛЮЗИВНОЕ ОБРАЗОВАНИЕ В КАЗАХСТАНЕ: ПРОБЛЕМЫ И ПЕРСПЕКТИВЫ» КОЛЛЕДЖ ОТКРЫВАЕТ НОВЫЕ СПЕЦИАЛЬНОСТИ «АРХИТЕКТУРА» И «ЭНЕРГОАУДИТ» ПРИСУЖДЕНИЕ АЛТАЙБАЕВУ Р.К. ПРЕМИИ АКИМА ОБЛАСТИ В НОМИНАЦИИ «ЛУЧШИЙ МАСТЕР ПРОИЗВОДСТВЕННОГО ОБУЧЕНИЯ»\r\n', '2025-01-05 04:11:26'),
(26, '2015', 'КОЛЛЕДЖ ВПЕРВЫЕ СТАНОВИТСЯ УЧАСТНИКОМ МЕЖДУНАРОДНОГО ЧЕМПИОНАТА «WORLDSKILLS» В ГОРОДЕ САН ПАУЛУ, БРАЗИЛИЯ ОТКРЫТИЕ ТВОРЧЕСКИХ ГРУПП «ТЕАТР ТЕНЕЙ» И «ХОР ЖЕСТОВОГО ПЕНИЯ» С УЧАСТИЕМ СТУДЕНТОВ С ОСОБЫМИ ОБРАЗОВАТЕЛЬНЫМИ ПОТРЕБНОСТЯМИ\r\n', '2025-01-05 04:11:38'),
(27, '2014', 'КОЛЛЕДЖ ОТКРЫЛ НОВЫЕ ТЕХНИЧЕСКИЕ СПЕЦИАЛЬНОСТИ ПО ПРОФИЛЮ «СТРОИТЕЛЬСТВО, ДИЗАЙН» ЗАПУЩЕН ПРОЕКТ ИНКЛЮЗИВНОГО ОБРАЗОВАНИЯ ПО ОБУЧЕНИЮ СТУДЕНТОВ С ОСОБЫМИ ОБРАЗОВАТЕЛЬНЫМИ ПОТРЕБНОСТЯМИ КОЛЛЕДЖ СТАЛ УЧАСТНИКОМ РЕСПУБЛИКАНСКОГО ПРОЕКТА «СЕРПІН» КОЛЛЕДЖ ЗАПУСТИЛ ПРОГРАММЫ КРАТКОСРОЧНЫХ КУРСОВ ПРОФЕССИОНАЛЬНОЙ ПОДГОТОВКИ И ПЕРЕПОДГОТОВКИ РАБОЧИХ КАДРОВ\r\n', '2025-01-05 04:11:49'),
(28, '2012', 'ПШ №26 ПРЕОБРАЗОВАНА В КГУ КАРАГАНДИНСКИЙ ТЕХНИКО-СТРОИТЕЛЬНЫЙ КОЛЛЕДЖ ПРИСУЖДЕНИЕ ФАРТУКЕВИЧ В.И. ПРЕМИИ АКИМА ОБЛАСТИ В НОМИНАЦИИ «ЛУЧШИЙ МАСТЕР ПРОИЗВОДСТВЕННОГО ОБУЧЕНИЯ»\r\n', '2025-01-05 04:12:03'),
(29, '2009', 'ПШ №26 ПЕРЕИМЕНОВАНА В ГУ ПЛ №26\r\n', '2025-01-05 04:12:16'),
(30, '2002', 'ПТШ №26 ПЕРЕИМЕНОВАНА В ПШ №26\r\n', '2025-01-05 04:12:29'),
(31, '1996', 'СПТУ №26 ПЕРЕИМЕНОВАНО В ПТШ№26\r\n', '2025-01-05 04:12:40'),
(32, '1984', 'ГПТУ №129 ПЕРЕИМЕНОВАНО В СПТУ №26\r\n', '2025-01-05 04:12:58'),
(33, '1976', 'ОСНОВАНИЕ ГПТУ №129 БАЗОВОГО УЧЕБНОГО ЗАВЕДЕНИЯ ОБЪЕДИНЕНИЯ «ЦЕНТРКАЗГЕОЛОГИЯ»\r\n', '2025-01-05 04:13:09');

