--
-- Структура таблицы `media_publications`
--

CREATE TABLE `media_publications` (
  `id` int NOT NULL,
  `media_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Название СМИ',
  `media_type` enum('newspaper','tv','radio','online','magazine') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'newspaper' COMMENT 'Тип СМИ',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Описание публикации',
  `link` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Ссылка на публикацию',
  `publication_date` date NOT NULL COMMENT 'Дата публикации',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Дата создания записи',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Дата обновления записи'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Публикации СМИ о организации';

--
-- Дамп данных таблицы `media_publications`
--

INSERT INTO `media_publications` (`id`, `media_name`, `media_type`, `description`, `link`, `publication_date`, `created_at`, `updated_at`) VALUES
(1, 'Жұмысшы маман ұстаханасы', 'newspaper', 'Қарағанды тех­никалық-құры­лыс колледжі түлек­терінің табыс­ты мансап бас­тауына нәти­желі мүмкіндік ұсынып отыр. Биыл Жұмысшы мамандықтары жылы қарсаңында оқу орны жаңа белестерге қадам басты.', 'https://egemen.kz/article/394937-zhumysshy-maman-ustakhanasy', '2025-09-11', '2025-09-11 06:30:11', '2025-09-11 06:32:05'),
(2, 'Лаборатория будущего: карагандинские студенты осваивают цифровые технологии', 'online', 'От датчиков движения до интеллектуального щита управления — полный набор цифровых технологий современного здания теперь доступен студентам Карагандинского колледжа техники и строительства. Здесь открыли лабораторию «Умный дом» для практической подготовки будущих специалистов. Особое внимание уделено внедрению элементов цифровизации и искусственного интеллекта в образовательный процесс. ', 'https://www.gov.kz/memleket/entities/karaganda/press/news/details/1159773?lang=ru', '2026-02-23', '2026-02-23 05:53:21', '2026-02-23 05:54:11'),
(3, 'Болашақ зертханасы: Қарағанды студенттері цифрлық технологияларды игеруде', 'online', 'Қозғалыс датчиктерінен бастап интеллектуалды басқару қалқанына дейін — заманауи ғимаратқа тән цифрлық технологиялардың толық жиынтығы енді Қарағанды техника және құрылыс колледжінің студенттеріне қолжетімді. Оқу орнында болашақ мамандарды тәжірибелік даярлауға арналған «Ақылды үй» зертханасы ашылды. Білім беру үдерісінде цифрландыру мен жасанды интеллект элементтерін енгізуге басымдық берілген.', 'https://www.gov.kz/memleket/entities/karaganda/press/news/details/1159773?lang=kk', '2026-02-23', '2026-02-23 05:53:40', '2026-02-23 05:53:40'),
(4, 'Аймақ айнасы | Құрылыс және инновация', 'tv', 'Аймақ айнасы | Құрылыс және инновация', 'https://www.youtube.com/watch?v=G9v2SSZG_tw', '2026-04-01', '2026-04-01 08:55:02', '2026-04-01 08:55:02');

