--
-- Структура таблицы `projects`
--

CREATE TABLE `projects` (
  `id` int NOT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `main_image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `gallery` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `photo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Дамп данных таблицы `projects`
--

INSERT INTO `projects` (`id`, `name`, `description`, `main_image`, `gallery`, `created_at`, `photo`) VALUES
(5, 'РЕСПУБЛИКАНСКИЙ ПРОЕКТ «ЖАС МАМАН»', ' Карагандинский технико-строительный колледж в 𝟐𝟎𝟏𝟗 году стал одним из участников данного проекта по десяти рабочим профессиям, в том числе по квалификациям из атласа новых профессий. Реализация данного проекта способствовала открытию инновационного Центра компетенций, состоящего из трех самостоятельных блоков, расположенных на 𝟏-ом, 𝟐-ом и 𝟑-м этажах. \r\nВ настоящее время Центр позволяет студентам осваивать современные технологические и производственные процессы, ежегодно быть полноправным участником международных соревнований 𝐖𝐨𝐫𝐥𝐝𝐬𝐤𝐢𝐥𝐥𝐬.\r\nВ рамках вышеназванного проекта колледжу было выделено 𝟑𝟔𝟎 миллионов тенге, благодаря чему приобретено промышленное оборудование, идентичное оборудованию, используемой в современном производстве и 𝐈𝐓-индустрии. Более того, отвечающие самым высоким требованиям, что позволяет вести подготовку специалистов высокого класса, реализовывать пилотные проекты в области строительной индустрии и стартапов в промышленном дизайне.\r\nНа основе данного оборудования созданы новые и модернизированы существующие, в общей сложности 𝟏𝟖 мастерских и 𝟖 лабораторий. Каждый из которых используется по двум, а некоторые по пяти специальностям.\r\nКак известно, в настоящее время в стране активно развивается строительная отрасль, где востребованы специалисты, обладающие навыками работы с новыми материалами, использующие современные архитектурные, дизайнерские и ландшафтные решения, умеющие программировать роботов-строителей, беспилотники летательных аппаратов, создавать архитектурные модели с помощью алгоритмов и кодов, решать вопросы энергоэффективности зданий, обладать высокой визуальной культурой. Это есть - строительство будущего, которому студенты колледжа обучаются именно сейчас и сегодня в нашем учебном заведении.\r\nВ 𝟐𝟎𝟐𝟏 году начата подготовка по совершенно новому направлению – это подготовка специалистов в области Промышленного дизайна. Для этой цели заблаговременно была создана учебная лаборатория Промышленного дизайна, которая оснащена многофункциональным оборудованием Мимаки, позволяющее студентам научиться обслуживать цифровые станки ЧПУ.\r\nЛаборатория и мастерская сварочного дела используются по трем специальностям колледжа. Виртуальный тренажер, рабочие места, 𝟏𝟎 оборудованных кабин с полным комплектом аппаратов – гарантия и успех в подготовке электрогазосварщиков для любой отрасли производства.\r\nЭлектромонтажная лаборатория, полигон, мастерская предназначены для трех специальностей. Здесь же на оборудованиях, приобретенных по проекту Жас маман, проводится обучение участников соревнований 𝐖𝐨𝐫𝐥𝐝𝐬𝐤𝐢𝐥𝐥𝐬 всех учебных заведений Карагандинской области.\r\nДля мастерских столярного дела и мебельного производства приобретены станки и машины с компьютерным управлением, позволяющие изготавливать сложные детали, исключающие появление брака.\r\nМакетное проектирование – есть основа развития профессионального творчества будущих архитекторов, дизайнеров, специалистов декоративно-прикладного искусства и ландшафтного строительства. Новые оборудования мастерских позволяют на стадии разработки проекта получить наглядное представление о принимаемых объемных решениях.\r\nДля всех специальностей, включенных в проект Жас маман, созданы учебная лаборатория спецтехнологии и электротехники, кабинет охраны труда, где студенты на базе оборудования получают знания в области технологии современных отраслей производства, электрической части машин и механизмов, а также приобретают навыки оказания первой медицинской помощи.\r\nС 𝟐𝟎𝟐𝟎 года колледж в качестве итоговой аттестации проводит демонстрационные экзамены по пяти компетенциям, таким как малярные и декоративные работы, кирпичная кладка, облицовка плиткой, сварочные технологии и электромонтаж. Уровень знаний, умений и практических навыков ежегодно оцениваются независимыми экспертами с производства.\r\nРанняя профилизация в колледже начинается с нового учебного года и способствует сознательному, обоснованному выбору школьниками будущей профессии, помогает убедиться в достоинствах и определиться в своих интересах. В связи с чем, профессиональные пробы проводятся по 𝟗 специальностям. \r\nПодписан меморандум с Шахтинской художественной школой, ученики которой ежегодно проходят профессиональные пробы по специальностям:   «Дизайн интерьера, реставрация, реконструкция гражданских зданий», «Декоративно- прикладное искусство и народные промыслы, «Архитектура», «Лесное хозяйство, садово-парковое и ландшафтное строительство».\r\nСоздание тренировочного лагеря для участников Ворлдскиллс является одним из результатов проекта Жас маман. Он позволяет повысить качество подготовки участников чемпионатов Ворлдскиллс. \r\nНа базе Центра компетенции ежегодно проводятся региональные чемпионаты Ворлдскиллс по девяти компетенциям: малярные и декоративные работы, кирпичная кладка, облицовка плиткой, сухое строительство и штукатурные работы, сварочные технологии, электромонтаж, флористика, визуальный мерчендайзинг и витринистики и управление беспилотными летательными аппаратами. \r\nБлагодаря условиям, созданных в Центре компетенции, открылись новые творческие кружки, которые в настоящее время работают над выпуском: \r\n- сувенирной продукции;\r\n- продукцией мебельного производства, а также занимаются комплексными решениями дизайна в сфере благоустройства.\r\nОхват студентов по кружкам технического творчества составляет более шестиста человек. Все это способствует безбарьерному вхождению студентов в бизнес-среду.\r\nОснащение мастерских и лабораторий в рамках проекта Жас маман в полном и гарантированном объеме позволяет:\r\n- поднять на новый уровень подготовку специалистов по современным рабочим профессиям и спрос на выпускников колледжа, в том числе на основе расширения связи с казахстанскими и иностранными предприятиями;\r\n- стать тренировочным лагерем по 𝐖𝐨𝐫𝐥𝐝𝐬𝐤𝐢𝐥𝐥𝐬 и заявить о достойных участниках профессиональных соревнований;\r\n- создать условия для безбарьерного вхождения в бизнес-среду;\r\n- быть площадкой по проведению профессиональных проб для школьников;\r\n- осуществлять подготовку и переподготовку безработного населения;\r\n- расширить возможности обучения лиц с особыми образовательными потребностями;\r\n- улучшить качество и доводимость до коммерциализации стартап-проектов;\r\n- повысить престиж рабочей профессии и имидж учебного заведения;\r\n- преподавателям и мастерам производственного обучения проявить стремление к повышению профессионального мастерства.\r\nБезусловно, проект Жас маман был направлен на развитие человеческого капитала, поддержку молодежи в получении качественного образования и востребованной профессии.\r\nВ настоящее время планируется привлечение зарубежных партнеров для обучения преподавателей и мастеров производственного обучения, а также содействия в составлении программ обучения на основе международных стандартов, в том числе стандартов 𝐖𝐨𝐫𝐥𝐝𝐒𝐤𝐢𝐥𝐥𝐬, по заявленным профессиям, что позволит колледжу подготовиться и пройти международную отраслевую аккредитацию. В дальнейшем, наши выпускники будут иметь возможность получить международный сертификат на определенную компетенцию и быть востребованным в любой стране.\r\nТем самым, Центр компетенций, созданный на базе нашего учебного заведения и располагающий новейшим оборудованием, позволил создать собственную модель подготовки рабочих кадров, где особое внимание уделяется развитию стартап проектов, предпринимательской деятельности студентов, а в будущем будет способствовать созданию студенческих малых предприятий по выпуску продукции и оказанию услуг для вхождения колледжа бизнес-среду. ', 'ж9.jpeg', '2.jpeg,DSC_0108.JPG,IMG_2772.JPG,IMG_2797.JPG,IMG_9311.JPG_1.jpg,IMG_9353.JPG_1.jpg,IMG_9358.JPG_1.jpg,IMG_9381.JPG_1.jpg,IMG_9390.JPG_1.jpg', '2025-01-05 04:24:40', ''),
(6, 'ПРОЕКТ «ИНКЛЮЗИВНОЕ ОБРАЗОВАНИЕ». НАЦИОНАЛЬНЫЙ ЧЕМПИОНАТ ABILYMPICS.', ' Карагандинский технико-строительный колледж с сентября 𝟐𝟎𝟏𝟒 года в экспериментальном режиме начал работу со студентами, ограниченных в возможностях развития, а именно ограниченных в развитии слуха и речи, в нарушении опорно-двигательного аппарата.\r\nПредварительно было проведено анкетирование среди педагогов колледжа и обучающихся на определение уровня восприятия данного проекта. Выяснилось, что 𝟒𝟎% педагогам интересны вопросы инклюзивного обучения, 𝟑𝟓% выразили сомнение в достаточной изученности данной проблемы в ТиПО, 𝟐𝟓% инженерно-педагогических работников отрицали возможность участия в проекте. Приблизительно таковыми были и ответы студентов колледжа. \r\nПроект Инклюзивное образование реализовывался с помощью различных методов и подходов, направленных на создание равных возможностей для всех студентов, независимо от их индивидуальных особенностей.\r\nДля начала, была создана рабочая группа, в которую вошли педагоги, психологи, социальные работники и специалисты по инклюзивному обучению. Вместе они разработали индивидуальные образовательные программы для студентов с особыми образовательными потребностями, учитывая их специфику и потребности.\r\nТакже были проведены специальные тренинги и семинары для педагогов по вопросам инклюзивного образования, чтобы повысить их квалификацию и укрепить понимание важности включения всех студентов в учебный процесс.\r\nТак, например, на базе колледжа Общественное объединение «Кредо» провел семинар на тему «Особенности формирования профессионально-трудовых умений и навыков у подростков с ОВР».  Большую методическую помощь мы получили от сотрудничества с коллективами областных специальных школ-интернатов для детей с нарушением слуха, для детей с нарушением опорно-двигательного аппарата, которые с удовольствием делились опытом работы. \r\nВ рамках проекта также были организованы специальные занятия и мероприятия, направленные на формирование толерантности, взаимоуважения и понимания среди студентов. Благодаря этому проекту, в нашем колледже была создана дружественная атмосфера, где каждый студент чувствовал себя принятым и поддержанным, что способствовало их успешному обучению и развитию.\r\nВ рамках подписанного договора проводилась профориентационная работа среди учащихся спецшкол по таким специальностям как «Лесное хозяйство, садовопарковое и ландшафтное строительство» с квалификацией «Мастер по ландшафтному дизайну», «Декоративно-прикладное искусство и народные промыслы» с квалификациями «Изготовитель художественных изделий из шерсти и кожи», «Заготовщик деталей и материалов к ювелирным изделиям». \r\nПедагоги колледжа вошли в состав экзаменационных комиссий по творческим экзаменам в спецшколах.  В рамках подписанного договора о совместной деятельности, а также с целью обмена опытом практики преподавания, преподаватели колледжа в течении года посещали учебные занятия в школе-интернате г. Караганды для детей с нарушением слуха.\r\nКроме того, в рамках проекта Инклюзивное образование были созданы специализированные адаптированные учебные материалы и методические пособия для студентов с особыми образовательными потребностями. Это помогло им лучше усваивать учебный материал и успешно справляться с учебными заданиями.\r\nВажным компонентом проекта было также обеспечение доступности образовательной среды для всех студентов. Были проведены работы по адаптации учебных помещений, созданию специального оборудования, установке пандусов и других средств для облегчения передвижения студентов с ограниченными возможностями, а также обеспечен доступ к адаптированным технологиям, индивидуальной поддержке специалистов и помощи ассистентов, если это необходимо.\r\nНаш колледж активно сотрудничал и продолжает сотрудничать с региональными и местными организациями, ориентированными на поддержку людей с особыми потребностями. Проводятся совместные мероприятия, обучающие семинары в целях повышения осведомленности общественности в вопросах инклюзивности. \r\nТак, например, ведется тесное сотрудничество с Общественным объединением г. Караганды \"Городское общество глухих \"Қорғау\", объединением юридических лиц «Ассоциация «Гражданский Альянс Карагандинской области», совместно с которыми проводятся различные мероприятия, планируются и проводятся обучающие курсы.\r\nКроме того, педагоги колледжа активно сотрудничают с родителями студентов, обсуждая их потребности и разрабатывая совместные планы поддержки и развития студентов с особыми образовательными потребностями. Такой подход помогал создать синергию усилий и обеспечить максимальную поддержку для каждого студента.\r\nОсобое внимание уделяется работе с талантливыми студентами, в том числе студентами с нарушениями развития. Мы разрабатываем индивидуальные планы развития для каждого студента, помогаем им раскрыть свой творческий потенциал и достигнуть успехов в выбранных областях.\r\nВ настоящее время в колледже активно продолжают работать созданные творческие группы «Театр теней» и «Хор жестового пения», которые выступают с концертами на творческих площадках, участвуют в конкурсах.\r\nСтуденты принимают активное участие в соревнованиях «А𝐛𝐢𝐥𝐢𝐦𝐩𝐢𝐜𝐬» по профессиональному мастерству для людей с инвалидностью и «𝐃𝐞𝐚𝐟𝐬𝐤𝐢𝐥𝐥𝐬» - конкурсе профмастерства для людей с ограниченными возможностями в развитии слуха в рамках национального, международного чемпионатов 𝐖𝐨𝐫𝐥𝐝𝐒𝐤𝐢𝐥𝐥𝐬. Ежегодно студенты колледжа демонстрируют свое мастерство в изготовлении изделий декоративно-прикладного характера - из кожи, дерева, глины, участвовали в компетенциях по художественной керамике, работе с кожей, с витражными красками, с шерстью, бисероплетению, художественной сечке по дереву. \r\nТак, студенты колледжа принимали участие в чемпионате по профессиональному мастерству «𝗔𝗕𝗜𝗟𝗬𝗠𝗣𝗜𝗖𝗦-𝟮𝟬𝟭𝟳» в г. Москве, а затем в международном чемпионате профессионального мастерства для лиц с нарушением слуха «𝗗𝗘𝗔𝗙𝗦𝗞𝗜𝗟𝗟𝗦» чемпионате 𝗪𝗢𝗥𝗟𝗗𝗦𝗞𝗜𝗟𝗟𝗦 𝗔𝗕𝗨-𝗗𝗛𝗔𝗕𝗜-𝟮𝟬𝟭𝟳.\r\nВ 𝟐𝟎𝟏𝟗 году студенты колледжа с особыми образовательными потребностями приняли участие во 𝐈𝐈-ом национальном чемпионате по профессиональному мастерству «𝗗𝗘𝗔𝗙𝗦𝗞𝗜𝗟𝗟𝗦-𝟮𝟬𝟭𝟵», а также во 𝐈𝐈-ом национальном чемпионате по профессиональному мастерству «𝗔𝗕𝗜𝗟𝗬𝗠𝗣𝗜𝗖𝗦-𝟮𝟬𝟭𝟵» в компетенциях живопись, эпоксидная смола, работа с кожей, ювелирно-монтажные работы, где заняли призовые первые места по двум компетенциям.\r\nИнклюзивное образование для нас – это не просто стратегия, но и философия, которая ориентирована на поддержку и включение каждого студента в активную жизнь колледжа. Мы стремимся создать дружественное и поддерживающее обучающее окружение, в котором каждый чувствует себя важным и уважаемым.\r\nВ целом, проект Инклюзивное образование в нашем колледже был успешно реализован благодаря внимательной работе коллектива, готовности к постоянному обучению и развитию, а также стремлению создать дружественную и поддерживающую образовательную среду для всех студентов.', 'и2.jpg', 'IMG_1831.jpg,IMG_2001.jpg,Защита_проектов_ООП_.JPG', '2025-01-05 04:25:38', 'IMG_2001.jpg');

