-- Структура таблицы `projects_lang`
--

CREATE TABLE `projects_lang` (
  `id` int NOT NULL,
  `project_id` int DEFAULT NULL,
  `language` enum('ru','kz','en') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Дамп данных таблицы `projects_lang`
--

INSERT INTO `projects_lang` (`id`, `project_id`, `language`, `name`, `description`) VALUES
(1, 5, 'ru', 'РЕСПУБЛИКАНСКИЙ ПРОЕКТ «ЖАС МАМАН»', 'Карагандинский технико-строительный колледж в 𝟐𝟎𝟏𝟗 году стал одним из участников данного проекта по десяти рабочим профессиям, в том числе по квалификациям из атласа новых профессий. Реализация данного проекта способствовала открытию инновационного Центра компетенций, состоящего из трех самостоятельных блоков, расположенных на 𝟏-ом, 𝟐-ом и 𝟑-м этажах.\r\nВ настоящее время Центр позволяет студентам осваивать современные технологические и производственные процессы, ежегодно быть полноправным участником международных соревнований 𝐖𝐨𝐫𝐥𝐝𝐬𝐤𝐢𝐥𝐥𝐬.\r\nВ рамках вышеназванного проекта колледжу было выделено 𝟑𝟔𝟎 миллионов тенге, благодаря чему приобретено промышленное оборудование, идентичное оборудованию, используемой в современном производстве и 𝐈𝐓-индустрии. Более того, отвечающие самым высоким требованиям, что позволяет вести подготовку специалистов высокого класса, реализовывать пилотные проекты в области строительной индустрии и стартапов в промышленном дизайне.\r\nНа основе данного оборудования созданы новые и модернизированы существующие, в общей сложности 𝟏𝟖 мастерских и 𝟖 лабораторий. Каждый из которых используется по двум, а некоторые по пяти специальностям.\r\nКак известно, в настоящее время в стране активно развивается строительная отрасль, где востребованы специалисты, обладающие навыками работы с новыми материалами, использующие современные архитектурные, дизайнерские и ландшафтные решения, умеющие программировать роботов-строителей, беспилотники летательных аппаратов, создавать архитектурные модели с помощью алгоритмов и кодов, решать вопросы энергоэффективности зданий, обладать высокой визуальной культурой. Это есть - строительство будущего, которому студенты колледжа обучаются именно сейчас и сегодня в нашем учебном заведении.\r\nВ 𝟐𝟎𝟐𝟏 году начата подготовка по совершенно новому направлению – это подготовка специалистов в области Промышленного дизайна. Для этой цели заблаговременно была создана учебная лаборатория Промышленного дизайна, которая оснащена многофункциональным оборудованием Мимаки, позволяющее студентам научиться обслуживать цифровые станки ЧПУ.\r\nЛаборатория и мастерская сварочного дела используются по трем специальностям колледжа. Виртуальный тренажер, рабочие места, 𝟏𝟎 оборудованных кабин с полным комплектом аппаратов – гарантия и успех в подготовке электрогазосварщиков для любой отрасли производства.\r\nЭлектромонтажная лаборатория, полигон, мастерская предназначены для трех специальностей. Здесь же на оборудованиях, приобретенных по проекту Жас маман, проводится обучение участников соревнований 𝐖𝐨𝐫𝐥𝐝𝐬𝐤𝐢𝐥𝐥𝐬 всех учебных заведений Карагандинской области.\r\nДля мастерских столярного дела и мебельного производства приобретены станки и машины с компьютерным управлением, позволяющие изготавливать сложные детали, исключающие появление брака.\r\nМакетное проектирование – есть основа развития профессионального творчества будущих архитекторов, дизайнеров, специалистов декоративно-прикладного искусства и ландшафтного строительства. Новые оборудования мастерских позволяют на стадии разработки проекта получить наглядное представление о принимаемых объемных решениях.\r\nДля всех специальностей, включенных в проект Жас маман, созданы учебная лаборатория спецтехнологии и электротехники, кабинет охраны труда, где студенты на базе оборудования получают знания в области технологии современных отраслей производства, электрической части машин и механизмов, а также приобретают навыки оказания первой медицинской помощи.\r\nС 𝟐𝟎𝟐𝟎 года колледж в качестве итоговой аттестации проводит демонстрационные экзамены по пяти компетенциям, таким как малярные и декоративные работы, кирпичная кладка, облицовка плиткой, сварочные технологии и электромонтаж. Уровень знаний, умений и практических навыков ежегодно оцениваются независимыми экспертами с производства.\r\nРанняя профилизация в колледже начинается с нового учебного года и способствует сознательному, обоснованному выбору школьниками будущей профессии, помогает убедиться в достоинствах и определиться в своих интересах. В связи с чем, профессиональные пробы проводятся по 𝟗 специальностям.\r\nПодписан меморандум с Шахтинской художественной школой, ученики которой ежегодно проходят профессиональные пробы по специальностям: «Дизайн интерьера, реставрация, реконструкция гражданских зданий», «Декоративно- прикладное искусство и народные промыслы, «Архитектура», «Лесное хозяйство, садово-парковое и ландшафтное строительство».\r\nСоздание тренировочного лагеря для участников Ворлдскиллс является одним из результатов проекта Жас маман. Он позволяет повысить качество подготовки участников чемпионатов Ворлдскиллс.\r\nНа базе Центра компетенции ежегодно проводятся региональные чемпионаты Ворлдскиллс по девяти компетенциям: малярные и декоративные работы, кирпичная кладка, облицовка плиткой, сухое строительство и штукатурные работы, сварочные технологии, электромонтаж, флористика, визуальный мерчендайзинг и витринистики и управление беспилотными летательными аппаратами.\r\nБлагодаря условиям, созданных в Центре компетенции, открылись новые творческие кружки, которые в настоящее время работают над выпуском:\r\n- сувенирной продукции;\r\n- продукцией мебельного производства, а также занимаются комплексными решениями дизайна в сфере благоустройства.\r\nОхват студентов по кружкам технического творчества составляет более шестиста человек. Все это способствует безбарьерному вхождению студентов в бизнес-среду.\r\nОснащение мастерских и лабораторий в рамках проекта Жас маман в полном и гарантированном объеме позволяет:\r\n- поднять на новый уровень подготовку специалистов по современным рабочим профессиям и спрос на выпускников колледжа, в том числе на основе расширения связи с казахстанскими и иностранными предприятиями;\r\n- стать тренировочным лагерем по 𝐖𝐨𝐫𝐥𝐝𝐬𝐤𝐢𝐥𝐥𝐬 и заявить о достойных участниках профессиональных соревнований;\r\n- создать условия для безбарьерного вхождения в бизнес-среду;\r\n- быть площадкой по проведению профессиональных проб для школьников;\r\n- осуществлять подготовку и переподготовку безработного населения;\r\n- расширить возможности обучения лиц с особыми образовательными потребностями;\r\n- улучшить качество и доводимость до коммерциализации стартап-проектов;\r\n- повысить престиж рабочей профессии и имидж учебного заведения;\r\n- преподавателям и мастерам производственного обучения проявить стремление к повышению профессионального мастерства.\r\nБезусловно, проект Жас маман был направлен на развитие человеческого капитала, поддержку молодежи в получении качественного образования и востребованной профессии.\r\nВ настоящее время планируется привлечение зарубежных партнеров для обучения преподавателей и мастеров производственного обучения, а также содействия в составлении программ обучения на основе международных стандартов, в том числе стандартов 𝐖𝐨𝐫𝐥𝐝𝐒𝐤𝐢𝐥𝐥𝐬, по заявленным профессиям, что позволит колледжу подготовиться и пройти международную отраслевую аккредитацию. В дальнейшем, наши выпускники будут иметь возможность получить международный сертификат на определенную компетенцию и быть востребованным в любой стране.\r\nТем самым, Центр компетенций, созданный на базе нашего учебного заведения и располагающий новейшим оборудованием, позволил создать собственную модель подготовки рабочих кадров, где особое внимание уделяется развитию стартап проектов, предпринимательской деятельности студентов, а в будущем будет способствовать созданию студенческих малых предприятий по выпуску продукции и оказанию услуг для вхождения колледжа бизнес-среду.'),
(5, 5, 'kz', '«ЖАС МАМАН» РЕСПУБЛИКАЛЫҚ ЖОБАСЫ', 'Қарағанды техника-құрылыс колледжі 2019 жылы осы жобаға он жұмысшы мамандығы бойынша, оның ішінде жаңа кәсіптер атласынан біліктілік бойынша қатысушылардың бірі болды. Бұл жобаны іске асыру 1-ші, 2-ші және 3-ші қабаттарда орналасқан үш дербес блоктан тұратын инновациялық құзыреттілік орталығын ашуға ықпал етті. \r\nҚазіргі уақытта Орталық студенттерге заманауи технологиялық және өндірістік процестерді игеруге, жыл сайын WorldSkills халықаралық жарыстарының толыққанды қатысушысы болуға мүмкіндік береді.\r\nЖоғарыда аталған жоба аясында колледжге 360 миллион теңге бөлінді, соның арқасында қазіргі заманғы өндірісте және IT-индустрияда қолданылатын жабдыққа ұқсас өнеркәсіптік жабдықтар сатып алынды. Сонымен қатар, жоғары деңгейлі мамандарды даярлауға, құрылыс индустриясы саласындағы пилоттық жобаларды және өнеркәсіптік дизайндағы стартаптарды іске асыруға мүмкіндік беретін ең жоғары талаптарға жауап беретін.\r\nОсы жабдықтың негізінде барлығы 18 шеберхана мен 8 зертхана модернизацияланып, жұмыс істеп тұрғандары жаңғыртылды. Олардың әрқайсысы екі, ал кейбіреулері бес мамандық бойынша қолданылады.\r\nӨздеріңіз білетіндей, қазіргі уақытта елде құрылыс индустриясы белсенді дамып келеді. Онда жаңа материалдармен жұмыс істеу дағдылары бар, заманауи сәулет, дизайн және ландшафт шешімдерін қолданатын, робот-құрылысшыларды, ұшқышсыз ұшақтарды бағдарламалауды, алгоритмдер мен кодтардың көмегімен архитектуралық модельдер құруды, ғимараттардың энергия тиімділігі мәселелерін шешуді, жоғары визуальді өнімділік мәдениетіне ие мамандар сұранысқа ие. Бұл-колледж студенттері дәл қазір және бүгін біздің оқу орнында оқитын болашақтың құрылысы.\r\n2021 жылы мүлдем жаңа бағыт бойынша дайындық басталды-бұл өнеркәсіптік дизайн саласындағы мамандарды даярлау. Осы мақсатта студенттерге цифрлық ЧПУ станоктарына қызмет көрсетуді үйренуге мүмкіндік беретін көпфункционалды \"Мимаки\" жабдықтарымен жабдықталған өнеркәсіптік дизайн оқу зертханасы алдын ала құрылды.\r\nДәнекерлеу зертханасы мен шеберханасы колледждің үш мамандығы бойынша қолданылады. Виртуальді тренажер, жұмыс орындары, аппараттардың толық жиынтығы бар 10 жабдықталған кабиналар. Бұл дегеніңіз-өндірістің кез келген саласы үшін электр газбен дәнекерлеушілерді дайындаудағы кепілдік және жетістік.\r\nЭлектрмонтаждау зертханасы, полигон, үш мамандыққа арналған шеберхана. Мұнда Жас маман жобасы бойынша сатып алынған жабдықта Қарағанды облысының барлық оқу орындарының Worldskills жарыстарына қатысушыларды оқыту жүргізіледі.\r\nАғаш ұстасы және жиһаз жасау шеберханалары үшін ақаудың пайда болуын болдырмайтын күрделі бөлшектерді жасауға мүмкіндік беретін компьютермен басқарылатын станоктар мен машиналар сатып алынды.\r\nМакеттік жобалау-болашақ сәулетшілердің, дизайнерлердің, сәндік-қолданбалы өнер және ландшафтық құрылыс мамандарының кәсіби шығармашылығын дамытудың негізі болып табылады. Шеберханалардың жаңа жабдықтары жобаны дайындау кезеңінде қабылданатын көлемді шешімдер туралы көрнекі түсінік алуға мүмкіндік береді.\r\nЖас маман жобасына енгізілген барлық мамандықтар үшін арнайы технологиялар және электротехника оқу зертханасы, еңбекті қорғау кабинеті құрылды, онда жабдықтар базасында студенттер өндірістің қазіргі заманғы салаларының технологиясы, машиналар мен механизмдердің электр бөлігі саласында білім алады, сондай-ақ алғашқы медициналық көмек көрсету дағдыларын игереді.\r\n2020 жылдан бастап колледж кескіндеме және сәндік жұмыстар, кірпіш қалау, плиткамен қаптау, дәнекерлеу технологиясы және электр монтажы сияқты бес құзыреттілік бойынша қорытынды аттестаттау ретінде демонстрациялық емтихандар өткізеді. Білім, білік және практикалық дағдылар деңгейін жыл сайын өндірістен тәуелсіз сарапшылар бағалайды.\r\nКолледжде ерте бейіндеу жаңа оқу жылынан басталады және білім алушылардың болашақ мамандықты саналы, негізделген таңдауына ықпал етеді, қадір-қасиетіне көз жеткізуге және өз мүддесін анықтауға көмектеседі. Осыған байланысты кәсіби сынамалар 9 мамандық бойынша жүргізіледі. \r\nШахтинск көркемсурет мектебімен меморандумға қол қойылды, оның оқушылары жыл сайын «Интерьер дизайны, азаматтық ғимараттарды қалпына келтіру, қайта құру», «Сәндік - қолданбалы өнер және халық кәсіпшілігі», «Сәулет», «Орман шаруашылығы, бақша-саябақ және ландшафт құрылысы» мамандықтары бойынша кәсіби сынамалардан өтеді.\r\nWorldSkills қатысушылары үшін оқу-жаттығу лагерін құру Жас маман жобасының нәтижелерінің бірі болып табылады. Бұл WorldSkills чемпионатына қатысушылардың дайындық сапасын арттыруға мүмкіндік береді. \r\nҚұзыреттілік орталығының базасында жыл сайын тоғыз құзыреттілік бойынша WorldSkills аймақтық чемпионаттары өткізіледі: бояу және сәндік жұмыстар, кірпіш қалау, плиткамен қаптау, құрғақ құрылыс және сылақ жұмыстары, дәнекерлеу технологиялары, электр монтажы, флористика, визуальді сауда және витринистика және ұшқышсыз ұшу аппараттарын басқару. \r\nҚұзыреттілік орталығында құрылған мүмкіндіктердің арқасында қазіргі уақытта қолөнер бұйымдарын дайындайтын жаңа шығармашылық үйірмелер ашылды:\r\n- кәдесый өнімдері;\r\n- жиһаз өндірісінің өнімдерімен, сондай-ақ абаттандыру саласында кешенді дизайн шешімдерімен айналысады.\r\nТехникалық шығармашылық үйірмелері бойынша студенттерді қамту алты жүзден астам адамды құрайды. Мұның бәрі студенттердің бизнес ортаға кедергісіз кіруіне ықпал етеді.\r\nШеберханалар мен зертханаларды толық және кепілдендірілген көлемде жарақтандыру Жас маман жобасы шеңберінде құрылғанға келесі мүмкіндіктерді береді:\r\n- заманауи жұмысшы мамандықтар бойынша мамандар даярлауды және колледж түлектеріне сұранысты, оның ішінде қазақстандық және шетелдік кәсіпорындармен байланысты кеңейту негізінде жаңа деңгейге көтеру;\r\n- WorldSkills бойынша оқу-жаттығу лагеріне айналу және кәсіби жарыстарға лайықты қатысушылар туралы мәлімдеу;\r\n- бизнес-ортаға кедергісіз кіру үшін жағдай жасау;\r\n- білім алушылар үшін кәсіби сынамалар өткізетін алаң болу;\r\n- жұмыссыздарды  даярлауды және қайта даярлауды жүзеге асыру;\r\n- ерекше білім беру қажеттіліктері бар білім алушыларды оқыту мүмкіндіктерін кеңейту;\r\n-стартап-жобалардың сапасы мен коммерциялануына жеткізілуін жақсарту;\r\n- жұмыс кәсібінің беделін және оқу орнының имиджін арттыру;\r\n- оқытушылар мен өндірістік оқыту шеберлеріне кәсіби шеберлікті арттыруға ұмтылу.\r\nӘрине, Жас маман жобасы адами капиталды дамытуға, жастарды сапалы білім алуға және сұранысқа ие мамандыққа қолдауға бағытталған.\r\nҚазіргі уақытта оқытушылар мен өндірістік оқыту шеберлерін оқыту үшін шетелдік серіктестерді тарту, сондай-ақ мәлімделген кәсіптер бойынша халықаралық стандарттар, соның ішінде WorldSkills стандарттары негізінде оқыту бағдарламаларын жасауға жәрдемдесу жоспарлануда, бұл колледжге халықаралық салалық аккредиттеуге дайындалуға және өтуге мүмкіндік береді. Болашақта біздің түлектер белгілі бір құзыретке халықаралық сертификат алуға және кез келген елде сұранысқа ие болуға мүмкіндік алады.\r\nОсылайша, біздің оқу орнымыздың базасында құрылған және жаңа жабдықтары бар құзыреттілік орталығы жұмысшы кадрларды даярлаудың өзіндік моделін құруға мүмкіндік берді, онда стартап жобаларды, студенттердің кәсіпкерлік қызметін дамытуға ерекше назар аударылады. Ал болашақта колледждің бизнес-ортаға кіруі үшін өнім шығару және қызмет көрсету бойынша студенттік шағын кәсіпорындарды құруға ықпал ететін болады. \r\n\r\n'),
(6, 5, 'en', 'REPUBLICAN PROJECT \"ZHAS MAMAN\"', 'In 2018, Karaganda Technical and Construction College became one of the participants in this project in ten blue-collar jobs, including qualifications from the atlas of new jobs. The implementation of this project contributed to the opening of an innovative Competence Center, consisting of three independent blocks located on the 2nd, 3rd and 4th floors.\r\nCurrently, the Center allows students to master modern technological and production processes, and annually be a full participant in international competitions 2018-2019. Within the framework of the above-mentioned project, the college was allocated 𝟑𝟔𝟎 million tenge, thanks to which industrial equipment identical to the equipment used in modern production and the 𝐈𝐓 industry was purchased. Moreover, it meets the highest requirements, which allows training high-class specialists, implementing pilot projects in the field of construction industry and start-ups in industrial design. Based on this equipment, new and modernized existing, a total of 𝟏𝟖 workshops and 𝟖 laboratories. Each of which is used for two, and some for five specialties. As you know, the construction industry is currently actively developing in the country, where specialists with skills in working with new materials, using modern architectural, design and landscape solutions, who can program construction robots, unmanned aerial vehicles, create architectural models using algorithms and codes, solve issues of energy efficiency of buildings, and have a high visual culture are in demand. This is the construction of the future, which college students are studying right now and today in our educational institution. In 2018, training began in a completely new direction - this is the training of specialists in the field of Industrial Design. For this purpose, an educational laboratory of Industrial Design was created in advance, which is equipped with multifunctional Mimaki equipment, allowing students to learn how to service digital CNC machines. The laboratory and welding workshop are used in three specialties of the college. A virtual simulator, workplaces, 𝟏𝟎 equipped cabins with a full set of devices are a guarantee and success in training electric and gas welders for any industry.\r\nAn electrical installation laboratory, a training ground, and a workshop are designed for three specialties. Here, on the equipment purchased under the Zhas Maman project, training is conducted for participants in the 𝐖𝐨𝐫𝐥𝐝𝐬𝐤𝐢𝐥𝐥𝐬 competitions of all educational institutions of the Karaganda region.\r\nFor carpentry and furniture workshops, computer-controlled machines and machines have been purchased that allow the production of complex parts that eliminate the occurrence of defects.\r\nModel design is the basis for the development of professional creativity of future architects, designers, specialists in decorative and applied arts and landscape construction. New workshop equipment allows for a visual representation of the volumetric decisions being made at the project development stage. For all specialties included in the Zhas Maman project, a training laboratory of special technology and electrical engineering, an occupational safety room have been created, where students, using the equipment, gain knowledge in the field of technology of modern industries, the electrical part of machines and mechanisms, and also acquire first aid skills.\r\nSince 2018, the college has been conducting demonstration exams in five competencies as a final certification, such as painting and decorative work, bricklaying, tiling, welding technology and electrical installation. The level of knowledge, skills and practical skills are annually assessed by independent experts from production.\r\nEarly profiling in the college begins with the new academic year and contributes to a conscious, informed choice of a future profession by schoolchildren, helps to be convinced of the merits and determine their interests. In this regard, professional tests are held in 𝟗 specialties. A memorandum was signed with the Shakhty Art School, whose students annually undergo professional tests in the following specialties: \"Interior design, restoration, reconstruction of civil buildings\", \"Decorative and applied arts and folk crafts, \"Architecture\", \"Forestry, gardening and landscape construction\".\r\nThe creation of a training camp for WorldSkills participants is one of the results of the Zhas Maman project. It allows improving the quality of training of participants in WorldSkills championships.\r\nThe Competence Center annually hosts regional WorldSkills championships in nine competencies: painting and decorative work, bricklaying, tiling, dry construction and plastering, welding technologies, electrical installation, floristry, visual merchandising and window dressing, and control of unmanned aerial vehicles.'),
(7, 6, 'ru', 'ПРОЕКТ «ИНКЛЮЗИВНОЕ ОБРАЗОВАНИЕ».  НАЦИОНАЛЬНЫЙ ЧЕМПИОНАТ ABILYMPICS', '<p>Карагандинский технико-строительный колледж с сентября 2014 года в экспериментальном режиме начал работу со студентами, ограниченных в возможностях развития, а именно ограниченных в развитии слуха и речи, в нарушении опорно-двигательного аппарата.</p>\r\n\r\n<p>Предварительно было проведено анкетирование среди педагогов колледжа и обучающихся на определение уровня восприятия данного проекта. Выяснилось, что 40% педагогам интересны вопросы инклюзивного обучения, 35% выразили сомнение в достаточной изученности данной проблемы в ТиПО, 25% инженерно-педагогических работников отрицали возможность участия в проекте. Приблизительно таковыми были и ответы студентов колледжа.</p>\r\n\r\n<p>Проект Инклюзивное образование реализовывался с помощью различных методов и подходов, направленных на создание равных возможностей для всех студентов, независимо от их индивидуальных особенностей.</p>\r\n\r\n<p>Для начала, была создана рабочая группа, в которую вошли педагоги, психологи, социальные работники и специалисты по инклюзивному обучению. Вместе они разработали индивидуальные образовательные программы для студентов с особыми образовательными потребностями, учитывая их специфику и потребности.</p>\r\n\r\n<p>Также были проведены специальные тренинги и семинары для педагогов по вопросам инклюзивного образования, чтобы повысить их квалификацию и укрепить понимание важности включения всех студентов в учебный процесс.</p>\r\n\r\n<p>Так, например, на базе колледжа Общественное объединение &laquo;Кредо&raquo; провел семинар на тему &laquo;Особенности формирования профессионально-трудовых умений и навыков у подростков с ОВР&raquo;.&nbsp; Большую методическую помощь мы получили от сотрудничества с коллективами областных специальных школ-интернатов для детей с нарушением слуха, для детей с нарушением опорно-двигательного аппарата, которые с удовольствием делились опытом работы.</p>\r\n\r\n<p>В рамках проекта также были организованы специальные занятия и мероприятия, направленные на формирование толерантности, взаимоуважения и понимания среди студентов. Благодаря этому проекту, в нашем колледже была создана дружественная атмосфера, где каждый студент чувствовал себя принятым и поддержанным, что способствовало их успешному обучению и развитию.</p>\r\n\r\n<p>В рамках подписанного договора проводилась профориентационная работа среди учащихся спецшкол по таким специальностям как &laquo;Лесное хозяйство, садовопарковое и ландшафтное строительство&raquo; с квалификацией &laquo;Мастер по ландшафтному дизайну&raquo;, &laquo;Декоративно-прикладное искусство и народные промыслы&raquo; с квалификациями &laquo;Изготовитель художественных изделий из шерсти и кожи&raquo;, &laquo;Заготовщик деталей и материалов к ювелирным изделиям&raquo;.</p>\r\n\r\n<p>Педагоги колледжа вошли в состав экзаменационных комиссий по творческим экзаменам в спецшколах. &nbsp;В рамках подписанного договора о совместной деятельности, а также с целью обмена опытом практики преподавания, преподаватели колледжа в течении года посещали учебные занятия в школе-интернате г. Караганды для детей с нарушением слуха.</p>\r\n\r\n<p>Кроме того, в рамках проекта Инклюзивное образование были созданы специализированные адаптированные учебные материалы и методические пособия для студентов с особыми образовательными потребностями. Это помогло им лучше усваивать учебный материал и успешно справляться с учебными заданиями.</p>\r\n\r\n<p>Важным компонентом проекта было также обеспечение доступности образовательной среды для всех студентов. Были проведены работы по адаптации учебных помещений, созданию специального оборудования, установке пандусов и других средств для облегчения передвижения студентов с ограниченными возможностями, а также обеспечен доступ к адаптированным технологиям, индивидуальной поддержке специалистов и помощи ассистентов, если это необходимо.</p>\r\n\r\n<p>Наш колледж активно сотрудничал и продолжает сотрудничать с региональными и местными организациями, ориентированными на поддержку людей с особыми потребностями. Проводятся совместные мероприятия, обучающие семинары в целях повышения осведомленности общественности в вопросах инклюзивности.</p>\r\n\r\n<p>Так, например, ведется тесное сотрудничество с Общественным объединением г. Караганды &quot;Городское общество глухих &quot;Қорғау&quot;, объединением юридических лиц &laquo;Ассоциация &laquo;Гражданский Альянс Карагандинской области&raquo;, совместно с которыми проводятся различные мероприятия, планируются и проводятся обучающие курсы.</p>\r\n\r\n<p>Кроме того, педагоги колледжа активно сотрудничают с родителями студентов, обсуждая их потребности и разрабатывая совместные планы поддержки и развития студентов с особыми образовательными потребностями. Такой подход помогал создать синергию усилий и обеспечить максимальную поддержку для каждого студента.</p>\r\n\r\n<p>Особое внимание уделяется работе с талантливыми студентами, в том числе студентами с нарушениями развития. Мы разрабатываем индивидуальные планы развития для каждого студента, помогаем им раскрыть свой творческий потенциал и достигнуть успехов в выбранных областях.</p>\r\n\r\n<p>В настоящее время в колледже активно продолжают работать созданные творческие группы &laquo;Театр теней&raquo; и &laquo;Хор жестового пения&raquo;, которые выступают с концертами на творческих площадках, участвуют в конкурсах.</p>\r\n\r\n<p>Студенты принимают активное участие в соревнованиях &laquo;Аbilimpics&raquo; по профессиональному мастерству для людей с инвалидностью и &laquo;Deafskills&raquo; - конкурсе профмастерства для людей с ограниченными возможностями в развитии слуха в рамках национального, международного чемпионатов WorldSkills. Ежегодно студенты колледжа демонстрируют свое мастерство в изготовлении изделий декоративно-прикладного характера - из кожи, дерева, глины, участвовали в компетенциях по художественной керамике, работе с кожей, с витражными красками, с шерстью, бисероплетению, художественной сечке по дереву.</p>\r\n\r\n<p>Так, студенты колледжа принимали участие в чемпионате по профессиональному мастерству &laquo;ABILYMPICS-2017&raquo; в г. Москве, а затем в международном чемпионате профессионального мастерства для лиц с нарушением слуха &laquo;DEAFSKILLS&raquo; чемпионате WORLDSKILLS ABU-DHABI-2017.</p>\r\n\r\n<p>В 2019 году студенты колледжа с особыми образовательными потребностями приняли участие во II-ом национальном чемпионате по профессиональному мастерству &laquo;DEAFSKILLS-2019&raquo;, а также во II-ом национальном чемпионате по профессиональному мастерству &laquo;ABILYMPICS-2019&raquo; в компетенциях живопись, эпоксидная смола, работа с кожей, ювелирно-монтажные работы, где заняли призовые первые места по двум компетенциям.</p>\r\n\r\n<p>Инклюзивное образование для нас &ndash; это не просто стратегия, но и философия, которая ориентирована на поддержку и включение каждого студента в активную жизнь колледжа. Мы стремимся создать дружественное и поддерживающее обучающее окружение, в котором каждый чувствует себя важным и уважаемым.</p>\r\n\r\n<p>В целом, проект Инклюзивное образование в нашем колледже был успешно реализован благодаря внимательной работе коллектива, готовности к постоянному обучению и развитию, а также стремлению создать дружественную и поддерживающую образовательную среду для всех студентов.</p>\r\n\r\n<p>&nbsp;</p>\r\n'),
(8, 6, 'kz', '\"ИНКЛЮЗИВТІ БІЛІМ БЕРУ\" ЖОБАСЫ.  ABILYMPICS ҰЛТТЫҚ ЧЕМПИОНАТЫ', 'Қарағанды техника-құрылыс колледжі 2014 жылдың қыркүйегінен бастап эксперименттік режимде даму мүмкіндіктері шектеулі, атап айтқанда есту және сөйлеу қабілеті шектеулі, тірек-қимыл аппараты бұзылған студенттермен жұмысты бастады.\r\nКолледж педагогтары мен білім алушылар арасында осы жобаны қабылдау деңгейін анықтау үшін алдын ала сауалнама жүргізілді. Педагогтардың 40%-ы инклюзивті оқыту мәселелеріне қызығушылық танытқаны, 35% - ы ТжКБ-да осы проблеманы жеткілікті түрде зерделеуге күмән келтіргені, инженерлік-педагогикалық қызметкерлердің 25% - ы жобаға қатысу мүмкіндігін жоққа шығарғаны анықталды. Колледж студенттерінің жауаптары да осындай болды. \r\nИнклюзивті білім беру жобасы барлық студенттерге, олардың жеке ерекшеліктеріне қарамастан, тең мүмкіндіктер жасауға бағытталған әртүрлі әдістер мен тәсілдер арқылы жүзеге асырылды.\r\nЕң алдымен жұмыс тобы құрылды, оның құрамына педагогтер, психологтер, әлеуметтік қызметкерлер және инклюзивті оқыту мамандары кірді. Олар біріге отырып ерекше білім беру қажеттіліктері бар студенттерге олардың ерекшеліктері мен қажеттіліктерін ескере отырып, жеке білім беру бағдарламаларын жасады.\r\nСондай-ақ олардың біліктілігін арттыру және барлық студенттерді оқу процесіне қосудың маңыздылығын түсінуді нығайту үшін педагогтарға инклюзивті білім беру мәселелері бойынша арнайы тренингтер мен семинарлар өткізілді.\r\nМәселен, колледж базасында \"Кредо\" қоғамдық бірлестігі \"Мүмкіндігі шектеулі жасөспірімдердің кәсіби-еңбек дағдылары мен танымдарын қалыптастыру ерекшеліктері\" тақырыбында семинар өткізді.  Біз есту қабілеті бұзылған балаларға, тірек-қимыл аппараты бұзылған балаларға арналған облыстық арнайы мектеп-интернаттар ұжымдарымен ынтымақтастықтан үлкен әдістемелік көмек алдық, олар жұмыс тәжірибесімен қуана бөлісті. \r\nЖоба аясында студенттер арасында толеранттылықты, өзара сыйластық пен түсіністікті қалыптастыруға бағытталған арнайы сабақтар мен іс-шаралар ұйымдастырылды. Осы жоба арқылы біздің колледжде достық атмосфера құрылды, онда әрбір студент өзін жақсы қабылдады және қолдады, бұл олардың табысты оқуы мен дамуына ықпал етті.\r\nҚол қойылған шарт шеңберінде арнайы мектептердің оқушылары арасында \"Орман шаруашылығы, бау-бақша және ландшафтық құрылыс\" мамандығының \"Ландшафтық дизайн  шебері\", \"Сәндік-қолданбалы өнер және халық кәсіпшілігі\" , \"Жүн мен былғарыдан көркем бұйымдар жасаушы\", \"Зергерлік бұйымдарға бөлшектер мен материалдарды дайындаушы\" сияқты біліктіліктерімен кәсіптік бағдар беру жұмыстары жүргізілді. \r\nКолледж педагогтары арнайы мектептердегі шығармашылық емтихандар бойынша емтихан комиссияларының құрамына кірді.  Бірлескен қызмет туралы қол қойылған шарт шеңберінде, сондай-ақ оқыту практикасында тәжірибе алмасу мақсатында колледж оқытушылары жыл бойы есту қабілеті бұзылған балаларға арналған Қарағанды қаласының мектеп-интернатында оқу сабақтарына қатысты.\r\nСонымен қатар, инклюзивті білім беру жобасы ерекше білім беру қажеттіліктері бар студенттерге арналған арнайы бейімделген оқу материалдары мен әдістемелік құралдарды жасады. Бұл оларға оқу материалын жақсы меңгеруге және оқу тапсырмаларын сәтті орындауға көмектесті.\r\nЖобаның маңызды құрамдас бөлігі барлық студенттер үшін білім беру ортасының қолжетімділігін қамтамасыз ету болды. Оқу баспаналарын бейімдеу, арнайы жабдықтар жасау, мүмкіндігі шектеулі студенттердің қозғалысын жеңілдету үшін пандустар мен басқа да құралдарды орнату бойынша жұмыстар жүргізілді, сондай-ақ бейімделген технологияларға қол жеткізу, мамандардың жеке қолдауы және қажет болған жағдайда ассистенттердің көмегі қамтамасыз етілді.\r\nБіздің колледж ерекше қажеттіліктері бар адамдарды қолдауға бағытталған аймақтық және жергілікті ұйымдармен белсенді жұмыс істеді және ынтымақтастықты жалғастыруда. Инклюзивтілік мәселелерінде жұртшылықтың хабардарлығын арттыру мақсатында бірлескен іс-шаралар, оқыту семинарлары өткізіледі. \r\nМәселен, мысалы, Қарағанды қаласының \"Қорғау \"Қалалық саңыраулар қоғамы\" қоғамдық бірлестігімен, \"Қарағанды облысының Азаматтық Альянсы \"Қауымдастығы\" заңды тұлғалар бірлестігімен тығыз ынтымақтастық жүргізілуде, олармен бірлесіп түрлі іс-шаралар өткізіледі, оқыту курстары жоспарланады және өткізіледі.\r\nСонымен қатар, колледж мұғалімдері студенттердің ата-аналарымен белсенді түрде жұмыс істейді, олардың қажеттіліктерін талқылайды және ерекше білім беру қажеттіліктері бар студенттерді қолдау мен дамытудың бірлескен жоспарларын жасайды. Бұл тәсіл күш-жігердің синергиясын құруға және әр студентке барынша қолдау көрсетуге көмектесті.\r\nДарынды студенттермен, оның ішінде даму кемістігі бар студенттермен жұмыс істеуге ерекше назар аударылады. Біз әр студент үшін жеке даму жоспарларын жасаймыз, олардың шығармашылық қабілеттерін ашуға және таңдалған салаларда жетістіктерге жетуге көмектесеміз.\r\nҚазіргі уақытта колледжде құрылған \"Көлеңкелер театры\" және \"Ыммен ән айту хоры\" шығармашылық топтары белсенді жұмыс істеуде, олар шығармашылық алаңдарда концерттермен өнер көрсетеді, конкурстарға қатысады.\r\nСтуденттер мүгедектігі бар адамдарға арналған кәсіби шеберлік бойынша \"Аbilimpics\" жарысына және WorldSkills Ұлттық, халықаралық чемпионаттары шеңберінде есту қабілетін дамытуда мүмкіндіктері шектеулі адамдарға арналған \"Deafskills\" кәсіби шеберлік байқауына белсенді қатысады. Жыл сайын колледж студенттері сәндік-қолданбалы сипаттағы бұйымдарды - былғарыдан, ағаштан, саздан жасауда өз шеберліктерін көрсетеді, көркем керамика, былғарымен жұмыс, витраж бояуларымен, жүнмен, бисермен, ағаш бойынша көркемдік секция бойынша құзыреттіліктерге қатысты. \r\nСонымен, колледж студенттері Мәскеу қаласында өткен \"ABILYMPICS-2017\" кәсіби шеберлік чемпионатына, содан кейін WORLDSKILLS Abu-DHABI-2017 \"Deafskills\" есту қабілеті бұзылған тұлғалар үшін халықаралық кәсіби шеберлік чемпионатына қатысты.\r\n2019 жылы ерекше білім беру қажеттіліктері бар колледж студенттері \"DEAFSKILLS-2019\" кәсіптік шеберлік бойынша II Ұлттық чемпионатқа, сондай-ақ \"ABILYMPICS-2019\" кәсіптік шеберлік бойынша ІІ Ұлттық чемпионатқа сурет салу, эпоксидті шайыр, былғарымен жұмыс, зергерлік-монтаждау жұмыстарына қатысты, онда екі құзырет бойынша жүлделі бірінші орын алды.\r\nБіз үшін инклюзивті білім беру-бұл тек стратегия ғана емес, сонымен қатар әр студентті колледждің белсенді өміріне қолдауға және қосуға бағытталған философия. Біз әркім өзін маңызды және құрметті сезінетін достық және қолдау көрсететін оқу ортасын құруға тырысамыз.\r\nЖалпы, біздің колледжде инклюзивті білім беру жобасы ұжымның мұқият жұмысының, тұрақты оқуға және дамуға дайындығының, сондай-ақ барлық студенттер үшін достық және қолдау көрсететін білім беру ортасын құруға ұмтылысының арқасында сәтті іске асырылды.\r\n\r\n\r\n\r\n\r\n');

