INSERT INTO `students` (`id`, `name`, `group_name`, `achievements`, `image`, `created_at`, `updated_at`) VALUES
(5, 'Канаткызы Жаннур', 'Архитектура.', '[\"Областной дебатный турнир сруди студентов, 1 место.\", \"Призер в областном конкурсе «Қазақ сахарасының қоңырауы» по направлению «Степная звезда», посвященное 180-летию Ибрая Алтынсарина, 2 место.\"]', '1.jpg', '2025-01-05 06:09:49', '2025-01-05 06:09:49'),
(6, 'Абдрашит Зере', 'Архитектура', '[\"Абайтану 2022-2023 «Образ Абая», организованный республиканским журналом «Мурагер» 1 место. \", \"2-ой городской дебатный конкурс среди студентов организаций технического и профессионального образования «ЛУЧШИЙ СПИКЕР».\"]', '2.jpg', '2025-01-05 06:50:15', '2025-01-05 06:50:15'),
(7, 'Егинбаев Адилет', 'Архитектура', '[\"Фестиваль лиги «Магнитка» сезон 2023 г. Команда «Нам пара», 1 место.\", \"Чемпионат Юниор лиги Карагандинского КВН сезона 2022-2023 учебного года, 3 место.\", \"Кубок Акима Карагандинской области среди студентов, 1 место.\", \"Благодарственное письмо за участие в семинаре-тренинге по подготовке молодежных лидеров с целью создания волонтерского движения для работы по принципу «Тең-тең».\", \"«Мисс КВН» в игре клуба веслых и находчивых за кубок Акима Карагандинской области среди студентов.\", \"«Зимний Кубок» Юниор лиги Карагандинского КВН, 2 место.\", \"Благодарственное письмо за участие в областном дебатном турнире среди студентов колледжей, посвященном 30-летию национальной валюты Республики Казахстан.\", \"Благодарственное письмо Кубок Акима Карагандинской области среди студентов.\"]', 'Picture1.jpg', '2025-01-05 14:08:24', '2025-01-05 14:08:24'),
(8, 'Иртаева Еркеайым ', 'Дизайн интерьера, реставрация, реконструкция   гражданских зданий.', '[\"Областной дебатный турнир среди студентов колледжей Карагандинской области, 2 место.\", \"Областной конкурс «Dance City», 3 место.\", \"Интеллектуальная игра «Правоведы» среди студентов колледжей Карагандинской области, 2 место.\", \"Президент парламента «Жігер» в колледже.\", \"Международный музыкальный конкурс «THE PLANET OF ART-2023», сертификат.\"]', 'Picture2.jpg', '2025-01-05 14:11:01', '2025-01-05 14:11:01'),
(9, 'Селиванов Александр ', 'Дизайн интерьера, реставрация, реконструкция гражданских зданий.', '[\"Открытый Чемпионат Юниор лиги КВН г.Караганды, 3 место.\", \"Интеллектуальная игра «Что? Где? Когда?» в рамках молодежного фестиваля «Upgrade», посвященного 30-летию Независимости Республики Казахстан среди студентов Карагандинской области, диплом 3 степени.\", \"Областной конкурс среди студентов на лучшую рекламную компанию по продвижению выбранной книги «Book Slam», 1 место.\", \"Конкурс «Знаток финансов» среди студентов колледжей Карагандинской области, сертификат.\", \"Номинация: Лучший актер в Осеннем кубке юниор лиги КВН Карагандинской области, диплом.\", \"XI Областной студенческий фестиваль национальных культур, посвященный Дню Независимости Республики Казахстан и 100-летию Саранского гуманитарно-технического колледжа имени Абая Кунанбаева «Песню дружбы запевает молодежь», сертификат.\"]', 'Picture3.jpg', '2025-01-05 14:15:04', '2025-01-05 14:20:41'),
(10, 'Шин Элина', 'Дизайн интерьера, реставрация, реконструкция гражданских зданий.', '[\"Викторина, приуроченная Дню национальной валюты среди студентов колледжей Карагандинской области, 1 место.\", \"Соревнования по настольному теннису среди студентов колледжей Карагандинской области, 2 место.\", \"Соревнования по баскетболу, среди студентов – девушек Карагандинской области, 1 место.\", \"Соревнования по футболу среди студентов-девушек колледжей Карагандинской области, 1 место.\", \"В 2022 году вошла в ТОП – 100 студентов колледжей Республики Казахстан.\"]', 'Picture4.jpg', '2025-01-05 14:23:19', '2025-01-05 14:23:19'),
(11, 'Ботабаева Алия', 'Архитектура.', '[\"Международный творческий конкурс – выставка на тему: «Мой город – моя вселенная», посвященный Дню Независимости РК, номинация «Декоративно-прикладное искусство», диплом 1 степени.\", \"Областной конкурс по созданию макетов достопримечательностей Казахстана «Гүлдене бер, Қазақстан», посвященный 30-летию Независимости Республики Казахстан, Диплом победителя в номинации «Сакральные объекты Казахстана», денежный сертификат на сумму 85 000 тенге.\", \"Соревнование по футболу среди студентов-девушек колледжей Карагандинской области, 1 место.\"]', 'Picture5.jpg', '2025-01-05 14:24:00', '2025-01-05 14:24:00'),
(12, 'Шаметова Сабина', 'Дизайн интерьера, реставрация, реконструкция гражданских зданий.', '[\"Проведение патриотических мероприятий, посвященных 33-летию вывода Советских войск из Афганистана, благодарственное письмо.\", \"Областной конкурс по военному троеборью среди студентов колледжей Карагандинской области, посвященный 31-летию Независимости РК, 3 место.\", \"Областной конкурс рисунков «Образ моей мамы» среди студентов колледжей Карагандинской области, сертификат.\", \"Областная олимпиада по архитектуре среди студентов колледжей и школ, посвященная 70-летию КарТУ имени А.Сагинова, 2 место.\", \"Областной конкурс «Жас Шебер», номинация «Художественная обработка материала», 3 место.\"]', 'Picture6.jpg', '2025-01-05 14:35:23', '2025-01-05 14:35:23'),
(13, 'Шваб Милана Дмитриевна', 'Системы информационной безопасности.', '[\"Мастер спорта Республики Казахстан.\", \"Бронзовый призер IV Летней Спартакиады Республики Казахстан\", \"Чемпион Республики Казахстан в командных упражнениях.\", \"Чемпионат по батутной гимнастике, 2 место.\", \"Чемпионат  г.Караганды по акробатике среди возрастных групп, 1 место.\", \"Победитель номинации по итогам 2022 года «Наша надежда», диплом Федерации гимнастики Карагандинской области.\", \"Чемпионат Республики Казахстан по батутной гимнастике среди молодёжи, 2 место.\", \"\"]', 'Picture7.jpg', '2025-01-05 14:36:29', '2025-01-06 12:03:34'),
(14, 'Сәмен Ернұр Серікбайұлы', 'Сварочное дело.', '[\"Областной фестиваль афганской песни «Сердцем причастны…» среди студентов колледжей Карагандинской области, 1 место.\", \"Участие в региональных XIV Национальных Дельфийских играх Республики Казахстан.\", \"Участие в международном фестивале творчества молодых людей с ограниченными возможностями «Восточная сказка», г. Баку, Азербайджан.\"]', 'Picture8.jpg', '2025-01-05 14:37:24', '2025-01-05 14:37:24'),
(15, 'Камалдинов Евгений Анатольевич', 'Системы информационной безопасности.', '[\"Областное мероприятие «Хакатон – начало программирования» - 1 место.\", \"Участие в региональном WorldSkills по компетенции «Мобильная робототехника», 3 место.\", \"Оказывает содействие по программному обеспчению колледжа в сопровождении программ для внутреннего использования, установке и ремонте технических средств.\"]', 'Picture9.jpg', '2025-01-05 14:37:56', '2025-01-05 14:37:56'),
(16, 'Әбенов Бекнияз Болатұлы', 'Системы информационной безопасности.', '[\"Президент колледжа КГКП «КТСК» в 2022-2023гг.\", \"Участник облстнного дебатного турнира среди студентов «Ұшқыр ой алаңы» - сертификат\", \"Участник областного конкурса видеороликов «Ауылым-алтын бесігім», приуроченный к 30-летию Независимости Республики Казахстан, диплом 3 место.\", \"Участник  научно-практической конференции «Ә.Бөкейхан – ұлы мұрат жолындағы қолбасшы» - сертификат.\", \"Участник областного турнира «Үздік спикер», диплом.\", \"Участник областного дебатного турнира среди студентов, диплом 1 место.\"]', 'Picture10.jpg', '2025-01-05 14:38:46', '2025-01-05 14:38:46'),
(17, 'Сидикова Акмарал', 'Дизайн интерьера, реставрация, реконструкция гражданских зданий.', '[\"Областная научно-практическая конференция среди преподавателей и студентов колледжей Карагандинской области по теме «Взгляд в будущее: модернизация общественного сознания», посвященная реализации программы «Рухани Жаңғыру», сертификат\", \"Акция «Полевая почта», 1 место, денежная премия 20000 тг.\", \"Международная конференция исследовательских и проектных работ студентов «Архитектура. Строительство. Реставрация.21 век», 2 место.\", \"Программа Предпринимательства «Momentum», сертификат.\", \"I Областной чемпионат профессионального мастерства «AgroSkills» среди студентов организаций ТиПО, компетенция «Цифровое земледелие», 3 место.\", \"Конкурс профессионального мастерства по направлению «Графический дизайн» в рамках ОМО «Связь, телекоммуникации и IT-технологии», сертификат.\"]', 'blank-profile-picture-973460_1280.png', '2025-01-05 14:40:53', '2025-01-05 14:40:53'),
(18, 'Байгошкарова Дана', 'Дизайн интерьера, реставрация, реконструкция гражданских зданий.', '[\"Республиканский дистанционный конкурс в номинациях: «Молодой художник», «Молодой писатель», 1 место.\", \"Международный творческий конкурс–выставка на тему: «Мой город – моя вселенная», посвященный Дню Независимости РК, номинация «Живопись», 1 место.\", \"Национальный чемпионат профмастерства «Worldskills Kazakhstan-2021», 1 место.\", \"Международный чемпионат «EuroSkills - 2023», сертификат.\"]', 'blank-profile-picture-973460_1280.png', '2025-01-05 14:41:47', '2025-01-05 14:41:47'),
(19, 'Смирнова Анастасия', 'Дизайн интерьера, реставрация, реконструкция гражданских зданий.', '[\"Региональный конкурс профессионального мастерства WorldSkills-2022, компетенция «Флористика», 1 место.\", \"Республиканский конкурс профессионального мастерства WorldSkills-2022, компетенция «Флористика», 1 место.\", \"Международный конкурс EuroSkills–2023 по компетенции «Флористика», благодарственное письмо.\"]', 'blank-profile-picture-973460_1280.png', '2025-01-05 14:42:17', '2025-01-05 14:42:17'),
(20, 'Ишина Ева', 'Архитектура.', '[\"I Областной чемпионат профессионального мастерства «AgroSkills» среди студентов организаций ТиПО, компетенция «Планировочное решение в строительстве», 1 место.\", \"Международный творческий конкурс–выставка на тему: «Мой город – моя вселенная», посвященный Дню Независимости РК, номинация «Графика», Диплом – Гран – При.\", \"Областной конкурс по созданию макетов достопримечательностей Казахстана «Гүлдене бер, Қазақстан», посвященный 30-летию Независимости Республики Казахстан, диплом победителя в номинации «Сакральные объекты Казахстана», денежный сертификат на сумму 85 000 тенге.\"]', 'empty_profile.png', '2025-01-05 14:43:38', '2025-01-05 14:43:38'),
(21, 'Сеилов Рустем', 'Архитектура.', '[\"Международная конференция исследовательских и проектных работ студентов «Архитектура. Строительство. Реставрация.21 век», 1 место.\", \"Международный творческий конкурс–выставка на тему: «Мой город – моя вселенная», посвященный Дню Независимости РК, номинация «Декоративно-прикладное искусство», диплом 1 степени.\", \"I Областной чемпионат профессионального мастерства «AgroSkills» среди студентов организаций ТиПО, компетенция «Планировочное решение в строительстве», сертификат.\", \"II Областная студенческая ярмарка готовых изделий «От студенческого хобби до успешного бизнеса», сертификат.\", \"Областной конкурс по созданию макетов достопримечательностей Казахстана «Гүлдене бер, Қазақстан», посвященный 30-летию Независимости Республики Казахстан, диплом победителя в номинации «Сакральные объекты Казахстана», денежный сертификат на сумму 85 000 тенге.\"]', 'empty_profile.png', '2025-01-05 14:44:22', '2025-01-05 14:44:22'),
(22, 'Васильев Сергей', 'Архитектура.', '[\"Военно-исторические реконструкции: «Бой под Понырями», «О героях былых времен», сертификат.\", \"Региональный конкурс профессионального мастерства WorldSkills-2022, компетенция «Управление беспилотными летательными аппаратами» 2 место.\", \"Открытый Чемпионат г.Караганда по «Ашихара Карате», 2 место.\", \"Бизнес–инкубатор «Терриконовая долина», сертификат.\", \"Активное участие в проведении патриотического мероприятия «О героях былых времен», посвященное 100-летию Героя Советского Союза М.Маметовой, благодарственное письмо.\"]', 'empty_profile.png', '2025-01-05 14:45:15', '2025-01-05 14:45:15'),
(23, 'Дәуренбек Айша', 'Дизайн интерьера, реставрация, реконструкция гражданских зданий.', '[\"Областная олимпиада по архитектуре среди студентов колледжей и школ, посвященная 70-летию КарТУ имени А.Сагинова, 1 место.\", \"Соревнования по шахматам, среди студентов Карагандинской области, 3 место.\", \"Соревнования по настольному теннису среди студентов колледжей Карагандинской области, 2 место.\", \" Областные соревнования по шахматам І, ІІ-дивизион среди девушек колледжей, диплом «Лучший игрок».\"]', 'empty_profile.png', '2025-01-05 14:46:42', '2025-01-05 14:46:42'),
(24, 'Мальцева Елена', 'Дизайн интерьера.', '[\"Областной фестиваль афганской песни «Сердцем причастны…» среди студентов колледжей Карагандинской области, сертификат.\", \"Интеллектуальная игра «Что? Где? Когда?» в рамках молодежного фестиваля «Upgrade», посвященного 30-летию Независимости Республики Казахстан среди студентов Карагандинской области, диплом 3 степени.\", \"Областной конкурс «Жас Шебер», номинация «Живопись», сертификат.\"]', 'empty_profile.png', '2025-01-05 14:47:15', '2025-01-05 14:47:15'),
(25, 'Бугутаев Мадияр', 'Декоративно – прикладное искусство и народные промыслы.', '[\"Областной фестиваль «Ел жүрегі - Астана», 2 место.\", \"Вторые Международные Парадельфийские игры, сертификат.\", \"Областной молодежный инновационный форум-фестиваль «Жауыртаудағы кездесу», диплом.\"]', 'empty_profile.png', '2025-01-05 14:47:40', '2025-01-05 14:47:40');

