--
-- Структура таблицы `teachers`
--

CREATE TABLE `teachers` (
  `id` int NOT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `education` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `works_in_college` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `position` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Дамп данных таблицы `teachers`
--

INSERT INTO `teachers` (`id`, `name`, `description`, `created_at`, `updated_at`, `education`, `works_in_college`, `position`, `image`) VALUES
(19, 'АЙТБАЕВА НАГИМА КАЛДЫБЕКОВНА', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ:\r\n1.	Техникалық және кәсіптік, орта білімнен кейінгі білім беру ұйымдарының студенттері арасындағы Ыбырай Алтынсариннің туғанына 180 жылдығына арналған «Қазақ сахарасының қоңырауы» атты облыстық байқауында «ДАЛА ЖҰЛДЫЗЫ» бағыты бойынша Қарағанды облысында білім беруді дамытудың оқу-әдістемелік орталығы, ІІ дәрежелі Диплом 2022 ж.\r\n2.	Ыбырай Алтынсариннің туғанына 180 жылдығына арналған «Қазақ сахарасының қоңырауы» атты облыстық байқауының  «КЕЛ, БАЛАЛАР, ОҚЫЛЫҚ» бағыты бойынша Қарағанды облысында білім беруді дамытудың оқу-әдістемелік орталығы,ІІ-дәрежелі Диплом, 2022 ж.\r\n3.	Техникалық және кәсіптік, орта білімнен кейінгі білім беру ұйымдарының студенттері араындағы Халықаралық «Алаш» сыйлығының лауреаты, Қазақстанның еңбек сіңірген қайраткері, Абай атындағы әдебиет пен өнер саласындағы ҚР Мемлекеттік сыйлығының иегері, ақын Серік Ақсұңқарұлы шығармашылығына арналған дәстүрлі облыстық байқауы, ІІІ-дәрежелі Диплом, 2024ж.\r\n4.	ХІ Областной студенческий фестиваль национальных культур «Песню дружбы запевает молодежь», Сертификат 2022 г.\r\n5.	Білім беру саласындағы әлеуметтік-педагогикалық инновациялардың ІІ-Халықаралық жәрмеңкесінің презентация алаңында жоба ұсынғаны үшін мадақтама 2023 ж.\r\n6.	«Өшпес ерлік» жобасының аясында Кеңес Одағының батырлары Талғат Бегелдиновтің, Мәншүк Мәметованың, «Халық қаһарманы» атағының иегері Хиуаз Доспанованың 100 жылдығына арналған «Жеңіс батырлары» халықаралық интернет-байқауы ұйымдастырғаны үшін Алғыс хат, 2022ж.\r\n7.	Білім және ғылым қызметкерлерінің кәсіподақ жұмысына белсене қатысқаны үшін Қазақстандық салалық Білімі және ғылым қызметкерлері кәсіпдік одағының қарағанды облыстық ұйымы, Құрмет грамотасы 2022 ж.\r\n8.	Қарағанды техника-құрылыс колледжінің кәсіподақ жұмысына белсене қатысқаны үшін«Мәртебе» білім және ғылымның салалық кәсіптік одағы «Сала қызметкерлерінің кәсіподағына сіңірген айрықша еңбегі үшін» төс белгі, 2023 ж.', '2025-01-05 05:02:15', '2025-06-02 04:46:45', '[\"КарГУ им. Е.А.Букетова, 1992г., КарГТУ, 2009г.\"]', '2020', 'Аудармашы, қазақ тілі мен әдебиеті пәнінің мұғалімі', 'blank-profile-picture-973460_1280.png'),
(20, 'АКИМБАЕВА НАЗЕЛ РАХИМБЕККЫЗЫ', '1.	Заместитель главного эксперта по компетенции «Флористика» национального чемпионата WorldSkills Казахстан-2019, г.Астана. \r\n2.	Главный эксперт по компетенции «Флористика» национального чемпионата WorldSkills Kazakhstan-2021, г.Кокшетау.  \r\n3.	Главный эксперт по компетенции «Флористика» в отборочном туре профессионального мастерства EuroSkills Gdansk-2023, г.Астана.\r\n4.	 Разработчик тестовых вопросов по специальностям ТиПО для проведения национального квалификационного тестирования педагогических работников и приравненных к ним лиц. 2019-2023гг. \r\n5.	Эксперт-компатриот по компетенции «Флористика» европейского чемпионата Euroskills Gdańsk 2023, Польша.\r\n6.	Эксперт паспортов образовательных программ технического и профессионального, послесреднего образования РК для внесения в Реестр в 2022г., 2024 г.\r\n', '2025-01-05 05:08:02', '2025-04-30 03:24:22', '[\"Карагандинский государственный технический университет 2016 г., Карагандинский технический университет 2020 г., магистр технических наук\"]', '2018', 'Преподаватель спецдисциплин', '1.jpg'),
(21, 'АЛАКАЕВА БАКГУЛЬ КАНАТОВНА', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ:\r\n1.	Учебно-методический центр развития образования Карагандинской области. Алғыс хат, 2015 г.\r\n2.	Внештатный тренер Холдинг «Қәсіпқор», 2016-2018 г.\r\n3.	Разработала СМК колледжа 2021 г.\r\n4.	Алғыс хат. 2023 г. управления образования Карагандинской области.\r\n5.	Подготовила участника для конкурса «Жас шебер», сертификат 2023 г.\r\n6.	Qaraganda Worldskills-2023, Алғыс хат. \r\n7.	Abilympics – 2024, Алғыс хат. ', '2025-01-05 05:14:19', '2025-06-02 04:48:23', '[\"Семипалатинский государственный университет им.Шакарима.\"]', '2015', 'Методист, преподаватель спецдисциплин', '2.jpg'),
(22, 'АЛТАЙБАЕВ РЫМБЕК КАПШОВИЧ', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ: \r\n1.	В 2017 году награжден дипломом акима Карагандинской области в номинации «Лучший мастер производственного обучения».\r\n2.	В профессиональном конкурсе «Мастера отделочных работ» студент Бекбаев Багдаулет занял 2 место, 2015г., г.Семей.\r\n3.	В региональном конкурсе WorldSkills Караганда-2016 г. по компетенции «Облицовка плиткой», студент Ушкемпиров Жаксылык занял 1 место.\r\n4.	В региональном конкурсе WorldSkills Караганда-2017 студент Бекбаев Багдаулет занял 1 место по компетенции «Сухое строительство и штукатурные работы»\r\n5.	В региональном конкурсе WorldSkills Караганда-2017, 2018 студент Дуйсенбеков Сабыржан занял 1 место по компетенции «Облицовка плиткой».\r\n6.	В региональном конкурсе WorldSkills Караганда-2020, студент Тілеуғабыл Мадияр занял 1 место по компетенции «Сухое строительство и штукатурные работы».	\r\n7.	В региональном конкурсе WorldSkills Караганда-2021 по компетенции «Сухое строительство и штукатурные работы» студент Әскербек Серікбол занял 1 место.\r\n8.	В региональном конкурсе WorldSkills Караганда-2022 студент Исайын Мухаметали занял 1 место по компетенции «Облицовка плиткой».\r\n9.	В республиканском конкурсе WorldSkills Казахстан-2016 студент Ушкемпиров Жаксылык занял 1 место по компетенции «Облицовка плиткой», г.Астана.\r\n10.	Республиканский конкурс World Skills Бекбаев Багдаулет, занял 3 место 2017 г. по компетенции «Сухое строительство и штукатурные работы», г.Астана.\r\n11.	В республиканском конкурсе WorldSkills Казахстан-2017,2018 студент Дуйсенбеков Сабыржан занял 1 место по компетенции «Облицовка плиткой», г.Астана.\r\n12.	В республиканском конкурсе WorldSkills Казахстан-2022 студент Тлеуғабыл Нұрсұлтан занял 1 место по компетенции «Облицовка плиткой», г.Астана.\r\n13.	В мировом чемпионате EuroSkills-2016 по компетенции «Облицовка плиткой» принимал участие студент Ушкемпиров Жаксылык г. Гетеборг. \r\n14.	В мировом чемпионате WorldSkills-Russia-2016, г. Краснодар. по компетенции «Облицовка плиткой» студент Ушкемпиров Жаксылык занял 3 место. \r\n15.	В мировом чемпионате EuroSkills-2018 по компетенции «Облицовка плиткой», «Сухое строительство и штукатурные работы» принимали участие студенты Дуйсенбеков Сабыржан и Бекбаев Багдаулет, г.  Будапешт.\r\n16.	В мировом чемпионате WorldSkills-2019 г.Казань принимал участие студент Дуйсенбеков Сабыржан.', '2025-01-05 05:15:52', '2025-06-02 04:49:43', '[\"Семипалатинский строительный техникум, 1989г., Семипалатинский педагогический институт им: Шакарима, 1995г\"]', '2015', 'Преподаватель спецдисциплин', '3.jpg'),
(23, 'АХМЕТБАЙ ЕРНҰР БАҚЫТЖАНҰЛЫ', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ:\r\n1.	Автомобиль көлігі бағыты бойынша «Үздік оқу стендтері» номинациясы бойынша 2 орын, Қарағанды 2019 ж.\r\n2.	Қ. Сәтбаев атындағы техникалық мамандықтар олимпиадасы Астана, 2020 ж.\r\n3.	WS Karaganda-2020 «Жеңіл автокөліктерді жөндеу және қызмет көрсету» құз Диплом, 3 орын.\r\n4.	Главный эксперт WS Karaganda-2022 по компетенции «Промышленный дизайн».\r\n5.	ТжКОБ педагогтерінің инновациялық жұмыстарының республикалық конкурсының өңірлік кезеңі, 2 орын, Қарағанды облысының ОӘО, 2023 ж.\r\n6.	Главный эксперт WS Karaganda-2023 по компетенции «Промышленный дизайн».\r\n', '2025-01-05 05:18:45', '2025-01-06 11:27:12', '[\"Карагандинский государственный технический университет, 2018г., Транспорт, транспортная техника и технология, бакалавр, 2020г. - магистр технических наук\"]', '2018', 'Преподаватель спецдисциплин', 'blank-profile-picture-973460_1280.png'),
(24, 'БАТПАНОВА МЕРУЕРТ ДУЗЕЛЬБЕКОВНА', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ: \r\n1.	«ТжКБ-да инклюзивтік білім берудің үздік педагогы» техникалық және кәсіптік білім беру ұйымдары оқытушыларының республикалық байқауының областық кезеңінің жеңімпазы, II-дәрежелі диплом, 2018 ж.\r\n2.	За подготовку призера Республиканской олимпиады имени М.В. Ломоносова по химии благодарственное письмо, 2018-2019 гг.\r\n3.	Мектеп оқушылар арасындағы «Jas AgroSkils» бірінші областық кәсіби  шеберлік чемпионатына «Ауыл шаруашылық биотехнологиясы» құзыреті бойынша сарапшы ретінде қатысқаны үшін, Алғыс хат 2018-2019 ж.\r\n4.	Халықаралық биологиялық алуан түрлілігі күніне арналған қалалық байқауының «Эколог- зерттеуші» номинациясы бойынша  зерттеу жұмысының жеңімпазы «Қарағанды техника құрылыс колледжі»  КММ 1-ші курс студенті Какетаев Нұрсұлтанға II-дәрежелі диплом, 2019-2020 ж.\r\n5.	Химия және биология пәндері оқытушыларының облыстық әдістемелік бірлестігі жұмысы аясында өткізілген «Химия және биология әлеміне саяхат» онлайн викторинасында III орын иеленген үшін «Қарағанды техника құрылыс колледжі»КММ студенті Солодовиченко Даниил, диплом, 2020-2021 ж.\r\n6.	Білім беру саласын дамытуға қосқан мол үлесі мен педагогикалық қызыметте шығармашылық табыстарға қол жеткізіп,біліктілік танытқаны үшін Құрмет грамотасы, 2021-2022 ж.\r\n7.	Білім беру саласының өркендеуі жолында адал қызымет етіп,жас ұрпақты оқыту мен тәрбиелеудегі ерен еңбегін жоғары бағаланып және қоғамдық жұмыстарға белсене араласқаны үшін Алғыс хат, 2022 ж.\r\n8.	Республикалық ғылыми-практикалық конференция «Биолтехнология» Павлодар қаласы, ІІ дәрежелі диплом, 2021 ж.\r\n9.	«Жас зерттеуші академиясы» атты ғылыми жобалар байқауында Доманова Луиза, І дәрежелі дилом, 2023 ж. \r\n', '2025-01-05 05:21:50', '2025-01-05 14:52:51', '[\"КарГУ имени Е.А. Букетова, 1997г.\"]', '2013', 'Преподаватель химии', 'ң.jpg'),
(25, 'БАХТЫБАЕВА АЛТЫНАЙ ТОКЕНОВНА', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ:\r\n1.	Мерекелік белгісі, \"Кәсіптік-техникалық білімге 75 жыл\".\r\n2.	Областной конкурс « Инновации в ІТ,ІІ место, Учебно-методический центр развития образования Карагандинской области 2017 г.\r\n3.	VІ областной фестиваль культуры народов Казахстана. г.Сарань. ІІІ место, 2017 г.\r\n4.	Почетная грамота ко дню учителя,  Отдел образования г.Караганды 2018 г.\r\n5.	«Колледж үздік оқытушысы», Қарағанды облысы Әкімінің білім саласындағы сыйлығы, 2019 г.\r\n6.	Қазақстан Республикасының Президенті АЛҒЫС ГРАМОТАСЫ және омырау белгісі, «АЛТЫН БАРС» Нұр-Сұлтан, Ақорда, Қазақстан Республикасының Президенті Алғыс хаты 2019 ж.\r\n7.	Worldskills–2020. Региональный чемпионат по компетенции «Инженерная графика» 3 место, Асауханов Мирас.\r\n8.	Конкурс профессионального мастерства по специальности «Информационные технологии», ІІІ место, городской акимат Караганды, отдел внутренной политики 2022 г.\r\n9.	Worldskills–2020., региональный чемпионат по компетенции «Безпилотные летательные аппараты», благодарственное письмо. 2022 г.\r\n10.	Областной конкурс «Лучший педагог-2022», сертификат.\r\n11.	 «Мәртебе» белгісі, Білім және ғылымның салалық кәсіптік одағы, «Сала қызметкерлігінің кәсіподағына сіңірген айрықша еңбегі үшін», 2023 ж.\r\n\r\n', '2025-01-05 05:23:02', '2025-01-06 11:27:01', '[\"Карагандинский педагогический институт, 1991., Карагандинский госудасртвенный университет им. Е.А. Букетова,  2002г.\"]', '2005', 'Преподаватель информатики, физики и английского языка', 'blank-profile-picture-973460_1280.png'),
(26, 'БОНДАРЕВА АЛЕНА АНДРЕЕВНА', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ: \r\n1.	\"WORLDSKILLS KARAGANDA-2024\", \"Визуальный мерчендайзинг и витринистика\", студентка Филимонова Дарья, 1 место.\r\n2.	Көркем еңбек мамандығы бойынша «Жас шебер» облыстық байқауы, студент Колесникова Яна, 1 место, 2024г.\r\n3.	\"WORLDSKILLS KARAGANDA-2023\", \"Визуальный мерчендайзинг и витринистика\", студентка Гильмиярова Аделина, 1 место.\r\n4.	Областной конкурс \"Үздік IT - сабақ\", г.Караганда, 24.02.2023, 1 место.\r\n5.	Выступление на Международной научно-практической конференции «Дизайн-образование и развитие инклюзивности: теория, методика и практика», 2023 г.\r\n', '2025-01-05 05:25:47', '2025-01-05 14:52:34', '[\"Высшее, КарГУ им.Е.А.Букетова, 2015. \"]', '2021', 'Заведующая отделением, преподаватель спецдисциплин', 'Рисунок1.jpg'),
(27, 'БОХАЙ БИГҮЛ', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ:\r\n1.	Қарағанды облысында білім беруді дамытудың оқу-әдістемелік орталығының алғыс хаты, 2017 ж.\r\n2.	«Кәсіподақ» холдингі» Коммерциялық емес акционерлік қоғамы Кәсіптік білім беру орталығының алғыс хаты 2017 ж.\r\n3.	Қарағанды облысында білім беруді дамытудың оқу-әдістемелік орталығы 1 дәрежелі диплом, 2022 ж.\r\n4.	Қарағанды облысында білім беруді дамытудың оқу-әдістемелік орталығы, 1 дәрежелі диплом, 2018 ж.\r\n', '2025-01-05 05:27:51', '2025-01-06 11:26:51', '[\"КарГТУ, Транспорт транспортная техника и технологии, 2007 г. бакалавр, 2009 г., магистр транспорта и транспортной техники технологии \"]', '2016', 'Преподаватель спецдисциплин', 'blank-profile-picture-973460_1280.png'),
(28, 'ДАТКИНА КУНДЫЗ КУАНЫШКЫЗЫ', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ:\r\n1.	Алғыс хат WorldSkills Karaganda-2023 аймақтық чемпионатына «Плиткамен қаптау» құзыреті бойынша жеңімпаз студент дайындаған ұшін. Қарағанды облысының білім басқармасы.\r\n2.	Алғыс хат. Қарағанды облысының білім басқармасы 2023 ж.\r\n3.	Алғыс хат. Халықаралық ғылыми-тәжірибелік конференциясы «Еңбек нарығының қазіргі заманғы тенденцияларын ескере отырып, ТЖҚБ-дағы инновациялық білім беру қызметінің өзекті бағыттары»  Атырау облысы білім басқармасы 2021ж.\r\n4.	Благодарственное письмо управления образования Атырауской области 2021г.\r\n5.	Алғыс хат. II облыстық  Жаңа Қазақстан шығармашылық онлайн байқауының жүлдегері дайындағаны ұшін.\r\n6.	Алғыс хат. XII облыстық Туған соқпақтар виртуалды экскурсиялар байқауына жеңімпаз дайындаған үшін.', '2025-01-05 05:30:43', '2025-01-05 14:52:21', 'null', '2020', 'Заведующая отделением, преподаватель английского языка', '5.jpg'),
(29, 'ӘДІЛ ДИАНА ДАРЫНҚЫЗЫ', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ: \r\n1.	Диплом 3 место Үздік ІТ сабақ \r\n2.	Республиканский конкурс \"Юный художник\", ЮНЕСКО, студентка Нұргелді Нәзерке, 1 место. \r\n3.	Республиканский конкурс \"Юный художник ЮНЕСКО, студентка Мырдина Любовь, 1 место. \r\n4.	Студентке Нұргелді Назерке вручен Сертификат Республиканского конкурса рисунков \"Время перемен\" ЮНЕСКО.\r\n5.	Национальный чемпионат Ворлдскилс-2022, студентка Жайлеубай Лаура, призовой медальон. \r\n6.	Национальный чемпионат Ворлдскилс-2023, студентка Гильмиярова Аделина, призовой медальон.\r\n7.	Алғыс хат Республиканского научно-практического центра \"ДАРЫН\" вручен студенту Әділ Д.Д.\r\n8.	Алғыс хат Управления образования Карагандинской области, 2023 год. \r\n9.	Алғыс хат Управления образования Карагандинской области 2023 год. \r\n10.	Участие в международной конференции \"ДИЗАЙН БІЛІМІ ЖӘНЕ ИНКЛЮЗИВТІ ДАМЫТУ: ТЕОРИЯ, ӘДІСТЕМЕ ЖӘНЕ ПРАКТИКА\".\r\n11.	Участие в областном конкурсе «Лучший ІТ урок».', '2025-01-05 05:32:17', '2025-01-05 14:52:15', '[\"Технологический колледж КарГТУ - 2013г., КарГУ имени Букетова-2017г\"]', '2021', 'Преподаватель спецдисциплин', '6.jpg'),
(30, 'ЖУМАНБАЕВА КУРАЛАЙ АСЫЛБЕКОВНА', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ: \r\n1.	«Даму мүмкіндігі шектелген балаларға инклюзивтік білім беруде ұйымдастыру» тақырыбында оқыту курстарына қатысқаны үшін Сертификат, 2016 ж.\r\n2.	«Техникалық және кәсіптік білім беру жүйесінде ерекше назар аударуды қажет ететін студенттермен жұмыс істейтін педагогтардың кәсіби құзыреттілігін көтеру» тақырыбында оқыту курсын өткізгені үшін Сертификат, 2016 ж.\r\n3.	Разработчик программы факультативного курса «Основы инклюзивного образования» для педагогических специальностей технического и профессионального образования, программа факультативного курса, Караганда, 2018 г.\r\n4.	Республиканский научно-методический журнал «Инноваций в педагогике», «Психолого-медико-педагогический консилиум-качественное взаимодействие всех участников образовательного процесса для успешной социализации обучающихся с особыми образовательными потребностями», г. Тараз,2019 г.\r\n5.	Информационно-методический сборник рекомендаций по организации инклюзивного образовательного процесса в организациях технического и профессионального образования, Караганда, 2018 г.\r\n6.	Қашықтықтан оқыту жағдайында белсенділік танытып, іс-тәжірибемен бөліскені үшін Алғыс хат, 2020 ж.\r\n7.	«Техникалық және кәсіптік білім беру жүйесін жаңғырту: бүгінгі мен келешегі» аймақтық семинар-практикум, сертификат 2019 ж.\r\n8.	«Инклюзивті білім беру практикасы:мектеп пен ТжКББ арасындағы үздіксіздік және сабақтастық» тақырыбындағы облыстық ғылыми-тәжірибелік конференция ұйымдастырып, өткізуге ат салысқаны үшін Алғыс хат, 2021 ж.\r\n9.	Қазақстан Республикасының білім беру жүйесін дамытуға қосқан зор үлесі үшін Алғысы, 2021 ж.\r\n10.	 За организацию и участие в Республиканском августовском совещании и представление опыта, благодарственное письмо, 2022 г.\r\n11.	Участник научно-практической конференции «Опыт и перспективы развития инклюзивного образования в колледжах», сертификат, 2022 г.\r\n12.	Білім беру саласындағы әлеуметтік-педагогикалық инновациялардың ІІ халықаралық жәрмеңкесі қатысқаны үшін сертификат, 2023 ж.', '2025-01-05 05:34:11', '2025-01-05 14:57:47', '[\"Карагандинский государственный университет имени Е.А. Букетова, 1996г. \"]', '2006', 'Заместитель директора УМР, преподаватель химии и биологии', '7.jpg'),
(31, 'ИСКАКОВА ДИАНА ЖЫЛКЫБАЕВНА', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ: \r\n1.	Главный региональный эксперт WorldSkills по компетенции «Визуальный мерчендайзинг» 2019-2021г. \r\n2.	Заместитель Республиканского эксперта WorldSkills по компетенции «Визуальный мерчендайзинг» 2021-2023 г. \r\n3.	Заместитель Регионального эксперта WorldSkills по компетенции «Визуальный мерчендайзинг» 2021-2023 г.\r\n4. Международный эксперт WorldSkills по компетенции «Визуальный мерчендайзинг» 2022-2023 г.\r\n5.	С 2019 года является разработчиком и экспертом Национального квалификационного теста по спецдисциплинам для преподавателей ТиППО по специальностям «0417000 Дизайн промышленной продукции», «0420000 Дизайн  интерьера» на государственном и русском языках.\r\n6. В 2019 году подготовила студентку Сидикову Акмарал к Международной конференции «Архитектура. Строительство. Реставрация. 21 век» (Россия, г. Москва, 2019 г., II Место), выступившей в секции «Техническое творчество молодежи. Новые производственные технологии» с докладом «Внедрение новых технологий в проектирование дизайн-интерьера», также была экспертом в данной конференции в секции «Техническое творчество молодежи. Новые производственные технологии».\r\n7. В 2019 году приняла участие в Республиканском семинар-совещании «Деятельность мастеров производственного обучения и преподавателей специальных дисциплин в рамках внедрения модульно-компетентностного подхода и стандартов WorldSkills», г. Талдыкорган.\r\n8. В 2019 году награждена почетной грамотой от заместителя Председателя Правления НАО «Холдинг «Кәсіпқор» Бимендиной А. Т.\r\n9. В 2020 году удостоена почетного звания Лауреата I степени «III Республиканского профессионального конкурса «Лучший педагог по дистанционному обучению» в номинации «Портфолио педагога».\r\n10. В 2021 году награждена почетной грамотой от Управления образования Карагандинской области.\r\n11. В 2021 году подготовила студентку Байгошкарову Дану к республиканскому Чемпионату WorldSkills по компетенции «Визуальный мерчендайзинг», г. Алматы, 1 место.\r\n12. В 2022 году выступила с докладом «Внедрение стандартов WorldSkills в модульно-компетентностный подход на основе спецификации стандарта по компетенции «Визуальный мерчендайзинг» на Международном форуме «Актуальные вопросы дизайн-образования».\r\n13. В 2022 году награждена почетной грамотой от Карагандинской областной организации Казахстанского отраслевого Профсоюза работников образования и науки.\r\n14. В 2022 году подготовила студентку Байгошкарову Дану к международному чемпионату WorldSkills Special Edition по компетенции «Визуальный мерчендайзинг», Швеция, г. Стокгольм.\r\n15.	В 2023 году выступила с мастер-классом по развитию медиа-компетенции проектной деятельности студентов-дизайнеров на IX Международном Форуме по педагогическому образованию «Качество педагогического образования в условиях современных вызовов», г.Караганда, г.Казань, Татарстан.\r\n16. В 2023 году выступила с докладом «Проект как средство развития творческой активности студентов – дизайнеров» на международной конференции «Дизайн-образование и развитие инклюзивности: теория, методика и практика».\r\n', '2025-01-05 05:34:56', '2025-01-06 11:26:40', '[\"КарГУ им Е.А. Букетова,2013 г. \"]', '2018', 'Преподаватель спецдисциплин', 'blank-profile-picture-973460_1280.png'),
(32, 'ИСКАКОВА МАДИРА КУРАКБАЕВНА', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ: \r\n1.	Совместный международный социальный проект в рамках ассоциации «Рост – Өрлеу посвященный 70-летию Великой Победы, между колледжами России г. Первоуральск и студентами КГУ «Карагандинский технико-строительный колледж», Казахстан, г. Караганда и г. Первоуральск, Россия, 2015 г.\r\n2.	Эксперт-компатриот по компетенции «Малярные и декоративные работы» в Республиканском чемпионате профессионального мастерства «WorldSkills Kazakhstan-2017», г. Астана. Результат: студентка Тоқырбай А. – медальон, (сертификаты).\r\n3.	Эксперт-компатриот по компетенции «Малярные и декоративные работы» в Региональном чемпионате профессионального мастерства «WorldSkills Karaganda-2018», г. Караганда. Результат: студентка Тоқырбай А. – 1 место, (сертификаты, диплом).\r\n4.	Эксперт-компатриот по компетенции «Малярные и декоративные работы» в Региональном чемпионате профессионального мастерства «WorldSkills Karaganda-2019», г. Караганда. Результат: студент Әлмуқан М. – участие, (сертификаты).\r\n5.	Главный эксперт по компетенции «Малярные и декоративные работы» в Региональном чемпионате профессионального мастерства «WorldSkills Karaganda -2021», г. Караганда, (сертификаты).\r\n6.	Эксперт-компатриот по компетенции «Малярные и декоративные работы» в Республиканском чемпионате профессионального мастерства «WorldSkills Kazakhstan-2021», г. Кокшетау. Результат: студент Гуцул М. – участие, (сертификаты).\r\n1.	Главный эксперт по компетенции «Малярные и декоративные работы» в Региональном чемпионате профессионального мастерства «WorldSkills Karagand-2022», г. Караганда, (сертификаты).\r\n2.	Эксперт-компатриот по компетенции «Малярные и декоративные работы» в Республиканском чемпионате профессионального мастерства «WorldSkills Kazakhstan-2022», г. Астана. Результат: студент Сайлау С. – участие, (сертификаты).\r\n3.	Главный эксперт по компетенции «Малярные и декоративные работы» в Региональном чемпионате профессионального мастерства «WorldSkills Karaganda -2023», г. Караганда, (сертификаты).\r\n4.	Эксперт-компатриот по компетенции «Малярные и декоративные работы» в Республиканском чемпионате профессионального мастерства «WorldSkills Kazakhstan-2023», г. Астана. Результат: студент Софина Ж. – участие, (сертификаты).\r\n1.	Главный эксперт по компетенции «Малярные и декоративные работы» в Региональном чемпионате профессионального мастерства «WorldSkills Karaganda-2024», г. Караганда, (сертификаты).\r\n2.	Руководитель совместного студенческого проекта колледжей России г. Первоуральска и студентов КТСК г.Караганды по ремонту квартир ветеранов войны.\r\n', '2025-01-05 05:36:12', '2025-01-05 14:51:47', '[\"Жезказганский строительный техникум 1985.\"]', '2009', 'Мастер п/о', '8.jpg'),
(33, 'КАКЕМБАЙ РАХАТ', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ:\r\n1.	Республикалық Тарих пәнінен ұстаздар арасында олимпиадасының жеңімпазы, ІІ дәрежелі диплом, 26.12.2020 ж.\r\n2.	А.Құқанбайұлының 175 жылдығына арналған «Ұлы даланың ұлы тұлғасы-Абай» атта республикалық қашықтық олимпиадасының жеңімпазы, І дәрежелі диплом 25.12.2020  ж.\r\n3.	«Құқықтық навигатор» облыстық пікір-сайыс турнирі ІІІ орын, 02.06.2021.\r\n4.	ҚР Тәуелсіздігінің 30 жылдығына арналған «Ауылым-алтын бесігім» ІІІ орын,2021 ж.\r\n5.	Қазақстан тарихы пәні бойынша ІІІ Республикалық қашықтық олимпиадасы І дәрежелі диплом, 06.12.2022 ж.\r\n6.	Халықаралық ана тілі күніне орай ұйымдастырылған облыстық пікірсайыс турнирі І орын,2023 ж.\r\n7.	«Үздік ІТ-сабақ» облыстық байқау ІІ орын, 26.02.2024 ж.\r\n8.	«Құқық білгірлері» облыстық іскерлік ойын ІІ орын, 19.01.2024 ж.\r\n', '2025-01-05 05:37:27', '2025-01-05 14:51:39', '[\"КарГУим. Е.А.Букетова, 2008г.\"]', '2015', 'Преподаватель истории и общественных дисциплин', '9.jpg'),
(34, 'КАСИМОВА ГУЛЬЗАДА ТУРДАКУНОВНА', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ:\r\n1.	Әлеуметтік-гуманитарлық пәндер оқытушыларының облыстық әдістемелік бірлестігі жұмысының аясында колледж студенттері арасында «Қазақстан тарихы» пәні бойынша өткізілген «Қазыналы құт берекем -Қарағанды» тақырыбындағы облыстық олимпиадада 1-дәрежелі орынға ие болғаны үшін Сыздыков Абайға берілді, 2019 ж. \r\n2.	Республика күніне орай колледж студенттері арасындағы облыстық пікірсайыс турниріне қатысып Қарағанды техника-құрылыс колледжінің «Why not?» командасы жүлделі екінші орынға ие болды. Команда мүшелері екінші курс студенті Матвеев Д. және үшінші курс студенті, «Жігер» студенттік парламентінің президенті Иртаева Е. Команданы дайындыған «Все точки над i» дебат клубының үлестірушісі тарих және әлеуметтік-гуманитарлық пәндерінің оқытушысы Касимова Г.Т., 20.10.22 ж.\r\n3.	23.02.2023 проходил областной дебатный турнир, посвященный международному дню языков Республики Казахстан. Команды \"Сөз Мерген\" в казахской лиге и \"Why not\" в русской лиге заняли ПЕРВЫЕ места. \r\n4.	Областной конкурс видеооткрыток, посвященный празднику 9 Мая, 1 место, 2023 г. \r\n5.	Диплом. 23.02.2024 ж. “Сарыарқа дарыны”БҚББ АҒПО ұйымдастыруымен кәсіптік және техникалық білім беру ұйымдарының арасында өткен ІІ-ші қалалық пікірсайыс турнирінде Қарағанды техника-құрылыс колледжінің “Қазақстан” команда мүшелері Егінбаев Әділет пен Абрашит Зере жүлделі І орынға ие болды. \r\n6.	Диплом. 16.03.2024 ж. Техникалық және кәсіптік, орта білімнен кейінгі білім беру ұйымдарының студенттері арасында облыстық пікірсайыс турирінен Қарағанды техника-құрылыс колледжінің «Қазақстан» командасы 9-АР-22 тобының студенті Абдрашит Зере мен 9-ДИ-РБ-23 тобының студенді Финонченко Полина қатысып, жүлделі ІІ-орынға ие болды.', '2025-01-05 05:38:52', '2025-01-05 14:51:26', '[\"Семипалатинский государственный университет им. Шакарима, 2004г., Семипалатинский государственный университет им. Шакарима, 2007г.\"]', '2016', 'Преподаватель истории и общественных дисциплин', '10.jpg'),
(35, 'КОВАЛЕНКО ТАТЬЯНА ИВАНОВНА', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ: \r\n1.	Участник Областной ярмарки «От хобби до успешного бизнеса».\r\n2.	Участник  экоконкурсов  в Экомузее г. Караганды.\r\n3.	 Областной экоконкурс «Лучший артобъект из мусора», диплом первой степени, студентка Джазбекова А. \r\n4.	Эксперт-компатриот регионального чемпионата WorldSkills по компетенции «Флористика», 1 место, студентка Смирнова А. \r\n5.	Республиканский конкурс «Шабыт», диплом  второй  степени Колмакова Д.\r\n6.	Конкурс ЮНЕСКО «Время перемен», студенты Кирсанов А., Жакаш Б., сертификат.\r\n7.	Эксперт Внешней экспертной комиссии НААР при аккредитации РГУ «Казахская Национальная академия искусств имени Т. Жургенева» (колледж).\r\n8.	Консультант по разработке специальной учебной программы по квалификации 041312 2 «Изготовитель художественных изделий из кожи и шерсти» Центра профессионального образования НАО «Холдинг Кәсiпкор», 2016г.\r\n9.	Член Союза Дизайнеров РК.\r\n10.	Участник  международных конференций. Статьи в сборнике.\r\n11.	Персональная выставка творческих работ «На крыльях вдохновения», 1996г.\r\n12.	В 2022 году принимала участие в Региональном конкурсе профессионального мастерства среди педагогов организаций технического и профессионального, послесреднего образования по отрасли культуры и искусства на базе КГКП «Карагандинский колледж искусств им.Таттимбета». \r\n13.	В 2022 году принимала участие в Областном конкурсе юных художников «Бояулар купиясы» под эгидой ЮНЕСКО.\r\n', '2025-01-05 05:40:01', '2025-01-05 14:51:15', '[\"Целиноградский сельскохозяйственный институт, 1988г., КарГУ им.Е.А. Букетова, 2003г.\"]', '2020', 'Преподаватель спецдисциплин', '11.jpg'),
(36, 'КУСЕНБАЕВА БАХЫТЖАН ОРЫНБАСАРОВНА', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ:\r\n1.	Ыбырай Алтынсариннің туғанына 180 жылдығына арналған «Қазақ сахарасының қоңырауы» атты облыстық байқауының  «КЕЛ, БАЛАЛАР, ОҚЫЛЫҚ» бағыты бойынша Қарағанды облысында білім беруді дамытудың оқу-әдістемелік орталығы,ІІ-дәрежелі Диплом, 2022 ж.\r\n2.	ХІ Областной студенческий фестиваль национальных культур «Песню дружбы запевает молодежь», Сертификат 2022 г.\r\n3.	«Өшпес ерлік» жобасының аясында Кеңес Одағының батырлары Талғат Бегелдиновтің, Мәншүк Мәметованың, «Халық қаһарманы» атағының иегеріХиуаз Доспанованың 100 жылдығына арналған «Жеңіс батырлары» халықаралық интернет-байқауы ұйымдастырғаны үшін Қарағанды облысының мәдениет, архивтер және құжаттама басқармасының «Ж. Бектұров ат.облыстық жасөспірімдер кітапханасы» КММ, Алғыс хат, 2022ж.\r\n4.	Қарағанды техника-құрылыс колледжінің кәсіподақ жұмысына белсене қатысқаны үшін «Мәртебе» білім және ғылымның салалық кәсіптік одағы «Сала қызметкерлерінің кәсіподағына сіңірген айрықша еңбегі үшін» төс белгі, 2023 ж.\r\n', '2025-01-05 05:41:28', '2025-01-05 14:51:06', '[\"Талдыкорганский пединститут им. И. Джансугуров 1989г., КарГУ им. Е.А. Букетова, 2004г.\"]', '2020', 'Преподаватель казахского языка и литературы', '12.jpg'),
(37, 'МУКАШЕВА ЖАЗИРА СУЛТАНОВНА', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ:\r\n1.	Подготовила призера регионального чемпионата Qaraganda Worldskills-2020 по компетенции 3Д-прототипирование, 2 место. \r\n2.	Участник обучающего семинара резерва директоров по проведению демонстрационного экзамена по требованиям (стандартам) Worldskills, как формы квалификационного экзамена и разработки комплексно-оценочной документации, 2020г.\r\n3.	Обобщение опыта на областном уровне: «Демонстрационный экзамен как форма независимой оценки качества подготовки специалистов с учетом стандартов Worldskills». 2021г.\r\n4.	Обобщение опыта на Августовской региональной конференции с докладом по теме «Оценка уровня профессиональной направленности». 2021 г.\r\n5.	Обобщение опыта на республиканском онлайн-семинаре «Современная траектория в профессиональной подготовке и дизайнеров новой формации» на тему «Модернизация материально-технической базы в рамках проекта «Жас маман» для повышения качества подготовки специалистов» на базе Карагандинского технико-строительного колледж, 2021г.\r\n6.	Алғыс хат управления образования  Карагандинской области, 2021г.\r\n7.	Учебно-методический центр развития образования Карагандинской области. Алғыс хат. 2021г.\r\n8.	НПП РК Атамекен. Алғыс хат.2021г.\r\n9.	Подготовила призера регионального чемпионата Qaraganda Worldskills-2023 по компетенции 3Д-прототипирование, 2 место.  \r\n10.	Призер конкурса среди педагогов Хакатон-бағдармалау марафоны, 2 орын.\r\n11.	Участие в II-III международных социально-иновационных ярмарках. 2023, 2024гг.\r\n12.	Призер конкурса профессионального мастерства среди педагогов ИТ отрасли, 3 место, 2023г.', '2025-01-05 05:43:38', '2025-01-05 14:50:55', '[\"Казахстанско-Российский университет, 2013г.\"]', '2020', 'Преподаватель по Айти ', '13.jpg'),
(38, 'НУРЖАНОВА ЗАУРЕ БОЛАТОВНА', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ:\r\n1.	Международный проект \"Чтение без границ.\" Подготовка студента Международный Диплом І-степени 2022 г. Благодарственное письмо.\r\n2.	Областной конкурс чтецов \"Красною кистью рябина зажглась...1 место, диплом, 2022 г.\r\n3.	Оқу сауаттылығы апталығында «Шекарасыз оқу» халықаралық жобасы аясында өткізілген мәнерлеп оқу байқауы І-ші дәрежелі диплом, 2022 ж.\r\n4.	«Әдеби презентация» номинациясы бойынша жеңімпаз дайындағаны үшін ІХ открытый републиканский конкурс «Мир в радуге профессий» Алғыс хат 2023 ж.\r\n5.	Техникалық және кәсіптік, орта білімнен кейінгі білім беру ұйымдарының студенттері арасындағы «WS-2022» аймақтық чемпионатына «Визуальді мерчендайзинг және витринистика» құзіреті бойынша студент дайындағаны үшін, Алғыс хат 2022 ж.\r\n6.	За ответственное отношение к координации деятельности клуба ЮНЕСКО Казахстанская Национальная Федерация клубов ЮНЕСКО (Unesco) Благодарственное письмо, 2023г.', '2025-01-05 05:44:39', '2025-01-05 14:50:46', '[\"КарГУ им. Е.А.Букетова, 1994г\"]', '2021', 'Заведующая отделением, преподаватель русского языка и литературы', '14.jpg'),
(39, 'ОСПАНОВ АЛМАС ШАЙМАГАНБЕТОВИЧ', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ: \r\n1.	Региональный чемпионат WorldSkills Караганда-2021г, студент Совет Дауренбек, 1 место, медаль - золото.\r\n2.	Республиканский чемпионат WorldSkills Казахстан-2021, г.Семей, студент Совет Дауренбек, 3место.\r\n3.	Региональный чемпионат WorldSkills Караганда-2022, студент Хайрат Жоламан 1 место, медаль - золото.\r\n4.	Республиканский чемпионат WorldSkills Казахстан-2022, г.Астана, ЭКСПО, студент Хайрат Жоламан, 4 место, призовой медальон.\r\n5.	Региональный чемпионат WorldSkills Караганда-2023, студент Хайрат Жоламан, 1 место, медаль - золото.\r\n6.	Республиканский чемпионат WorldSkills Казахстан-2023, г.Астана, ЭКСПО, студент Устеменко Артём, 2 место, медаль - серебро.\r\n', '2025-01-05 05:45:24', '2025-01-06 11:26:28', '[\"Карагандинский государственный технический университет, 2010г. \"]', '2015', 'Преподаватель спецдисциплин', 'blank-profile-picture-973460_1280.png'),
(40, 'ТАЙМУРЗАНОВА ТИШКЕН ЕСТАЙОВНА', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ: \r\n1.	Адал еңбегі, кәсіби шеберлігі, педагогикалық қызметте жоғары нәтижелілік пен тиімділікке өол жеткізгені  үшін Қазақстан Республикасы Тәуелсіздігінің 30 жылдығы, ҚТҚК – нің 45 жылдығы қарсаңында, Алғыс хат, 2021-2022 ж.\r\n2. Научно – технический конкурс «Новые технологии 2021», Диплом I степени, 2020-2021гг.  \r\n3.	Әдіскерлердің облыстық әдістемелік бірлестігінің жұмысы шеңберіндегі «Инженер-педагог қызметкерлердің өзін-өзі дамытудың сапалы жоспары — педагог қызметкердің кәсіби құзыреттілігін арттырудың негізі» тақырыбындағы облыстық семинарда өз тәжірибесімен бөліскені үшін «Сертификат», 2022 ж.\r\n4. Техникалық және кәсіптік, орта білімнен кейінгі білім беру ұйымдары педагогтерінің инновациялық жұмыстарының республикалық конкурсы, сертификат, 2019-2020жж.\r\n5. Сала қызметкерлерінің кәсіподағына сіңірген еңбегі үшін «Төс белгі», 2022 ж.\r\n', '2025-01-05 05:46:37', '2025-01-06 11:26:01', '[\"КарГУ имени Е.А. Букетова, 1982г. \"]', '2020', 'Преподаватель физики', 'blank-profile-picture-973460_1280.png'),
(41, 'ТУСУПОВА ЗАУРЕШ АЛИМЖАНОВНА', 'НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ:\r\n1.	Білім беру саласындағы әлеуметтік-педагогикалық инновациялардың ІІ-Халықаралық жәрмеңкесінің презентация алаңында жоба ұсынғаны үшін мадақтама 2023 ж.\r\n2.	Білім және ғылым қызметкерлерінің кәсіподақ жұмысына белсене қатысқаны үшін Қазақстандық салалық Білімі және ғылым қызметкерлері кәсіпдік одағының қарағанды облыстық ұйымы, Құрмет грамотасы 2022 ж.\r\n3.	ҚР тәуелсіздігінің 30 жылдығына арналған техникалық және кәсіптік, орта білімнен кейінгі білім беру ұйымдары студенттері арасындағы «Тәуелсіздік – елімнің ерлік жолы» облыстық онлайн байқауына жеңімпаз қатысушы дайындағаны үшін Қарағанды облысында білім беруді дамытудың оқу-әдістемелік орталығы, диплом ІІ степени, Алғыс хат 2022 ж.\r\n4.	Қарағанды техника-құрылыс колледжінің кәсіподақ жұмысына белсене қатысқаны үшін«Мәртебе» білім және ғылымның салалық кәсіптік одағы «Сала қызметкерлерінің кәсіподағына сіңірген айрықша еңбегі үшін» төс белгі, 2023 ж.\r\n5.	Қазақстандық оқу-ағарту, ғылым және жоғары білім қызметкерлерінің салалық кәсіподағы«Білім және ғылым қызметкерлерінің кәсіподағына сіңірген еңбегі үшін» төс белгі, 2023ж.\r\n', '2025-01-05 05:48:14', '2025-03-19 21:10:59', '[\"КарГУ имени Е.А. Букетова,1986г.\"]', '2015', 'преподаватель русского языка', '16.jpg');

