INSERT INTO `veterans` (`id`, `name`, `biography`, `photo`, `created_at`, `rank`, `name_ru`, `name_kz`, `name_en`, `biography_ru`, `biography_kz`, `biography_en`) VALUES
(10, 'ЖАМИЛЕВА ГАЛИЯ МУБЕРОВНА', 'Родилась 3 января 1960 года в поселке Успенка Карагандинской области. В 1990 году окончила Новосибирский институт инженеров геодезии, картографии и аэрофотосъемки, инженер-геодезист. Более 23-х лет работала на различных производственных участках в должностях геолога-геодезиста, инженера-геодезиста, главного специалиста-землеустроителя, а также супервайзер-технологом на заводе строительных материалов «ЭкоСтройСервис». Последние 17 лет Галия Муберовна посвятила педагогической деятельности в учебных заведениях области. В высшем политехническом колледже работала в качестве преподавателя, заведующей кафедрой строительных дисциплин. Затем продолжила педагогическую деятельность в Карагандинском филиале Алматинской инженерно-технической академии, Многопрофильном гуманитарно-техническом колледже, в технико-строительном колледже, где также работала в должности преподавателя строительных дисциплин, а затем заместителем директора по учебной работе и отсюда ушла на заслуженный отдых. Галия Муберовна внесла огромный вклад в открытие и развитие специальности «Строительство и эксплуатация зданий и сооружений». Ею были разработано огромное число учебно-методических пособий по многим спецдисциплинам, которые в настоящее время успешно используются преподавателями колледжа. Электронные учебники, разработанные Галией Муберовной отличаются новизной и совершенством использования их в учебных целях как студентами, так и педагогами. Большую лепту внесла в организацию работы с социальными партнерами по установлению взаимосотрудничества в целях качественной подготовки рабочих кадров для строительной отрасли. Галия Муберовна стояла у истоков начала в Казахстане движения WorldSkills являлась международным экспертом чемпионата «WorldSkills–Brazilia-2015», международным экспертом чемпионата «WorldSkills–Belarus-2018», заместителем главного эксперта «WorldSkills–Kazakhstan-2018», что позволило колледжу поднять на достойный уровень подготовку участников к различным профессиональным чемпионатам, в том числе к чемпионатам WorldSkills. Жамилева Г.М. за безупречный педагогический труд неоднократно награждалась почетными грамотами и благодарственными письмами, в том числе от имени министра образования и науки республики Казахстан.', '1742384374_1718840498164-Ð Ð¸ÑÑÐ½Ð¾Ðº5.jpg', '2025-01-05 04:18:46', 'ветеран ктск', 'ЖАМИЛЕВА ГАЛИЯ МУБЕРОВНА', 'ЖАМИЛЕВА ГАЛИЯ МУБЕРОВНА', '', 'Родилась 3 января 1960 года в поселке Успенка Карагандинской области. В 1990 году окончила Новосибирский  институт инженеров геодезии, картографии  и  аэрофотосъемки, инженер-геодезист.\\\\r\\\\nБолее 23-х лет работала на различных производственных участках в должностях геолога-геодезиста, инженера-геодезиста, главного специалиста-землеустроителя, а также супервайзер-технологом на заводе строительных материалов «ЭкоСтройСервис». \\\\r\\\\nПоследние 17 лет Галия Муберовна посвятила педагогической деятельности в учебных заведениях области. В высшем политехническом колледже работала в качестве преподавателя, заведующей кафедрой строительных дисциплин. Затем продолжила педагогическую деятельность в Карагандинском филиале Алматинской инженерно-технической академии, Многопрофильном гуманитарно-техническом колледже, в технико-строительном колледже, где также работала в должности преподавателя строительных дисциплин, а затем заместителем директора по учебной работе и отсюда ушла на заслуженный отдых.\\\\r\\\\nГалия Муберовна внесла огромный вклад в открытие и развитие специальности «Строительство и эксплуатация зданий и сооружений». Ею были разработано огромное число учебно-методических пособий по многим спецдисциплинам, которые в настоящее время успешно используются преподавателями колледжа. Электронные учебники, разработанные Галией Муберовной отличаются новизной и совершенством использования их в учебных целях как студентами, так и педагогами. Большую лепту внесла в организацию работы с социальными партнерами по установлению взаимосотрудничества в целях качественной подготовки рабочих кадров для строительной отрасли.\\\\r\\\\nГалия Муберовна стояла у истоков начала в Казахстане движения WorldSkills являлась международным экспертом чемпионата «WorldSkills–Brazilia-2015», международным экспертом чемпионата «WorldSkills–Belarus-2018», заместителем главного эксперта «WorldSkills–Kazakhstan-2018», что позволило колледжу поднять на достойный уровень подготовку участников к различным профессиональным чемпионатам, в том числе к чемпионатам WorldSkills.\\\\r\\\\nЖамилева Г.М. за безупречный педагогический труд неоднократно награждалась почетными грамотами и благодарственными письмами, в том числе от имени министра образования и науки республики Казахстан.\\\\r\\\\n', '1960 жылы 3 қаңтарда Қарағанды облысының Успенка кентінде дүниеге келген. 1990 жылы Новосибирск геодезия, картография және аэрофототүсірілім инженерлері институтын бітірді. Инженер-геодезист.\\\\\\\\r\\\\\\\\n23 жылдан астам уақыт бойы әртүрлі өндірістік учаскелерде геолог-геодезист, инженер-геодезист, бас маман-жерге орналастырушы, сондай-ақ «ЭкоСтройСервис» құрылыс материалдары зауытында супервайзер-технолог лауазымдарында жұмыс атқарды. \\\\\\\\r\\\\\\\\nГалия Муберовна  соңғы 17 жылын облыстың оқу орындарында педагогикалық қызметке арнады. Жоғары политехникалық колледжде оқытушы, құрылыс пәндері кафедрасының меңгерушісі болып жұмыс істеді. Содан кейін Алматы инженерлік-техникалық академиясының Қарағанды филиалында, Көпсалалы гуманитарлық-техникалық колледжде, Техника-құрылыс колледжінде педагогикалық қызметін жалғастырды. Колледжде құрылыс пәндерінің оқытушысы, содан кейін директордың оқу ісі жөніндегі орынбасары лауазымдарында жұмыс атқарып, осы жерден еңбек сіңірген демалысқа кетті.\\\\\\\\r\\\\\\\\nГалия Муберовна «Ғимараттар мен құрылыстарды салу және пайдалану» мамандығының ашылуы мен дамуына үлкен үлес қосты. Ол қазіргі уақытта колледж оқытушылары сәтті қолданатын көптеген арнайы пәндер бойынша көптеген оқу-әдістемелік құралдар әзірледі. Галия Муберовна әзірлеген электронды оқулықтар студенттердің де, мұғалімдердің де оларды оқу мақсатында қолданудың жаңалығымен және жетілдірілуімен ерекшеленеді. Құрылыс саласы үшін жұмысшы кадрларды сапалы даярлау мақсатында өзара ынтымақтастықты орнату бойынша әлеуметтік әріптестермен жұмысты ұйымдастыруда біршама еңбектер атқарды.\\\\\\\\r\\\\\\\\nГалия Муберовна Қазақстанда WorldSkills қозғалысының бастауында тұрды, «WorldSkills–Brazilia-2015» чемпионатының халықаралық сарапшысы, «WorldSkills–Belarus-2018» чемпионатының халықаралық сарапшысы, «WorldSkills–Kazakhstan-2018» бас сарапшысының орынбасары болды. Бұл колледжде қатысушылардың әртүрлі кәсіби байқауларда дайындығын лайықты деңгейге көтеруге мүмкіндік берді, соның ішінде WorldSkills чемпионаттарында.\\\\\\\\r\\\\\\\\nЖамилева Г.М. мінсіз педагогикалық еңбегі үшін бірнеше рет Құрмет грамоталарымен және Алғыс хаттармен, сондай-ақ Қазақстан Республикасы Білім және ғылым министрінің марапаттарына ие болды.\\\\\\\\r\\\\\\\\n', ''),
(11, 'ЧЖЕН АНДРЕЙ ИВАНОВИЧ', 'Чжен Андрей Иванович родился в 1945 году в поселке Байназар, Шетского района Карагандинской области. После окончания школы поступил в ГРПУ №2 г. Караганды и после завершения обучения в 1962-1966 годах работал в должности мастера производственного обучения Карагандинского индустриально-педагогического техникума. Затем продолжил педагогическую деятельность в ГПТУ №59 г. Караганды также в одлжности мастера производственного обучения. В 1971 году Андрей Ивановича назначают директором ГПТУ №155 г. Каражал. И в этом же году о поступает в Карагандинский государственный университет имени Е.А.Букетова, который успешно заканчивает в качестве первого выпуска в 1976 году по специальности «Экономика и планирование, экномика материально-технического снабжения», полцчив квалификацию – экономист. В 1973-1978 годах Андрей Иванович работал старшим мастером в ГПТУ №109 г. Караганды, затем в 1978-1983 годах возглавлял СПТУ №6. В 1985 году Андрей Иванович решил сменить педагогическую деятельность на производственную работу и возглавил в должности заместителя начальника управления ПМК-40. В 1987-1990 годах работал в должности заместителя директора Ленинской плодоовощной базы, а в 1990-1995 годах заместителем директора облкоопторга и затем до 2014 года продолжил производственную деятельность в ТОО «ЮМЕРС» в должностях директора, заместителя начальника по хозяйственной работе. В 2014 году Андрей Иванович возвращается вновь на педагогическую работу в Карагандинский технико-строительный колледж старшим мастером производственного обучения. И здесь, производственный стаж работы, профессиональный опыт в качестве руководителя, безупречный авторитет, умение сплотить коллектив, организаторские способности Андрей Ивановича позволили в самый ответственный период деятельности колледжа, когда происходили серьезные перемены в развитии профессионального образования, смело и решительно взяться за дело и внести весомый вклад в деятельность учебного заведения. Многие преобразования в создании и организации работы учебно-производственных мастерских – дело рук и идей Андрей Ивановича. Андрей Иванович пользовался огромным авторитеом и уважением у студентов, коллег и руководства колледжа за глубокие знания в производственной сфере, умение находить общий язык, самостоятельно принимать решения, ответственный подход к любой работе.', '1742440411_ee.jpg', '2025-01-05 04:19:07', 'ветеран ктск', 'ЧЖЕН АНДРЕЙ ИВАНОВИЧ', 'ЧЖЕН АНДРЕЙ ИВАНОВИЧ', 'ZHENG, ANDREY IVANOVICH', 'Чжен Андрей Иванович родился в 1945 году в поселке Байназар, Шетского района Карагандинской области.\\\\r\\\\nПосле окончания школы поступил в ГРПУ №2 г. Караганды и после завершения обучения в 1962-1966 годах работал в должности мастера производственного обучения Карагандинского индустриально-педагогического техникума. Затем продолжил педагогическую деятельность в ГПТУ №59 г. Караганды также в одлжности мастера производственного обучения. В 1971 году Андрей Ивановича назначают директором ГПТУ №155 г. Каражал. И в этом же году о поступает в Карагандинский государственный университет имени Е.А.Букетова, который успешно заканчивает в качестве первого выпуска в 1976 году по специальности «Экономика и планирование, экномика материально-технического снабжения», полцчив квалификацию – экономист.\\\\r\\\\nВ 1973-1978 годах Андрей Иванович работал старшим мастером в ГПТУ №109 г. Караганды, затем в 1978-1983 годах возглавлял СПТУ №6.\\\\r\\\\n В 1985 году Андрей Иванович решил сменить педагогическую деятельность на производственную работу и возглавил в должности заместителя начальника управления ПМК-40. \\\\r\\\\nВ 1987-1990 годах работал в должности заместителя директора Ленинской плодоовощной базы, а в 1990-1995 годах заместителем директора облкоопторга и затем до 2014 года продолжил производственную деятельность в ТОО «ЮМЕРС» в должностях директора, заместителя начальника по хозяйственной работе.\\\\r\\\\nВ 2014 году Андрей Иванович возвращается вновь на педагогическую работу в Карагандинский технико-строительный колледж старшим мастером производственного обучения. \\\\r\\\\nИ здесь, производственный стаж работы, профессиональный опыт в качестве руководителя, безупречный авторитет, умение сплотить коллектив, организаторские способности Андрей Ивановича позволили в самый ответственный период деятельности колледжа, когда происходили серьезные перемены в развитии профессионального образования, смело и решительно взяться за дело и внести весомый вклад в деятельность учебного заведения. Многие преобразования в создании и организации работы учебно-производственных мастерских – дело рук и идей Андрей Ивановича.  \\\\r\\\\nАндрей Иванович пользовался огромным авторитеом и уважением у студентов, коллег и руководства колледжа за глубокие знания в производственной сфере, умение находить общий язык, самостоятельно принимать решения, ответственный подход к любой работе. \\\\r\\\\n', 'Чжен Андрей Иванович 1945 жылы Қарағанды облысы Шет ауданы Байназар кентінде дүниеге келген.\\r\\nМектепті бітіргеннен кейін Қарағанды қаласының №2 ГРУППУ-не түсіп, 1962-1966 жылдары оқуын аяқтағаннан кейін Қарағанды индустриалды-педагогикалық техникумының өндірістік оқыту шебері лауазымында жұмыс істеді. Содан кейін Қарағанды қаласының №59 ГПТУ-інде педагогикалық қызметін өндірістік оқыту шебері лауазымында жалғастырды. 1971 жылы Андрей Иванович Қаражал қаласының №155 ГПТУ директоры болып тағайындалды. Осы жылы о Е. А. Бөкетов атындағы Қарағанды мемлекеттік университетіне оқуға түседі, ол 1976 жылы \\\"Экономика және жоспарлау, материалдық-техникалық жабдықтау экономикасы\\\" мамандығы бойынша бірінші түлегі ретінде табысты бітіріп, экономист біліктілігін алады.\\r\\n1973-1978 жылдары Андрей Иванович Қарағанды қ. №109 ГПТУ-нде аға шебер болып жұмыс істеді, кейін 1978-1983 жылдары №6 СПТУ-сін басқарды.\\r\\n1985 жылы Андрей Иванович педагогикалық қызметін өндірістік жұмысқа ауыстыруға шешім қабылдады және ПМК-40 басқармасы бастығының орынбасары қызметін атқарады. \\r\\n1987-1990 жылдары Ленинск жеміс-көкөніс базасы директорының орынбасары, ал 1990-1995 жылдары облыстық коопторг директорының орынбасары, содан кейін 2014 жылға дейін \\\"ЮМЕРС\\\" ЖШС-де директор, шаруашылық жұмысы жөніндегі бастықтың орынбасары лауазымдарында өндірістік қызметін жалғастырды.\\r\\n2014 жылы Андрей Иванович Қарағанды техникалық-құрылыс колледжіне өндірістік оқытудың аға шебері болып педагогикалық жұмысқа қайта оралады. \\r\\nБұл жерде де өндірістік жұмыс өтілі, басшы ретіндегі кәсіби тәжірибесі, мінсіз беделі, ұжымды біріктіру қабілеті, Андрей Ивановичтің ұйымдастырушылық қабілеті колледж қызметінің ең жауапты кезеңінде, кәсіптік білім беруді дамытуда елеулі өзгерістер болып жатқанда, батыл және тура шешім қабылдап іске кірісуге және оқу орнының қызметіне елеулі үлес қосуға мүмкіндік берді. Оқу-өндірістік шеберханаларды құру мен ұйымдастырудағы көптеген өзгерістерде Андрей Ивановичтің қолдары мен идеяларының да іздері бар десек, қалт кетпейміз.  \\r\\nАндрей Иванович студенттердің, әріптестердің және колледж басшылығының өндірістік саладағы терең білімі, ортақ тіл таба білуі, өз бетінше шешім қабылдай білуі, кез келген жұмысқа жауапкершілікпен қарауы үшін зор беделі мен құрметіне ие болды. \\r\\n', 'Andrey Ivanovich Zheng was born in 1945 in the village of Baynazar, Shet district of Karaganda region.\\\\r\\\\nAfter graduating from school, he entered the State Pedagogical University No. 2 in Karaganda and after completing his studies in 1962-1966, he worked as a master of industrial training at the Karaganda Industrial and Pedagogical College. Then he continued his teaching career at the State Technical Technical University No. 59 in Karaganda, also as a master of industrial training. In 1971, Andrey Ivanovich was appointed director of the State Technical Technical University No. 155 in Karazhal. And in the same year, he entered the E.A.Buketov Karaganda State University, which he successfully graduated as the first graduate in 1976 with a degree in Economics and Planning, Economics of Logistics, and half-completed his degree in economics.\\\\r\\\\nIn 1973-1978, Andrey Ivanovich worked as a senior foreman at SPTU No. 109 in Karaganda, then in 1978-1983 he headed SPTU No. 6.\\\\r\\\\n In 1985, Andrey Ivanovich decided to switch from teaching to production work and took over as Deputy head of the PMK-40 department. \\\\r\\\\nIn 1987-1990, he worked as deputy director of the Lenin Fruit and Vegetable Base, and in 1990-1995 as deputy director of the regional wholesale trade and then continued his production activities at YUMERS LLP as director and Deputy head of economic work until 2014.\\\\r\\\\nIn 2014, Andrey Ivanovich returned to teaching at the Karaganda Technical and Civil Engineering College as a senior master of industrial training. \\\\r\\\\nHere, Andrey Ivanovich\\\\\\\'s work experience, professional experience as a supervisor, impeccable authority, ability to rally a team, and organizational abilities allowed him to boldly and decisively take up the task and make a significant contribution to the activities of the educational institution during the most crucial period of the college\\\\\\\'s activity, when serious changes were taking place in the development of professional education. Many of the transformations in the creation and organization of educational and production workshops are the work of Andrei Ivanovich\\\\\\\'s hands and ideas.  \\\\r\\\\nAndrey Ivanovich enjoyed great prestige and respect among students, colleagues and college management for his deep knowledge in the industrial field, the ability to find a common language, make decisions on his own, and take a responsible approach to any job.'),
(13, 'ЦОЙ ИСКРА НИКОЛАЕВНА', 'Цой Искра Николаевна родилась в поселке Жана-Корган Кызылординской области. После окончания школы поступила в КОПИ имени Н.В.Гоголя. Данное учебное заведение Искра Николаевна закончила в 1975 году получив специальность «учитель русского языка и литературы» и была направлена в сельскую школу №46 имени А.С.Пушкина Чиилийского района Кызылординской области. В данной школе проработала один учебный год и по семейным обстоятельствам сменила место жительства, переехав в город Караганда. Здесь Искра Николаевна продолжила свою педагогическую деятельность. В 1976-1980 годах она работала учителем русккого языка и литературы ШРМ №4 города Караганды. Особенность данной школы заключалась в том, что здесь учились взрослые люди, не получившие среднее образование. После трудового рабочего дня, они приходили в школу и занимались как обычные школьники. К ним нужен был особый подход, необходимо было разрабатывать и подбирать особые методические приемы и методы. При этом приходилось ориентироваться на их профессии, на особенности выполняемых ими на работе функций. За четыре учебных года в школе рабочей молодежи Искра Николаевна получила огромный педагогический и методический опыт работы с обучающимися, имеющих за плечами производственный стаж и решила продолжить педагогическую работу в профтехучлище №20 города Караганды, где проработала с 1980 по 1991 годы. В 1991 году Искра Николаевна переходит на педагогическую работу преподавателем русского языка и литературы в ПЛ №26 (ныне Карагандинский технико-строительный колледж). Здесь Искра Николаевна проработала более 20-ти лет и в 2013 году вышла на заслуженный отдых. За многолетний и плодотворный труд в деле подготовки технических кадров, Искра Николаевна неоднократно награждалась Почетными грамотами и благодарственными письмами от органов управления образования.', '6.jpg', '2025-01-05 04:20:06', 'ветеран ктск', 'ЦОЙ ИСКРА НИКОЛАЕВНА', 'ЦОЙ ИСКРА НИКОЛАЕВНА', 'TSOI ISKRA NIKOLAEVNA', 'Цой Искра Николаевна родилась в поселке Жана-Корган Кызылординской области. После окончания школы поступила в КОПИ имени Н.В.Гоголя. Данное учебное заведение Искра Николаевна закончила в 1975 году получив специальность «учитель русского языка и литературы» и была направлена в сельскую школу №46 имени А.С.Пушкина Чиилийского района Кызылординской области.\\r\\nВ данной школе проработала один учебный год и по семейным обстоятельствам сменила место жительства, переехав в город Караганда. Здесь Искра Николаевна продолжила свою педагогическую деятельность. \\r\\nВ 1976-1980 годах она работала учителем русккого языка и литературы ШРМ №4 города Караганды. Особенность данной школы заключалась в том, что здесь учились взрослые люди, не получившие среднее образование. После трудового рабочего дня, они приходили в школу и занимались как обычные школьники. К ним нужен был особый подход, необходимо было разрабатывать и подбирать особые методические приемы и методы. При этом приходилось ориентироваться на их профессии, на особенности выполняемых ими на работе функций.\\r\\nЗа четыре учебных года в школе рабочей молодежи Искра Николаевна получила огромный педагогический и методический опыт работы с обучающимися, имеющих за плечами производственный стаж и решила продолжить педагогическую работу в профтехучлище №20 города Караганды, где проработала с 1980 по 1991 годы.\\r\\nВ 1991 году Искра Николаевна переходит на педагогическую работу преподавателем русского языка и литературы в ПЛ №26 (ныне Карагандинский технико-строительный колледж). Здесь Искра Николаевна проработала более 20-ти лет и в 2013 году вышла на заслуженный отдых. \\r\\nЗа многолетний и плодотворный труд в деле подготовки технических кадров, Искра Николаевна неоднократно награждалась Почетными грамотами и благодарственными письмами от органов управления образования.\\r\\n', 'Цой Искра Николаевна Қызылорда облысы Жаңақорған ауылында дүниеге келген. Мектепті бітіргеннен кейін Н. В. Гоголь атындағы Қызылорда педагогикалық институтына түседі. Искра Николаевна бұл оқу орнын 1975 жылы \\\"Орыс тілі мен әдебиеті мұғалімі\\\" мамандығы бойынша бітіріп, Қызылорда облысы Шиелі ауданының А. С. Пушкин атындағы №46 ауылдық мектебіне жіберілді.\\r\\nБұл мектепте бір жыл жұмыс істеп, отбасылық жағдай бойынша тұрғылықты жерін ауыстырып, Қарағанды қаласына көшті. Мұнда Искра Николаевна өзінің педагогикалық қызметін жалғастырды. \\r\\n1976-1980 жылдары Қарағанды қаласының №4 ШРМ орыс тілі мен әдебиеті пәнінің мұғалімі болып жұмыс істеді. Бұл мектептің ерекшелігі-мұнда орта білім алмаған ересектер оқыды. Жұмыс күнінен кейін олар мектепке келіп, қарапайым мектеп оқушылары сияқты білім алатын. Оларға ерекше тәсіл қажет болды, арнайы әдістемелік әдістер мен көрнекіліктерді әзірлеу және таңдау қажет болды. Бұл ретте олардың кәсібіне, жұмыста атқаратын функцияларының ерекшеліктеріне назар аударуға тура келді.\\r\\nЖұмысшы жастар мектебіндегі төрт оқу жылында Искра Николаевна өндірістік өтілі бар білім алушылармен үлкен педагогикалық және әдістемелік тәжірибе алды және Қарағанды қаласының №20 кәсіптік училищесінде педагогикалық жұмысты жалғастыруға шешім қабылдады. Онда 1980-1991 жылдары жұмыс істеді.\\r\\n1991 жылы Искра Николаевна №26 ПЛ (қазіргі Қарағанды техникалық-құрылыс колледжі) орыс тілі мен әдебиеті пәнінің оқытушысы болып педагогикалық жұмысқа ауысады. Мұнда Искра Николаевна 20 жылдан астам жұмыс атқарып, 2013 жылы лайықты еңбек демалысына шықты. \\r\\nТехникалық кадрларды даярлау ісіндегі көпжылдық және жемісті еңбегі үшін Искра Николаевна бірнеше рет білім басқармасы органдарының Құрмет грамоталарымен және алғыс хаттарымен марапатталды.\\r\\n', 'Tsoi Iskra Nikolaevna Kyzylorda oblysy Zhanakorgan auylynda duniege kelgen. Mektepti bitirgenennen kein N. V. Gogol atyndagi Kyzylorda Pedagogical Institute in Tusedi. Iskra Nikolaevna born 1975 zhyly \\\"Orys tіli men adebieti mugalіmі\\\" mamandygy boyynsha bitirip, Kyzylorda oblysy Shieli audanynyn A. S. Pushkin atyndagy No. 46 ouyldyk mektebіne zhіberildi.\\r\\nBe sure to remove the heat, drain the water, and wash the water. Munda Iskra Nikolaevna ozіnіn pedagogicalyk kyzmetіn zhalgastyrdy.\\r\\n1976-1980 zhildars of Karaganda kalasynyn No. 4 ShRM orys tili men adebieti paninin mugalimi bolyp zhumys іsteadi. Bul mekteptin ereksheligi-munda orta bilim almagan erekseker okydy. Zhumys kuninen kein olar mektepke kelip, karapaim mektep okushylar siyakty bіlіm alatyn. Olarga erekshe tasil kazhet bolds, arnay adistemelik adister men kornekilikterdi azirleu zhane tandau kazhet bolds. Bul rette olardyn kasibine, zhumysta atkaratyn functionlaryn erekshelikterine nazar audaruga tour keldi.\\r\\nZhumyshy zhastar mektebindegi tort oku zhylynda Iskra Nikolaevna Ondiristik otili bar bilim alushylarmen ulken pedagogikalyk zhane adistemelik tazhiribe aldy zhane Karagandy kalasynyn No. 20 regarding the sanitation of the school of pedagogical sciences is a pity for our work. Onda 1980-1991 zhyldary zhumys istedi.\\r\\n1991 years Iskra Nikolaevna No. 26 PL (Kazirghi Karaganda technical colleges) orys tіlі men adebietі pәnіnің about kytyushysy bolíp pedagogikalyk zhumyska auysady. Munda Iskra Nikolaevna 20 zhyldan astam zhumys atkaryp, 2013 zhyly layykty enbek demalysyna shykty.\\r\\nTechniques cadres data іsіndегі көпжылдиқ зән змісті еңбеги үшін Iskra Nikolaevna bіrneshe ret bіlіm baskarmasy organdarynѣ Құрмет тормісті еңне алыс khattarimen marapattaldy.'),
(14, 'ОСПАНОВА ҚАРЛЫҒАШ АСАНОВНА', 'Оспанова Карлыгаш Асановна родилась ы 1960 году в пос. Ростовка Карагандинской области. После окончания школы трудовую деятельность начала в Домостроительном комбинате треста «КарагандаЖилСтрой», где проработала в 1977-1979 годах штукатур-маляром. В 1980 году поступает на учебу в Карагандинский государственный университет имени Е.А.Букетова, который заканчивает в 1985 году, получив квалификацию «Преподаватель истории и обществоведения». После окончания вуза поступила на работу в среднюю школу пос. Кызылжар заместителем директора по учебной работе, где проработала с 1985-1989 гг. В 1989 году продолжила педагогическую деятельность в качестве преподавателя истории в СПТУ №26, где проработала до февраля 1992 года. Затем Карлыгаш Асановна была приглашена на должность заместителя директора по учебной работе в Карагандинский техникум физкультуры и спорта. В 1993 году Карлыгаш Асановна вновь возвращается в СПТУ №26, ныне Карагандинский технико-строительный колледж, где проработала преподавателем истории, затем заместителем директора по воспитательной работе, а затем директором колледжа с 2001 по 2009 годы. В 2009-2012 годах работала методистом, заведующей центром развития ТиПО в Карагандинском институте повышения квалификации и переподготовки работников образования. В 2012-2013 годах Карлыгаш Асановна продолжила трудовую деятельность в должности заместителя директора Учебно-методического центра развития образования Карагандинской области. В 2013 году Карлыгаш Асановну приглашают на работу в Палату предпринимателей Карагандинской области, где работала в различных руководящих должностях. За многолетний и плодотворный труд в системе профессионального образования, Карлыгаш Асановна неоднократно награждалась Почетными грамотами, благодарственными письмами, награждена медалью имени Ы.Алтынсарин, юбилейной медалью «20 лет Независимости Республики Казахстан».', '1748844116_Рисунок1.png', '2025-01-05 04:20:38', 'ветеран ктск', 'ОСПАНОВА КАРЛЫГАШ АСАНОВНА', 'ОСПАНОВА ҚАРЛЫГАШ АСАНОВНА', 'OSPANOVA KARLYGASH ASANOVNA', 'Оспанова Карлыгаш Асановна родилась ы 1960 году в пос. Ростовка Карагандинской области.\\\\r\\\\nПосле окончания школы трудовую деятельность начала в Домостроительном комбинате треста «КарагандаЖилСтрой», где проработала в 1977-1979 годах штукатур-маляром.\\\\r\\\\nВ 1980 году поступает на учебу в Карагандинский государственный университет имени Е.А.Букетова, который заканчивает в 1985 году, получив квалификацию «Преподаватель истории и обществоведения».\\\\r\\\\nПосле окончания вуза поступила на работу в среднюю школу пос. Кызылжар заместителем директора по учебной работе, где проработала с 1985-1989 гг.\\\\r\\\\nВ 1989 году продолжила педагогическую деятельность в качестве преподавателя истории в СПТУ №26, где проработала до февраля 1992 года. Затем Карлыгаш Асановна была приглашена на должность заместителя директора по учебной работе в Карагандинский техникум физкультуры и спорта.\\\\r\\\\nВ 1993 году Карлыгаш Асановна вновь возвращается в СПТУ №26, ныне Карагандинский технико-строительный колледж, где проработала преподавателем истории, затем заместителем директора по воспитательной работе, а затем директором колледжа с 2001 по 2009 годы.\\\\r\\\\nВ 2009-2012 годах работала методистом, заведующей центром развития ТиПО в Карагандинском институте повышения квалификации и переподготовки работников образования.\\\\r\\\\nВ 2012-2013 годах Карлыгаш Асановна продолжила трудовую деятельность в должности заместителя директора Учебно-методического центра развития образования Карагандинской области.\\\\r\\\\nВ 2013 году Карлыгаш Асановну приглашают на работу в Палату предпринимателей Карагандинской области, где работала в различных руководящих должностях.\\\\r\\\\nЗа многолетний и плодотворный труд в системе профессионального образования, Карлыгаш Асановна неоднократно награждалась Почетными грамотами, благодарственными письмами, награждена медалью имени Ы.Алтынсарин, юбилейной медалью «20 лет Независимости Республики Казахстан».\\\\r\\\\n', 'Оспанова Қарлығаш Асанова 1960 жылы Қарағанды облысының Ростовка кентінде дүниеге келген.\\r\\nМектепті бітіргеннен кейін еңбек жолын «Қарагандыжилстрой» трестінің үй құрылысы комбинатында бастады, онда 1977-1979 жылдары сылақшы-суретші болып жұмыс атқарған.\\r\\n1980 жылы Е.А. Бөкетов атындағы Қарағанды мемлекеттік университетіне оқуға түсіп, 1985 жылы «Тарих және қоғамтану пәнінің оқытушысы» біліктілігін алды.\\r\\nЖОО-нын бітіргеннен кейін Қызылжар кентінің орта мектебіне 1985-1989 жыл аралығында директордың оқу ісі жөніндегі орынбасары қызметін атқарады.\\r\\n1989 жылы № 26 СПТУ-да тарих пәнінің оқытушысы ретінде педагогикалық қызметін жалғастырып, 1992 жылдың ақпанына дейін жұмыс істеді. Содан кейін Қарлығаш Асанова Қарағанды дене шынықтыру және спорт техникумына директордың оқу ісі жөніндегі орынбасары қызметіне шақырылды.\\r\\n1993 жылы Қарлығаш Асанқызы №26 СПТУ-ға, қазіргі Қарағанды техникалық-құрылыс колледжіне қайта оралып, онда тарих пәнінің оқытушысы, кейін директордың тәрбие ісі жөніндегі орынбасары, кейін 2001-2009 жылдары колледж директоры болып жұмыс істеді.\\r\\n2009-2012 жылдары Қарағанды білім беру қызметкерлерінің біліктілігін арттыру және қайта даярлау институтында әдіскер, Типті дамыту орталығының меңгерушісі болып жұмыс істеді.\\r\\n2012-2013 жылдары Қарлығаш Асанова еңбек жолын Қарағанды облысының білім беруді дамыту оқу-әдістемелік орталығы директорының орынбасары лауазымында жалғастырды.\\r\\n2013 жылы Қарлығаш Асанқызы Қарағанды облысының кәсіпкерлер палатасына жұмысқа шақырылып, түрлі басшылық лауазымдарда жұмыс істеді.\\r\\nКәсіптік білім беру жүйесіндегі көпжылдық және жемісті еңбегі үшін Қарлығаш Асанқызы бірнеше рет Құрмет грамоталарымен, алғыс хаттармен марапатталды, Ы. Алтынсарин атындағы медальмен, \\\"Қазақстан Республикасының Тәуелсіздігіне 20 жыл\\\"мерейтойлық медалімен марапатталды. \\r\\n', 'Ospanova Karlygash Asanovna was born in 1960 in the village of Rostovka, Karaganda region.\\r\\nAfter finishing school, she began her career at the House-Building Plant of the KaragandaZhilStroy Trust, where she worked as a plasterer and painter from 1977 to 1979.\\r\\nIn 1980, she entered the Karaganda State University named after E.A. Buketov, which she graduated from in 1985, receiving the qualification of \\\"Teacher of History and Social Science\\\".\\r\\nAfter graduating from the university, she went to work at the secondary school in the village of Kyzylzhar as a deputy director for academic work, where she worked from 1985 to 1989.\\r\\nIn 1989, she continued her teaching career as a history teacher at Vocational School No. 26, where she worked until February 1992. Then Karlygash Asanovna was invited to the position of deputy director for academic work at the Karaganda College of Physical Education and Sports.\\r\\nIn 1993, Karlygash Asanovna returned to SPTU No. 26, now the Karaganda Technical and Construction College, where she worked as a history teacher, then deputy director for educational work, and then director of the college from 2001 to 2009.\\r\\nIn 2009-2012, she worked as a methodologist, head of the center for the development of technical and vocational education at the Karaganda Institute for Advanced Training and Retraining of Education Workers.\\r\\nIn 2012-2013, Karlygash Asanovna continued her career as deputy director of the Educational and Methodological Center for the Development of Education of the Karaganda Region.\\r\\nIn 2013, Karlygash Asanovna was invited to work in the Chamber of Entrepreneurs of the Karaganda Region, where she worked in various leadership positions.\\r\\nFor many years of fruitful work in the system of professional education, Karlygash Asanovna was repeatedly awarded with Certificates of Honor, letters of gratitude, was awarded the medal named after Y. Altynsarin, the jubilee medal \\\"20 years of Independence of the Republic of Kazakhstan\\\".');
INSERT INTO `veterans` (`id`, `name`, `biography`, `photo`, `created_at`, `rank`, `name_ru`, `name_kz`, `name_en`, `biography_ru`, `biography_kz`, `biography_en`) VALUES
(15, 'ФАРТУШКЕВИЧ ВЛАДИМИР ИВАНОВИЧ', 'Человек живет столько, сколько хранится память о нем… Среди людей, сыгравших заметную роль в развитии технического и профессионального образования, есть имя, вписанное золотыми буквами в историю нашего колледжа - имя мастера производственного обучения Фартушкевич Владимира Ивановича. Владимир Иванович родился 14 июня 1952 года в г. Караганде. После окончания школы поступил в Карагандинское профессиональное училище №59, где в 1969 году получил профессию электромонтажника 4 разряда по осветительным сетям и силовому электрооборудованию. В 1967 году, по запросу Карагандинского обкома партии в числе лучших выпускников ГПТУ №59, Фартушкевич В.И. был направлен на работу в областную студию телевидения г. Караганды. Владимир Иванович успешно совмещал работу по специальности с обучением на курсах журналистики и режиссерского мастерства при университете марксизма-ленинизма. В 1970 года Владимир Иванович служил в рядах Вооруженных сил СССР на Северном флоте. За два года прошел путь от рядового до старшего сержанта. Служил в должности командира взвода электромехаников плавающих средств специального назначения. После демобилизации, продолжил работу на телевидении. В 1983 году был приглашен руководством родного ГПТУ №59 на работу в качестве мастера производственного обучения. Для получения педагогического образования, Владимир Иванович окончил Карагандинский индустриально-педагогический техникум, чтобы в качестве мастера передавать свой опыт таким же ребятам, каким когда-то был сам. В 1997 году Владимир Иванович был переведен в СПТУ №26 (ныне Карагандинский технико-строительный колледж), где до последнего дня проработал в должности мастера производственного обучения. На своих занятиях Владимир Иванович учил ребят овладевать знаниями электромонтажной техники, быть думающими и творческими, трудолюбивыми и коммуникабельными и профессионально мобильными. Недаром, под руководством Владимира Ивановича, студенты колледжа становились призерами и победителями городских, областных и республиканских конкурсов технического творчества. Студенты кружка технического творчества, бессменным руководителем которого был Владимир Иванович, занимались изобретением, а также вносили рационализаторские предложения по совершенствованию технических приборов. И, безусловно, становились неоднократными победителями городских, областных конкурсов «Жас Талап». Так, в 2006 году в областном конкурсе прибор «Муравей -1» был удостоен 1-го места, а в 2010 году прибор «Скат-1» также занял 1-ое место. В 2012 году изобретение действующей модели автоматизированной экологической установки непрерывной циркуляции и очистки воды в плавательных бассейнах общественных и частных зданий «АМФИБИЯ-1» был отмечен сертификатом участника городской выставки инновационных, социальных и архитектурно-строительных, художественных работ молодежи города Караганды «Я и мир вокруг меня» в рамках республиканской кампании «Будущее начинается сегодня». Эта же модель была отмечена ценным призом и сертификатом третьего Республиканского конкурса энергосберегающих и экоохранных идей «Эргономика будущего». Это же изобретение отмечено сертификатом городской выставки инновационных, социальных проектов в рамках Республиканской компании «Будущее начинается сегодня». В 2013 году прибор «АМФИБИЯ-1» был использован в проекте «Дом моей мечты» и в рамках конкурса инновационных проектов «Молодежь –ЭКСПО 2017», занял 1 место с денежной премией в 100 тысяч тенге. Этот же проект занял І место во ІІ конкурсе научных работ школьников и студентов «Жас Ғалым». Владимир Иванович подготовил сотни рабочих - специалистов для производства. Многие его выпускники ныне работают в качестве руководителей предприятий в Казахстане и за рубежом. Многолетний и созидательный труд педагога Фартушкевич Владимир Ивановича в деле подготовки специалистов для энергетической отрасли был отмечен множеством благодарственных писем и грамот. Награды: 1989 г. Награжден медалью «Ветеран труда». 2004 г. Благодарственное письмо управления образования Карагандинской области. 2008 г. Почетная грамота управления образования Карагандинской области. 2010 г. Диплом Карагандинского городского филиала НДП «Нұр Отан». 2012 г. Благодарственное письмо начальника Отдела Внутренней политики города Караганды и директора негосударственного учреждения «Детство». 2012 г. Диплом и благодарственное письмо за участие в Республиканской выставке технического творчества студентов ТиПО в первом Молодежном Республиканском слете «Кәсіп. KZ». 2012 г. Грамота Областного комитета профсоюза науки и образования. 2012 г. Диплом и премия в номинации «Лучший мастер производственного обучения» Акима Карагандинской области. 2012 г. Кандидатура одобрена к включению в «Элитную книгу «КТО есть КТО» в системе технического и профессионального образования Республики Казахстан» решением республиканской комиссии Совета директоров учебных заведений технического и профессионального образования. 2014 г. Благодарственное письмо Министра образования и науки РК. 2019 г. Благодарственное письмо Управления образования Карагандинской области. 2020 г. Почетная грамота Управления образования Карагандинской области.', '8.jpg', '2025-01-05 04:20:59', 'ветеран ктск', 'ФАРТУШКЕВИЧ ВЛАДИМИР ИВАНОВИЧ', 'ФАРТУШКЕВИЧ ВЛАДИМИР ИВАНОВИЧ', 'FARTUSHKEVICH VLADIMIR IVANOVICH', 'Человек живет столько, сколько хранится память о нем… Среди людей, сыгравших заметную роль в развитии технического и профессионального образования, есть имя, вписанное золотыми буквами в историю нашего колледжа - имя мастера производственного обучения Фартушкевич Владимира Ивановича.\\r\\nВладимир Иванович родился 14 июня 1952 года в г. Караганде. После окончания школы поступил в Карагандинское профессиональное училище №59, где в 1969 году получил профессию электромонтажника 4 разряда по осветительным сетям и силовому электрооборудованию.\\r\\nВ 1967 году, по запросу Карагандинского обкома партии в числе лучших выпускников ГПТУ №59, Фартушкевич В.И.  был направлен на работу в областную студию телевидения г. Караганды. Владимир Иванович успешно совмещал работу по специальности с обучением на курсах журналистики и режиссерского мастерства при университете марксизма-ленинизма. \\r\\nВ 1970 года Владимир Иванович служил в рядах Вооруженных сил СССР на Северном флоте. За два года прошел путь от рядового до старшего сержанта. Служил в должности командира взвода электромехаников плавающих средств специального назначения. После демобилизации, продолжил работу на телевидении. \\r\\nВ 1983 году был приглашен руководством родного ГПТУ №59 на работу в качестве мастера производственного обучения.  Для получения педагогического образования, Владимир Иванович окончил Карагандинский индустриально-педагогический техникум, чтобы в качестве мастера передавать свой опыт таким же ребятам, каким когда-то был сам. \\r\\nВ 1997 году Владимир Иванович был переведен в СПТУ №26 (ныне Карагандинский технико-строительный колледж), где до последнего дня проработал в должности мастера производственного обучения. \\r\\nНа своих занятиях Владимир Иванович учил ребят овладевать знаниями электромонтажной техники, быть думающими и творческими, трудолюбивыми и коммуникабельными и профессионально мобильными. Недаром, под руководством Владимира Ивановича, студенты колледжа становились призерами и победителями городских, областных и республиканских конкурсов технического творчества. \\r\\nСтуденты кружка технического  творчества, бессменным руководителем которого был Владимир Иванович, занимались изобретением, а также вносили рационализаторские предложения по совершенствованию технических  приборов. И, безусловно, становились неоднократными  победителями городских, областных  конкурсов  «Жас Талап». \\r\\nТак, в 2006 году в областном конкурсе прибор «Муравей -1» был удостоен 1-го места, а в 2010 году прибор «Скат-1» также занял 1-ое место. \\r\\nВ 2012 году изобретение действующей модели автоматизированной экологической установки непрерывной циркуляции и очистки воды в плавательных бассейнах общественных и частных зданий «АМФИБИЯ-1» был отмечен сертификатом участника городской выставки инновационных, социальных и архитектурно-строительных, художественных работ молодежи города Караганды «Я и мир вокруг меня» в рамках республиканской кампании «Будущее начинается сегодня». Эта же модель была отмечена ценным призом и сертификатом третьего Республиканского конкурса энергосберегающих и экоохранных идей «Эргономика будущего».  Это же изобретение отмечено сертификатом городской выставки инновационных, социальных проектов в рамках Республиканской компании «Будущее начинается сегодня».   \\r\\nВ 2013 году прибор «АМФИБИЯ-1» был использован в проекте «Дом моей мечты» и в рамках конкурса инновационных проектов «Молодежь –ЭКСПО 2017», занял 1 место с денежной премией в 100 тысяч тенге. Этот же проект занял І место во ІІ конкурсе научных работ школьников и студентов «Жас Ғалым».\\r\\nВладимир Иванович подготовил сотни рабочих - специалистов для производства. Многие его выпускники ныне работают в качестве руководителей предприятий в Казахстане и за рубежом.\\r\\nМноголетний и созидательный труд педагога Фартушкевич Владимир Ивановича в деле подготовки специалистов для энергетической отрасли был отмечен множеством благодарственных писем и грамот. \\r\\n\\r\\n Награды:\\r\\n1989 г. Награжден медалью «Ветеран труда». \\r\\n2004 г. Благодарственное письмо управления образования Карагандинской области. \\r\\n2008 г. Почетная грамота управления образования Карагандинской области. \\r\\n2010 г. Диплом Карагандинского городского филиала НДП «Нұр Отан». \\r\\n2012 г. Благодарственное письмо начальника Отдела Внутренней политики города Караганды и директора негосударственного учреждения «Детство». \\r\\n2012 г. Диплом и благодарственное письмо за участие в Республиканской выставке технического творчества студентов ТиПО в первом Молодежном Республиканском слете «Кәсіп. KZ».\\r\\n2012 г. Грамота Областного комитета профсоюза науки и образования. \\r\\n2012 г. Диплом и премия в номинации «Лучший мастер производственного обучения» Акима Карагандинской области.\\r\\n2012 г. Кандидатура одобрена к включению в «Элитную книгу «КТО есть КТО» в системе технического и профессионального образования Республики Казахстан» решением республиканской комиссии Совета директоров учебных заведений технического и профессионального образования.\\r\\n2014 г. Благодарственное  письмо  Министра образования и науки РК.\\r\\n2019 г. Благодарственное  письмо  Управления образования Карагандинской области.\\r\\n2020 г. Почетная грамота Управления образования Карагандинской области.\\r\\n\\r\\n\\r\\n', 'Кісі есімі ұлағатымен қанша сақталса, сонша өмір сүреді... . Сондай жандардың арасында техникалық және кәсіптік білім беруді дамытуда елеулі рөл атқарған, біздің колледж тарихында алтын әріптермен жазылған есім - өндірістік оқыту шебері Владимир Иванович Фартушкевич.\\r\\nВладимир Иванович 1952 жылы 14 маусымда Қарағандыда дүниеге келген.\\r\\n Мектепті бітіргеннен кейін №59 Қарағанды кәсіптік училищесіне түсіп, 1969 жылы жарықтандыру желілері мен күштік электржабдықтары бойынша 4-разрядты электромонтажшы мамандығын алды.\\r\\n1967 жылы Қарағанды облыстық партия комитетінің сұранысымен №59 ГПТУ үздік түлектерінің қатарында В.И. Фартушкевич Қарағанды қаласының облыстық телевизия студиясына жұмысқа жіберілді. Владимир Иванович мамандығы бойынша жұмысты марксизм-ленинизм университетінің журналистика және режиссерлік шеберлік курстарында оқумен сәтті ұштастырды. \\r\\n1970 жылы Владимир Иванович Солтүстік флотта КСРО Қарулы Күштерінің қатарында қызмет етті. Екі жыл ішінде қатардағы жауынгерден аға сержантқа дейінгі жолды өтті. Арнайы мақсаттағы қалқымалы құралдардың электромеханиктері взводының командирі қызметін атқарды. Демобилизациядан кейін ол теледидарда жұмысын жалғастырды.\\r\\n1983 жылы өзі бітірген №59 ГПТУ  басшылығының ұсынысымен өндірістік оқыту шебері лауазымына жұмысқа шақырылды. Педагогикалық білім алу үшін Владимир Иванович Қарағанды индустриалды-педагогикалық техникумын бітіріп, өз тәжірибесін шебер ретінде бір кездері өзі сияқты болған балаларға дарытудан бастап кетті.. \\r\\n1997 жылы Владимир Иванович №26 СПТУ-ға (қазіргі Қарағанды техника-құрылыс колледжі) ауыстырылды. Аталған колледжде соңғы күнге дейін өндірістік оқыту шебері болып жұмыс атқарды.\\r\\nӨз сабақтарында Владимир Иванович балаларға электрмонтаждау техникасы туралы білімді меңгеруге, ойлауға және шығармашылыққа, еңбекқор, коммуникативті және кәсіби мобильді болуға үйретті. Владимир Ивановичтің басшылығымен колледж студенттері қалалық, облыстық және республикалық техникалық шығармашылық конкурстарының жүлдегерлері мен жеңімпаздары болғаны бекер емес. \\r\\nВладимир Иванович тұрақты жетекшілік еткен техникалық шығармашылық үйірменің студенттері өнертапқыштықпен айналысты, сондай-ақ техникалық аспаптарды жетілдіру бойынша рационализаторлық ұсыныстар енгізді. Сөзсіз, қалалық, облыстық «Жас Талап» байқауларының бірнеше дүркін жеңімпаздары атанды. \\r\\nМәселен, 2006 жылы облыстық байқауда «Құмырсқа -1» аспабы 1-нші орынға ие болды, ал 2010 жылы «Скат-1» аспабы да 1-нші орынға ие болды.\\r\\n2012 жылы «АМФИБИЯ-1» қоғамдық және жеке ғимараттарының жүзу бассейндерінде үздіксіз айналым мен суды тазартудың автоматтандырылған экологиялық қондырғысының қолданыстағы моделін ойлап табу «Болашақ бүгіннен басталады» республикалық науқаны аясында Қарағанды қаласы жастарының инновациялық, әлеуметтік және сәулет-құрылыс, көркемсурет жұмыстарының қалалық көрмесіне қатысушының сертификатымен марапатталды. Дәл осы модель «Болашақ эргономикасы» энергия үнемдеу және экоқорғау идеяларының үшінші республикалық байқауының бағалы сыйлығымен және сертификатымен марапатталды. Дәл осы өнертабыс «Болашақ бүгіннен басталады» республикалық компаниясы аясындағы инновациялық, әлеуметтік жобалардың қалалық көрмесінің сертификатымен атап өтілді.   \\r\\n2013 жылы «АМФИБИЯ-1» аспабы «Менің арманымдағы үй» жобасында және «Жастар –ЭКСПО 2017» инновациялық жобалар конкурсы шеңберінде пайдаланылды. 100 мың теңгелік ақшалай сыйлықпен 1-орынға ие болды. Осы жоба оқушылар мен студенттердің «Жас Ғалым» ғылыми жұмыстарының ІІ байқауында І- орын алды.\\r\\nВладимир Иванович өндіріске жүздеген жұмысшы мамандарды дайындады. Оның көптеген түлектері қазір Қазақстанда және шетелде кәсіпорындардың басшылары да болып жұмыс атқаруда.\\r\\nПедагог Владимир Иванович Фартушкевичтің энергетика саласына мамандар даярлау ісіндегі көпжылдық және жасампаз еңбегі көптеген Алғыс хаттар және грамоталармен марапатталды. \\r\\n\\r\\nМарапаттаулары:\\r\\n1989 ж. «Еңбек ардагері» медалімен марапатталған.\\r\\n2004 ж. Қарағанды облысы білім басқармасының Алғыс хаты.\\r\\n2008 ж. Қарағанды облысы білім басқармасының Құрмет грамотасы.\\r\\n2010 ж. «Нұр Отан» ХДП Қарағанды қалалық филиалының дипломы.\\r\\n2012 ж. Қарағанды қаласының Ішкі саясат бөлімі бастығының және «Детство» мемлекеттік емес мекемесі директорының Алғыс хаты.\\r\\n2012 ж. ТжКБ студенттерінің техникалық шығармашылығының Республикалық көрмесіне, «Кәсіп. KZ» алғашқы Жастар республикалық слетіне қатысқаны үшін Диплом және Алғыс хат.\\r\\n2012 ж. Облыстық ғылым және білім кәсіподағы комитетінің грамотасы.\\r\\n2012 ж.Қарағанды облысы әкімінің «Өндірістік оқытудың үздік шебері» номинациясы бойынша Диплом және сыйлық.\\r\\n2012 ж.  Техникалық және кәсіптік білім беру оқу орындарының директорлар кеңесінің республикалық комиссиясының шешімімен кандидатурасы  «Қазақстан Республикасының техникалық және кәсіптік білім беру жүйесінде «Кім кім екен» элиталық кітабына енгізуге мақұлданды.\\r\\n2014 ж. ҚР Білім және ғылым Министрінің Алғыс хаты.\\r\\n2019 ж. Қарағанды облысы білім басқармасының Алғыс хаты.\\r\\n2020 ж. Қарағанды облысы білім басқармасының Құрмет грамотасы.\\r\\n\\r\\n\\r\\n', 'A person lives as long as the memory of him is preserved... Among the people who played a significant role in the development of technical and vocational education, there is a name inscribed in gold letters in the history of our college - the name of the master of industrial training Fartushkevich Vladimir Ivanovich.\\r\\nVladimir Ivanovich was born on June 14, 1952 in Karaganda. After graduating from school, he entered the Karaganda vocational school No. 59, where in 1969 he received the profession of a 4th-category electrician for lighting networks and power electrical equipment.\\r\\nIn 1967, at the request of the Karaganda regional party committee, among the best graduates of GPTU No. 59, Fartushkevich V.I. was sent to work in the regional television studio of Karaganda. Vladimir Ivanovich successfully combined work in his specialty with training in journalism and directing courses at the University of Marxism-Leninism.\\r\\nIn 1970, Vladimir Ivanovich served in the ranks of the USSR Armed Forces in the Northern Fleet. In two years, he rose from private to senior sergeant. He served as a platoon commander of electrical mechanics of special-purpose floating craft. After demobilization, he continued working in television.\\r\\nIn 1983, he was invited by the management of his native GPTU No. 59 to work as a master of industrial training. To obtain a pedagogical education, Vladimir Ivanovich graduated from the Karaganda Industrial and Pedagogical College in order to pass on his experience as a master to the same guys as he once was.\\r\\nIn 1997, Vladimir Ivanovich was transferred to SPTU No. 26 (now the Karaganda Technical and Construction College), where he worked until his last day as a master of industrial training.\\r\\nIn his classes, Vladimir Ivanovich taught the guys to master the knowledge of electrical installation equipment, to be thoughtful and creative, hardworking and sociable and professionally mobile. It is not for nothing that, under the leadership of Vladimir Ivanovich, college students became prize winners and winners of city, regional and republican competitions of technical creativity.\\r\\nStudents of the technical creativity circle, whose permanent leader was Vladimir Ivanovich, were engaged in inventions, and also made rationalization proposals for the improvement of technical devices. And, of course, they became multiple winners of city and regional competitions \\\"Zhas Talap\\\".\\r\\nThus, in 2006, the \\\"Muravei-1\\\" device was awarded 1st place in the regional competition, and in 2010, the \\\"Skat-1\\\" device also took 1st place.\\r\\nIn 2012, the invention of a working model of an automated ecological installation for continuous circulation and purification of water in swimming pools of public and private buildings \\\"AMPHIBIA-1\\\" was awarded a certificate of participation in the city exhibition of innovative, social and architectural-construction, artistic works of the youth of the city of Karaganda \\\"Me and the World Around Me\\\" as part of the republican campaign \\\"The Future Begins Today\\\". The same model was awarded a valuable prize and a certificate of the third Republican competition of energy-saving and eco-friendly ideas \\\"Ergonomics of the Future\\\". The same invention was awarded a certificate of the city exhibition of innovative, social projects within the framework of the Republican company \\\"The Future Begins Today\\\".\\r\\nIn 2013, the \\\"AMPHIBIA-1\\\" device was used in the \\\"House of My Dreams\\\" project and within the framework of the competition of innovative projects \\\"Youth - EXPO 2017\\\", took 1st place with a cash prize of 100 thousand tenge. The same project took 1st place in the 2nd competition of scientific works of schoolchildren and students \\\"Zhas Galym\\\".\\r\\nVladimir Ivanovich trained hundreds of workers - specialists for production. Many of his graduates now work as heads of enterprises in Kazakhstan and abroad.\\r\\nThe long-term and creative work of the teacher Fartushkevich Vladimir Ivanovich in training specialists for the energy industry was noted by many letters of thanks and certificates.\\r\\n\\r\\nAwards:\\r\\n1989 Awarded the \\\"Veteran of Labor\\\" medal.\\r\\n\\r\\n2004 Letter of thanks from the Karaganda Region Education Department.\\r\\n\\r\\n2008 Certificate of honor from the Karaganda Region Education Department.\\r\\n\\r\\n2010 Diploma of the Karaganda City Branch of the NDP \\\"Nur Otan\\\".\\r\\n\\r\\n2012 Letter of thanks from the Head of the Internal Policy Department of the city of Karaganda and the Director of the non-governmental institution \\\"Childhood\\\".\\r\\n\\r\\n2012 Diploma and letter of thanks for participation in the Republican Exhibition of Technical Creativity of Students of the Technical and Vocational Education in the First Republican Youth Rally \\\"Kasip. KZ\\\".\\r\\n2012 Certificate of the Regional Committee of the Trade Union of Science and Education.\\r\\n\\r\\n2012 Diploma and prize in the nomination \\\"Best Master of Industrial Training\\\" of the Akim of the Karaganda Region.\\r\\n2012 The candidacy was approved for inclusion in the “Elite Book “WHO is WHO” in the System of Technical and Vocational Education of the Republic of Kazakhstan” by the decision of the Republican Commission of the Council of Directors of Educational Institutions of Technical and Vocational Education. 2014 Letter of thanks from the Minister of Education and Science'),
(16, 'БАЙЖАНОВ ПАЙЗУЛЛА КАРГУЛОВИЧ', 'ОБРАЗОВАНИЕ 1977-1982 г.г. Карагандинский политехнический институт (ныне КарГТУ), горный факультет, горный инженер; 1993-1997 г.г. Карагандинская Высшая школа следственного Комитета (ныне КЮИ), Правовед; РАБОТАЕТ В КОЛЛЕДЖЕ: с 2012г ДОЛЖНОСТЬ: заведующий отдела кадров ОПЫТ РАБОТЫ 1982-1984 г.г. Командир взвода управления артиллерийской батареи артиллерийского полка Закарпатского военного округа; Воинское звание – лейтенант; 1984-1985 г.г. Инженер лаборатории горного оборудования Карагандинского научно-исследовательского угольного института; 1985-2010 г.г. Служба в органах внутренних дел Республики Казахстан – (с 1985 по 1998 г.г. в пгт Агадырь Карагандинской области) заместитель начальника отделения Государственного пожарного надзора; начальник отделения дознания Агадырского РОВД; начальник следственного отделения Государственного следственного Комитета по Агадырскому району (ныне Шетский район); - (с 1998 по 2004 г.г. в Департаменте внутренних дел Карагандинской области) следователь собственной безопасности; старший следователь по особо важным делам Следственного управления; заместитель начальника Центра криминальной информации; начальник инспекции Штаба управления; - с ноября 2004 по июнь 2010 г.г. заместитель начальника УВД г.Жезказгана по следствию; В июне 2010 года по выслуге лет вышел на пенсию; Звание – полковник полиции; 2011 г.-2012 г. – юрист ТОО «Тұмар-2020» (охранное агентство); С апреля 2012 года по настоящее время заведующий отдела кадров КГКП «Карагандинский технико-строительный колледж». ДОПОЛНИТЕЛЬНАЯ ИНФОРМАЦИЯ Специалист в области уголовного и гражданского судопроизводства (претензионная работа, правовая экспертиза контрактов, составление контрактов; регистрация, перерегистрация юридического лица, исковое производство, государственные закупки и т.д.), трудового законодательства; Имеет государственную лицензию за № 0003796 от 02.07.2010 года на право занятия адвокатской деятельностью; Сертификат за № G 1693 «Организация кадровой работы и воинского учета» академии государственного управления при президенте Республики Казахстан; Знание ПК; Свободно владеет казахским и русскими языками; В 2024 году выпустил книгу «Жезқазған өңірінің тергеу тарихы».', '9.png', '2025-01-05 04:21:18', 'ветеран ктск', 'БАЙЖАНОВ ПАЙЗУЛЛА КАРГУЛОВИЧ', '', '', 'ОБРАЗОВАНИЕ 1977-1982 г.г. Карагандинский политехнический институт (ныне КарГТУ), горный факультет, горный инженер; 1993-1997 г.г. Карагандинская Высшая школа следственного Комитета (ныне КЮИ), Правовед; РАБОТАЕТ В КОЛЛЕДЖЕ: с 2012г ДОЛЖНОСТЬ: заведующий отдела кадров ОПЫТ РАБОТЫ 1982-1984 г.г. Командир взвода управления артиллерийской батареи артиллерийского полка Закарпатского военного округа; Воинское звание – лейтенант; 1984-1985 г.г. Инженер лаборатории горного оборудования Карагандинского научно-исследовательского угольного института; 1985-2010 г.г. Служба в органах внутренних дел Республики Казахстан – (с 1985 по 1998 г.г. в пгт Агадырь Карагандинской области) заместитель начальника отделения Государственного пожарного надзора; начальник отделения дознания Агадырского РОВД; начальник следственного отделения Государственного следственного Комитета по Агадырскому району (ныне Шетский район); - (с 1998 по 2004 г.г. в Департаменте внутренних дел Карагандинской области) следователь собственной безопасности; старший следователь по особо важным делам Следственного управления; заместитель начальника Центра криминальной информации; начальник инспекции Штаба управления; - с ноября 2004 по июнь 2010 г.г. заместитель начальника УВД г.Жезказгана по следствию; В июне 2010 года по выслуге лет вышел на пенсию; Звание – полковник полиции; 2011 г.-2012 г. – юрист ТОО «Тұмар-2020» (охранное агентство); С апреля 2012 года по настоящее время заведующий отдела кадров КГКП «Карагандинский технико-строительный колледж». ДОПОЛНИТЕЛЬНАЯ ИНФОРМАЦИЯ Специалист в области уголовного и гражданского судопроизводства (претензионная работа, правовая экспертиза контрактов, составление контрактов; регистрация, перерегистрация юридического лица, исковое производство, государственные закупки и т.д.), трудового законодательства; Имеет государственную лицензию за № 0003796 от 02.07.2010 года на право занятия адвокатской деятельностью; Сертификат за № G 1693 «Организация кадровой работы и воинского учета» академии государственного управления при президенте Республики Казахстан; Знание ПК; Свободно владеет казахским и русскими языками; В 2024 году выпустил книгу «Жезқазған өңірінің тергеу тарихы».', '', ''),
(17, 'АУБАКИРОВА АЙМАН ТУРСУНОВНА', 'ОБРАЗОВАНИЕ: высшее, КарГУ им Е. Букетова, год окончания 1974 г. ДОЛЖНОСТЬ: Преподаватель русского языка и литературы Место работы: - 1974-1976гг. по распределению была направлена в город Каркаралинск, сш №2 - 1976-1999 гг. преподаватель русского языка и литературы профтехучилище №129; - 1985г. была переведена на должность заместителя директора по общеобразовательным предметам. - в настоящее время работает администратором кинотеатра «Сарыжайлау».', '10.png', '2025-01-05 04:21:41', 'ветеран ктск', 'АУБАКИРОВА АЙМАН ТУРСУНОВНА', 'ӘУБӘКІРОВА АЙМАН ТҰРСЫНҚЫЗЫ', 'AUBAKIROVA AIMAN TURSUNOVNA', 'ОБРАЗОВАНИЕ: высшее, КарГУ им Е. Букетова, год окончания 1974 г. ДОЛЖНОСТЬ: Преподаватель русского языка и литературы Место работы: - 1974-1976гг. по распределению была направлена в город Каркаралинск, сш №2 - 1976-1999 гг. преподаватель русского языка и литературы профтехучилище №129; - 1985г. была переведена на должность заместителя директора по общеобразовательным предметам. - в настоящее время работает администратором кинотеатра «Сарыжайлау».', 'Білімі: жоғары, Е. Бөкетов атындағы ҚарМУ, бітірген жылы 1974 ж. Лауазымы: орыс тілі мен әдебиеті оқытушысы Жұмыс орны: - 1974-1976 жж. бөлу бойынша Қарқаралы қаласына, №2 ОМ - 1976-1999 жж. орыс тілі мен әдебиеті оқытушысы №129 кәсіптік училище; - 1985 ж. директордың орынбасары лауазымына ауыстырылды жалпы білім беретін пәндер бойынша. - қазіргі уақытта \\\"Сарыжайлау\\\" кинотеатрының әкімшісі болып жұмыс істейді.', 'Russian Russian language and literature EDUCATION: higher education, E. Buketov KarSU, graduation year 1974. POSITION: Teacher of Russian language and literature Place of work: - 1974-1976. she was assigned to the city of Karkaralinsk, secondary school No. 2 - 1976-1999. teacher of Russian language and literature, vocational school No. 129; - 1985. she was transferred to the position of deputy director in general education subjects. - Currently, he works as the administrator of the Saryzhailau cinema.'),
(18, 'КЕНЖЕБАЕВА ДАМЕЛИ МУХАНОВНАв', 'ОБРАЗОВАНИЕ: Высшее, Алма-Атинский энергетический институт. РАБОТАЕТ В КОЛЛЕДЖЕ с 2015 года. ДОЛЖНОСТЬ: Преподаватель экономических дисциплин. НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ: 1. «Благодарственное письмо» УОКО-2017; 2. «Благодарственное письмо» НПП КО -2016,2020; 3. Құрмет грамотасы Қарағанды облысының білім басқармасы 2021ж. 4.Публикация статьи «Активизация обучения- современное требование к образованию» в сборнике материалов Республиканской научно-практической конференции «Новые инновационные технологии в образовании», 2015г. 5.Областная дистанционная научно- практическая конференция на тему: «Современные тенденции в изучении экономических дисциплин: состояние и перспективы» 2020г. В рамках деятельности бизнес - школы проводились следующие мероприятия и участия в конкурсах: 6. Подготовка студентов: Рысқұлова А., Татымбаева Т., Байгошкарова Г., Ағибай Н. для участия в областном конкурсе бизнес-идей среди студентов колледжей Карагандинской области «Идея на миллион», 2015г. 7.Организация мероприятия на тему «Бизнес – это единственный способ перестать выживать и начать жить», посвящённое Областному молодежному движению «Жігер», клубу «Молодых предпринимателей», 2016г. 8.Подготовка студентки группы 11-ТС-15 Талдықбаеву А. для участия в Республиканской научно-практической конференции \\\"Казахстан – 2050 Стратегиясы – Мәңгілік Ел Жастары көзқарасымен\\\" с докладом на тему \\\" Дорогу- бизнесу молодых\\\", 2017г. 9.Организация и проведение бизнес-тренинга «Развитие молодежного предпринимательства», 2017г. 10.Организация и проведение бизнес-игры «Я - предприниматель» среди студентов второго курса КГУ КТСК 2016г., 2018г., 2020г. 11. Областной конкурс «Молодежь - в малый бизнес», Среди студентов организации ТиПО Карагандинской области (в рамках празднования 30-летия Независимости РК) 2021г. 12.Организация гостевых лекций с действующими предпринимателями Карагандинской области (Гостевая лекция со Смаиловым Д.Т.-директором ТОО \\\"PACKING-KZ\\\", с Ибкеевым С. К. – президентом Ассоциации предпринимателей г.Шахтинск, с предпринимателем торгово дома «Селена» Байтасовым К. У. в 2021г.) 13.Участвовала в разработке бизнес-проектов по мебельному производству, сувенирной продукции, рекламной продукции. Дамели Мухановна сотрудничает с Учебно-методическим центром развития образования Карагандинской области, с НАО «Талап». С 2016 года являлась Внештатным тренером и проводила курсы повышения квалификации педагогических работников. Является одним из группы разработчиков: - учебно- методического комплекса факультативного курса (34 часа) «Шаги к успешному бизнесу» 2016г. - программы факультативного курса «Основы эффективного трудоустройства» для технического и профессионального образования. 2020г.', '11.jpg', '2025-01-05 04:22:03', 'ветеран ктск', 'КЕНЖЕБАЕВА ДАМЕЛИ МУХАНОВНА', 'КЕНЖЕБАЕВА ДАМЕЛИ МҰХАНҚЫЗЫ', 'KENZHEBAYEVA DAMELI MUKHANOVNA', 'ОБРАЗОВАНИЕ: Высшее, Алма-Атинский энергетический институт. РАБОТАЕТ В КОЛЛЕДЖЕ с 2015 года. ДОЛЖНОСТЬ: Преподаватель экономических дисциплин. НАГРАДЫ, ЗВАНИЯ, ДОСТИЖЕНИЯ: 1. «Благодарственное письмо» УОКО-2017; 2. «Благодарственное письмо» НПП КО -2016,2020; 3. Құрмет грамотасы Қарағанды облысының білім басқармасы 2021ж. 4.Публикация статьи «Активизация обучения- современное требование к образованию» в сборнике материалов Республиканской научно-практической конференции «Новые инновационные технологии в образовании», 2015г. 5.Областная дистанционная научно- практическая конференция на тему: «Современные тенденции в изучении экономических дисциплин: состояние и перспективы» 2020г. В рамках деятельности бизнес - школы проводились следующие мероприятия и участия в конкурсах: 6. Подготовка студентов: Рысқұлова А., Татымбаева Т., Байгошкарова Г., Ағибай Н. для участия в областном конкурсе бизнес-идей среди студентов колледжей Карагандинской области «Идея на миллион», 2015г. 7.Организация мероприятия на тему «Бизнес – это единственный способ перестать выживать и начать жить», посвящённое Областному молодежному движению «Жігер», клубу «Молодых предпринимателей», 2016г. 8.Подготовка студентки группы 11-ТС-15 Талдықбаеву А. для участия в Республиканской научно-практической конференции \\\\\\\"Казахстан – 2050 Стратегиясы – Мәңгілік Ел Жастары көзқарасымен\\\\\\\" с докладом на тему \\\\\\\" Дорогу- бизнесу молодых\\\\\\\", 2017г. 9.Организация и проведение бизнес-тренинга «Развитие молодежного предпринимательства», 2017г. 10.Организация и проведение бизнес-игры «Я - предприниматель» среди студентов второго курса КГУ КТСК 2016г., 2018г., 2020г. 11. Областной конкурс «Молодежь - в малый бизнес», Среди студентов организации ТиПО Карагандинской области (в рамках празднования 30-летия Независимости РК) 2021г. 12.Организация гостевых лекций с действующими предпринимателями Карагандинской области (Гостевая лекция со Смаиловым Д.Т.-директором ТОО \\\\\\\"PACKING-KZ\\\\\\\", с Ибкеевым С. К. – президентом Ассоциации предпринимателей г.Шахтинск, с предпринимателем торгово дома «Селена» Байтасовым К. У. в 2021г.) 13.Участвовала в разработке бизнес-проектов по мебельному производству, сувенирной продукции, рекламной продукции. Дамели Мухановна сотрудничает с Учебно-методическим центром развития образования Карагандинской области, с НАО «Талап». С 2016 года являлась Внештатным тренером и проводила курсы повышения квалификации педагогических работников. Является одним из группы разработчиков: - учебно- методического комплекса факультативного курса (34 часа) «Шаги к успешному бизнесу» 2016г. - программы факультативного курса «Основы эффективного трудоустройства» для технического и профессионального образования. 2020г.', 'Білімі: жоғары, Алматы энергетикалық институты. Колледжде 2015 жылдан бастап жұмыс істейді. Лауазымы: экономикалық пәндер оқытушысы. МАРАПАТТАРЫ, АТАҚТАРЫ, ЖЕТІСТІКТЕРІ: 1. УОКОНЫҢ\\\" алғыс хаты \\\" - 2017; 2. \\\"Алғыс хат\\\" ҰКП КО -2016,2020; 3. Құрмет грамотасы Қарағанды облысының білім басқармасы 2021ж.4.2015 ж. \\\"білім берудегі жаңа инновациялық технологиялар\\\" республикалық ғылыми - практикалық конференциясының материалдар жинағында \\\"оқытуды жандандыру-білімге қойылатын заманауи талап\\\" мақаласын жариялау. 5.2020 ж. \\\"экономикалық пәндерді оқытудағы заманауи үрдістер: жай - күйі мен болашағы\\\" тақырыбында облыстық қашықтықтан ғылыми - тәжірибелік конференция бизнес-мектеп қызметі шеңберінде мынадай іс-шаралар және конкурстарға қатысу өткізілді: 6. Студенттерді даярлау: Рысқұлова А., Татымбаева Т., Байгошкарова г., Ағибай Н. Қарағанды облысының колледж студенттері арасында \\\"миллионға арналған Идея\\\" облыстық бизнес-идеялар конкурсына қатысу үшін, 2015ж. 7.Облыстық \\\"Жігер\\\" жастар қозғалысына, \\\"жас кәсіпкерлер\\\" клубына арналған \\\"Бизнес – бұл өмір сүруді тоқтатудың және өмір сүруді бастаудың жалғыз жолы\\\" тақырыбында іс-шара ұйымдастыру, 2016ж. 8.11-КО-15 тобының студенті А. Талдықбаеваны\\\"Қазақстан-2050 Стратегиясы – Мәңгілік Ел жастары көзқарасымын \\\\\\\" республикалық ғылыми – практикалық конференциясына қатысу үшін\\\\ \\\"жас бизнеске жол \\\\\\\" тақырыбында баяндамамен дайындау, 2017ж.9.\\\"Жастар кәсіпкерлігін дамыту\\\" бизнес-тренингін ұйымдастыру және өткізу, 2017ж. 10.2016ж., 2018ж., 2020ж. ктск КММ екінші курс студенттері арасында \\\"Мен-кәсіпкер\\\" бизнес - ойынын ұйымдастыру және өткізу 11. Қарағанды облысы ТжКБ ұйымының студенттері арасында \\\"Жастар - шағын бизнеске\\\" облыстық байқауы (ҚР Тәуелсіздігінің 30 жылдығын мерекелеу шеңберінде) 2021ж.12.Қарағанды облысының жұмыс істеп тұрған кәсіпкерлерімен қонақ дәрістер ұйымдастыру (Д. Т. Смайыловпен-\\\"PACKING-KZ \\\\\\\" ЖШС директоры, С. К. Ибкеевпен – Шахтинск қаласының кәсіпкерлер қауымдастығының президенті, \\\"Селена\\\" сауда үйінің кәсіпкері К. У. Байтасовпен қонақ дәріс 2021 жылы) 13.Жиһаз өндірісі, Кәдесый өнімдері, жарнамалық өнімдер бойынша бизнес-жобаларды әзірлеуге қатысты. Дамели Мұханқызы Қарағанды облысының білім беруді дамыту оқу-әдістемелік орталығымен, \\\"Талап\\\"КЕАҚ-мен ынтымақтасады. 2016 жылдан бастап штаттан тыс жаттықтырушы болды және педагог қызметкерлердің біліктілігін арттыру курстарын өткізді. Әзірлеушілер тобының бірі болып табылады: - 2016 жылғы \\\"табысты бизнеске қадамдар\\\" факультативтік курсының оқу-әдістемелік кешені (34 сағат). - техникалық және кәсіптік білім беру үшін \\\"тиімді жұмысқа орналасу негіздері\\\" факультативтік курсының бағдарламалары. 2020ж.', 'education: Higher education, Alma Ata Power Engineering Institute. SHE has BEEN WORKING AT THE COLLEGE since 2015. POSITION: Lecturer in Economics. AWARDS, TITLES, ACHIEVEMENTS: 1. \\\"Letter of thanks\\\" from UOKO-2017; 2. \\\"Letter of Thanks\\\" from NPP KO -2016,2020; 3. Kurmet gramotasy from Karaganda region bilim baskarmasy 2021j. 4. Publication of the article \\\"Activation of learning - a modern requirement for education\\\" in the collection of materials of the Republican scientific and practical conference \\\"New innovative technologies in Education\\\", 2015. 5. Regional remote scientific and practical conference on the topic: \\\"Current trends in the study of economic disciplines: state and prospects\\\" 2020. The following events and competitions were held as part of the business school\\\'s activities: 6. Preparation of students: Ryskulova A., Tatymbaeva T., Baygoshkarova G., Agibai N. for participation in the regional competition of business ideas among college students of Karaganda region \\\"Idea for a million\\\", 2015. 7. Organization of an event on the theme \\\"Business is the only way to stop surviving and start living\\\", dedicated to the Regional youth movement \\\"Zhiger\\\", the club of \\\"Young entrepreneurs\\\", 2016. 8. Preparation of a student of group 11–TS-15 Taldykbayeva A. to participate in the Republican scientific and practical conference \\\\\\\\\\\\\\\"Kazakhstan – 2050 Strategyasi – Mangilik El Zhastary kozkarasymen\\\\\\\\\\\\\\\" with a report on \\\\\\\\\\\\\\\"The road to business for the young\\\\\\\\\\\\\\\", 2017. 9.Organization and conduct of business training \\\"Development of youth entrepreneurship\\\", 2017. 10. Organization and holding of the business game \\\"I am an entrepreneur\\\" among second-year students of KSU KTSK 2016, 2018, 2020 11. Regional competition \\\"Youth - in small business\\\", Among students of the organization of the TVET of the Karaganda region (in celebration of the 30th anniversary of Independence of the Republic of Kazakhstan) 2021 12.Organization guest lectures with current entrepreneurs of the Karaganda region (Guest lecture with D.T. Smailov, Director of \\\\\\\\\\\\\\\"PACKING-KZ\\\\\\\\\\\\\\\" LLP, with S.K. Ibkeev, President of the Shakhtinsk Entrepreneurs Association, with K. U. Baitasov, entrepreneur of the Selena trading house. in 2021) 13. Participated in the development of business projects for furniture production, souvenir products, and promotional products. Dameli Mukhanovna cooperates with the Educational and Methodological Center for the Development of Education in the Karaganda region, with the NAO Talap. Since 2016, she has been a freelance coach and has conducted advanced training courses for teaching staff. He is one of the developers of: - educational and methodological complex of the optional course (34 hours) \\\"Steps to a successful business\\\" 2016. - optional course programs \\\"Fundamentals of effective employment\\\" for technical and vocational education. 2020');
INSERT INTO `veterans` (`id`, `name`, `biography`, `photo`, `created_at`, `rank`, `name_ru`, `name_kz`, `name_en`, `biography_ru`, `biography_kz`, `biography_en`) VALUES
(19, 'ИСАЕВА ФРАНЧЕСКА ПЕТРОВНА', 'Исаева Франческа Петровна работала в данном учебном заведении более 12-ти лет в 1980-1990-х годах преподавателем математики, ранее имея стаж работы в школе. Из воспоминаний Франчески Петровны, в те годы в училище обучалось порядка 1200 учащихся. Коллектив был хороший, говорит Франческа Петровна, всегда хотелось идти на работу. Было очень много мероприятий. Я работала в большинстве со студентами специальности бурильщик, газосварщик, автомобилистами, КИП (контрольно-измерительные приборы).\r\nФранческе Петровне мы задали ряд вопросов, ответы, которые мы получили, решили привести дословно. Следует отметить, что интервью состоялось интересно и познавательно для наших педагогов, в том числе молодых...\r\nВопрос: Какие образовательные методы и подходы Вы применяли в своей работе? \r\n-	Ответ: Опрос, индивидуальная работа, дидактические материалы, карточки, учетный счет. Причем каждый год педагогов направляли на курсы усовершенствования знаний.\r\n-	Вопрос: Какие воспоминания или моменты из Вашей работы особенно запечатлились в Ваших воспоминаниях? \r\n-	Ответ: Была хорошая организация педагогической работы.\r\n-	В: Какую роль играет педагог в жизни студентов, особенно в современном обществе?\r\n-	О: Основную. Научить студентов способам как добывать знания, формировать учебную деятельность и мышление. Именно педагог научит ребёнка мыслительной деятельности, и именно он участвует в интеллектуальном и нравственном формировании его личности.\r\n-	В: Какие изменения в системе образования Вы предложили бы, основываясь на Вашем опыте?\r\n-	О: Вовлекать студентов к той работе к чему он пришел. Быть справедливым и не оскорблять, не повышать тон. Он тогда почувствует, что он востребован. Внедрить в учебный процесс игры и симуляторы. Это вовлечет студентов, сделает обучение наглядным и поможет развивать навыки XXI века: работать в команде, мыслить критически и творчески.\r\n-	В: Чем Вы гордитесь в своей карьере педагога?\r\n-	О: Знанием предмета. Я люблю свой предмет.\r\n-	В: Как Вы оцениваете важность взаимодействия между преподавателем и студентами для успешного обучения?\r\n-	О: Доверие.\r\n-	В: Как Вы видите изменения в системе образования с момента Вашего ухода на пенсию?\r\n-	О: Как появилвись гаджеты они стали нервными, необщительные. Сейчас учитель не читает.\r\n-	В: Какой студент или группа студентов оставили на Вас наибольшее впечатление, и почему?\r\n-	О: Повара, обучавшиеся на специальности «Контрольно-измерительные приборы». Большинству студентов по этой специальности были не так важны оценки в дипломе, как умение решать проблемы и глубина понимания предмета.\r\n-	В: С какими вызовами и трудностями Вы сталкивались в процессе своей педагогической работы, и как Вы их преодолевали?\r\n-	О: Учитель все сам должен был достать для работы. Сами рисовали, сами копировали.\r\n-	В: Какую роль играет педагог в становлении и развитии молодого поколения?\r\n-	О: Важную. Он должен быть предметом подражания. Не опускаться на уровень «дружка». Держать интервал. Самооценка. Характер гибкости личности, создающие возможность своевременного оптимального выбора способа самореализации и самоструктурирования личности в деятельности.\r\n-	В: Как Вы считаете, что можно было бы улучшить или изменить в современной системе образования?\r\n-	О: Повышать мотивацию педагогов путем изменения статуса профессии и условий работы. Учить детей на родном языке не менее 10 лет, прежде чем они смогут полностью переключиться на другой язык обучения. Выделять достаточные ресурсы на образование, финансирование организаций, с учетом очевидной эффективности использования средств для улучшения качества образования.\r\n-	В: Какие педагогические принципы и ценности Вы старались придерживаться в своей работе?\r\n-	О: Быть справедливым. Это нужно! Они видят.\r\n-	В: Какие советы Вы дали бы молодым педагогам, которые только начинают свою карьеру?\r\n-	О: Для начала нужно определить для себя манеру поведения. Каким педагогом вы хотите быть? Будьте справедливы и проявляйте уважение. Не кричите на студентов, не шутите над ними, не обижайте и не дразните, не приказывайте. Умение находить общий язык с тем контингентом, которыми он работает. Если нет контакта - нет знаний. Нужно подвести, чтобы самому это сделать. Как бы ко мне не относились, так я отношусь. Видеть человека, больше общаться. Студент должны видеть успехи преподавателя. «С ремеслом спеши дружить — в коллективе легче жить». Будьте открыты и дружелюбны.\r\n-	Спасибо, Франческа Петровна. Здоровья и энергии вам на долгие годы.\r\n\r\nИнтервью провела преподаватель истории и общественных наук Блялова  Мөлдір Айтбаевна\r\nИсаева Франческа Петровна работала в данном учебном заведении более 12-ти лет в 1980-1990-х годах преподавателем математики, ранее имея стаж работы в школе. Из воспоминаний Франчески Петровны, в те годы в училище обучалось порядка 1200 учащихся. Коллектив был хороший, говорит Франческа Петровна, всегда хотелось идти на работу. Было очень много мероприятий. Я работала в большинстве со студентами специальности бурильщик, газосварщик, автомобилистами, КИП (контрольно-измерительные приборы).\r\nФранческе Петровне мы задали ряд вопросов, ответы, которые мы получили, решили привести дословно. Следует отметить, что интервью состоялось интересно и познавательно для наших педагогов, в том числе молодых...\r\nВопрос: Какие образовательные методы и подходы Вы применяли в своей работе? \r\n-	Ответ: Опрос, индивидуальная работа, дидактические материалы, карточки, учетный счет. Причем каждый год педагогов направляли на курсы усовершенствования знаний.\r\n-	Вопрос: Какие воспоминания или моменты из Вашей работы особенно запечатлились в Ваших воспоминаниях? \r\n-	Ответ: Была хорошая организация педагогической работы.\r\n-	В: Какую роль играет педагог в жизни студентов, особенно в современном обществе?\r\n-	О: Основную. Научить студентов способам как добывать знания, формировать учебную деятельность и мышление. Именно педагог научит ребёнка мыслительной деятельности, и именно он участвует в интеллектуальном и нравственном формировании его личности.\r\n-	В: Какие изменения в системе образования Вы предложили бы, основываясь на Вашем опыте?\r\n-	О: Вовлекать студентов к той работе к чему он пришел. Быть справедливым и не оскорблять, не повышать тон. Он тогда почувствует, что он востребован. Внедрить в учебный процесс игры и симуляторы. Это вовлечет студентов, сделает обучение наглядным и поможет развивать навыки XXI века: работать в команде, мыслить критически и творчески.\r\n-	В: Чем Вы гордитесь в своей карьере педагога?\r\n-	О: Знанием предмета. Я люблю свой предмет.\r\n-	В: Как Вы оцениваете важность взаимодействия между преподавателем и студентами для успешного обучения?\r\n-	О: Доверие.\r\n-	В: Как Вы видите изменения в системе образования с момента Вашего ухода на пенсию?\r\n-	О: Как появилвись гаджеты они стали нервными, необщительные. Сейчас учитель не читает.\r\n-	В: Какой студент или группа студентов оставили на Вас наибольшее впечатление, и почему?\r\n-	О: Повара, обучавшиеся на специальности «Контрольно-измерительные приборы». Большинству студентов по этой специальности были не так важны оценки в дипломе, как умение решать проблемы и глубина понимания предмета.\r\n-	В: С какими вызовами и трудностями Вы сталкивались в процессе своей педагогической работы, и как Вы их преодолевали?\r\n-	О: Учитель все сам должен был достать для работы. Сами рисовали, сами копировали.\r\n-	В: Какую роль играет педагог в становлении и развитии молодого поколения?\r\n-	О: Важную. Он должен быть предметом подражания. Не опускаться на уровень «дружка». Держать интервал. Самооценка. Характер гибкости личности, создающие возможность своевременного оптимального выбора способа самореализации и самоструктурирования личности в деятельности.\r\n-	В: Как Вы считаете, что можно было бы улучшить или изменить в современной системе образования?\r\n-	О: Повышать мотивацию педагогов путем изменения статуса профессии и условий работы. Учить детей на родном языке не менее 10 лет, прежде чем они смогут полностью переключиться на другой язык обучения. Выделять достаточные ресурсы на образование, финансирование организаций, с учетом очевидной эффективности использования средств для улучшения качества образования.\r\n-	В: Какие педагогические принципы и ценности Вы старались придерживаться в своей работе?\r\n-	О: Быть справедливым. Это нужно! Они видят.\r\n-	В: Какие советы Вы дали бы молодым педагогам, которые только начинают свою карьеру?\r\n-	О: Для начала нужно определить для себя манеру поведения. Каким педагогом вы хотите быть? Будьте справедливы и проявляйте уважение. Не кричите на студентов, не шутите над ними, не обижайте и не дразните, не приказывайте. Умение находить общий язык с тем контингентом, которыми он работает. Если нет контакта - нет знаний. Нужно подвести, чтобы самому это сделать. Как бы ко мне не относились, так я отношусь. Видеть человека, больше общаться. Студент должны видеть успехи преподавателя. «С ремеслом спеши дружить — в коллективе легче жить». Будьте открыты и дружелюбны.\r\n-	Спасибо, Франческа Петровна. Здоровья и энергии вам на долгие годы.\r\n\r\n', 'net_foto_2.png', '2025-06-02 06:08:06', 'ветеран ктск', 'ИСАЕВА ФРАНЧЕСКА ПЕТРОВНА', 'ИСАЕВА ФРАНЧЕСКА ПЕТРОВНА', NULL, 'Исаева Франческа Петровна работала в данном учебном заведении более 12-ти лет в 1980-1990-х годах преподавателем математики, ранее имея стаж работы в школе. Из воспоминаний Франчески Петровны, в те годы в училище обучалось порядка 1200 учащихся. Коллектив был хороший, говорит Франческа Петровна, всегда хотелось идти на работу. Было очень много мероприятий. Я работала в большинстве со студентами специальности бурильщик, газосварщик, автомобилистами, КИП (контрольно-измерительные приборы).\\r\\nФранческе Петровне мы задали ряд вопросов, ответы, которые мы получили, решили привести дословно. Следует отметить, что интервью состоялось интересно и познавательно для наших педагогов, в том числе молодых...\\r\\nВопрос: Какие образовательные методы и подходы Вы применяли в своей работе? \\r\\n-	Ответ: Опрос, индивидуальная работа, дидактические материалы, карточки, учетный счет. Причем каждый год педагогов направляли на курсы усовершенствования знаний.\\r\\n-	Вопрос: Какие воспоминания или моменты из Вашей работы особенно запечатлились в Ваших воспоминаниях? \\r\\n-	Ответ: Была хорошая организация педагогической работы.\\r\\n-	В: Какую роль играет педагог в жизни студентов, особенно в современном обществе?\\r\\n-	О: Основную. Научить студентов способам как добывать знания, формировать учебную деятельность и мышление. Именно педагог научит ребёнка мыслительной деятельности, и именно он участвует в интеллектуальном и нравственном формировании его личности.\\r\\n-	В: Какие изменения в системе образования Вы предложили бы, основываясь на Вашем опыте?\\r\\n-	О: Вовлекать студентов к той работе к чему он пришел. Быть справедливым и не оскорблять, не повышать тон. Он тогда почувствует, что он востребован. Внедрить в учебный процесс игры и симуляторы. Это вовлечет студентов, сделает обучение наглядным и поможет развивать навыки XXI века: работать в команде, мыслить критически и творчески.\\r\\n-	В: Чем Вы гордитесь в своей карьере педагога?\\r\\n-	О: Знанием предмета. Я люблю свой предмет.\\r\\n-	В: Как Вы оцениваете важность взаимодействия между преподавателем и студентами для успешного обучения?\\r\\n-	О: Доверие.\\r\\n-	В: Как Вы видите изменения в системе образования с момента Вашего ухода на пенсию?\\r\\n-	О: Как появилвись гаджеты они стали нервными, необщительные. Сейчас учитель не читает.\\r\\n-	В: Какой студент или группа студентов оставили на Вас наибольшее впечатление, и почему?\\r\\n-	О: Повара, обучавшиеся на специальности «Контрольно-измерительные приборы». Большинству студентов по этой специальности были не так важны оценки в дипломе, как умение решать проблемы и глубина понимания предмета.\\r\\n-	В: С какими вызовами и трудностями Вы сталкивались в процессе своей педагогической работы, и как Вы их преодолевали?\\r\\n-	О: Учитель все сам должен был достать для работы. Сами рисовали, сами копировали.\\r\\n-	В: Какую роль играет педагог в становлении и развитии молодого поколения?\\r\\n-	О: Важную. Он должен быть предметом подражания. Не опускаться на уровень «дружка». Держать интервал. Самооценка. Характер гибкости личности, создающие возможность своевременного оптимального выбора способа самореализации и самоструктурирования личности в деятельности.\\r\\n-	В: Как Вы считаете, что можно было бы улучшить или изменить в современной системе образования?\\r\\n-	О: Повышать мотивацию педагогов путем изменения статуса профессии и условий работы. Учить детей на родном языке не менее 10 лет, прежде чем они смогут полностью переключиться на другой язык обучения. Выделять достаточные ресурсы на образование, финансирование организаций, с учетом очевидной эффективности использования средств для улучшения качества образования.\\r\\n-	В: Какие педагогические принципы и ценности Вы старались придерживаться в своей работе?\\r\\n-	О: Быть справедливым. Это нужно! Они видят.\\r\\n-	В: Какие советы Вы дали бы молодым педагогам, которые только начинают свою карьеру?\\r\\n-	О: Для начала нужно определить для себя манеру поведения. Каким педагогом вы хотите быть? Будьте справедливы и проявляйте уважение. Не кричите на студентов, не шутите над ними, не обижайте и не дразните, не приказывайте. Умение находить общий язык с тем контингентом, которыми он работает. Если нет контакта - нет знаний. Нужно подвести, чтобы самому это сделать. Как бы ко мне не относились, так я отношусь. Видеть человека, больше общаться. Студент должны видеть успехи преподавателя. «С ремеслом спеши дружить — в коллективе легче жить». Будьте открыты и дружелюбны.\\r\\n-	Спасибо, Франческа Петровна. Здоровья и энергии вам на долгие годы.\\r\\n\\r\\n', 'Исаева Франческа Петровна осы оқу орнында 1980-1990 жылдары 12 жылдан астам уақыт математика пәнінің оқытушысы болып жұмыс атқарды, бұған дейін мектепте еңбек еткен. Франческа Петровнаның естеліктерінен сол жылдары училищеде 1200-ге жуық білім алушы оқыды. Франческа Петровна ұжымның ауызбірлігінің  болғанын, соның арқасында күнделікті жұмысқа тамаша көңілде барғысы келетін ерекшелігін айтты. «Көптеген іс-шаралар болды. Мен көп жағдайда бұрғылаушы, газбен дәнекерлеуші, автокөлік жүргізушілері, БӨА (бақылау-өлшеу аспаптары) мамандығының студенттерімен жұмыс істедім.»-дейді.\\r\\nФранческа Петровнаға біз бірқатар сұрақтар қойдық, алған жауаптарымызды сөзбе-сөз келтіруді шештік. Айта кету керек, сұхбат біздің педагогтер, оның ішінде жастар үшін қызықты әрі танымды өтті...\\r\\nСұрақ: Сіз өз жұмысыңызда қандай білім беру әдістері мен тәсілдерін қолдандыңыз?\\r\\n-	Жауап: Сауалнама, жеке жұмыс, дидактикалық материалдар, карточкалар, шот. Сонымен қатар жыл сайын мұғалімдер білімді жетілдіру курстарына жіберілді.\\r\\n-	Сұрақ: Сіздің жұмысыңыздағы қандай естеліктер немесе сәттер сіздің естеліктеріңізге ерекше әсер етті? \\r\\n-	Жауап: Педагогикалық жұмыстар жақсы ұйымдастырылды.\\r\\n-	Сұрақ: Мұғалім студенттердің өмірінде, әсіресе қазіргі қоғамда қандай рөл атқарады?\\r\\n-	Жауап: Негізгі. Студенттерге білім алу, оқу қызметі мен ойлауды қалыптастыру жолдарын үйрету. Бұл балаға ақыл-ой әрекетін үйрететін мұғалім, және ол оның жеке басының интеллектуалды және моральдық қалыптасуына қатысады.\\r\\n-	Сұрақ: Сіздің тәжірибеңізге сүйене отырып, білім беру жүйесіне қандай өзгерістер енгізуді ұсынар едіңіз?\\r\\n-	Жауап: Студентті өзі таңдаған мамандығы бойынша жұмысқа тарту керек. Әділ болыңыз және қорламаңыз, дауыс  көтермеңіз. Содан кейін ғана ол өзінің сұранысқа ие екенін сезінеді. Оқу процесіне ойындар мен тренажерларды енгізу. Бұл студенттерді тартады, оқуды көрнекі етеді және ХХІ ғасырдың дағдыларын дамытуға көмектеседі: командада жұмыс істеу, сыни және шығармашылық ойлау.\\r\\n-	Сұрақ: Сіз мұғалім педагог ретіндегі мансабыңызда немен мақтанасыз?\\r\\n-	Жауап: Пәнді білу. Мен өз пәнімді жақсы көремін.\\r\\n-	Сұрақ: Табысты оқу үшін оқытушы мен студенттердің өзара әрекеттесуінің маңыздылығын қалай бағалайсыз?\\r\\n-	Жауап: Сенім.\\r\\n-	Сұрақ: Зейнеткерлікке шыққаннан бері білім беру жүйесіндегі өзгерістерді қалай көресіз?\\r\\n-	Жауап: Гаджеттер қалай пайда болды, олардың солай жүйкелері тоза бастады, коммуникативті емес болып шығып жатыр. Қазіргі мұғалім кітап оқымайды.\\r\\n-	Сұрақ: Сізге қай студент немесе студенттер тобы үлкен әсер қалдырды және неге?\\r\\n-	Жауап: «Бақылау-өлшеу аспаптары» мамандығы бойынша оқыған аспаздар. Осы мамандық бойынша студенттердің көпшілігіне дипломдық бағалар проблемаларды шеше білу және тақырыпты түсіну тереңдігі сияқты маңызды болмады.\\r\\n-	Сұрақ: Педагогикалық жұмыс барысында Сіз қандай қиындықтар мен сындарға тап болдыңыз және оларды қалай жеңдіңіз?\\r\\n-	Жауап: Мұғалім жұмыс үшін бәрін өзі алуы керек керек кезң болды. Олар өздері сурет салды, өздері көшірді.\\r\\n-	Сұрақ: Жас ұрпақтың қалыптасуы мен дамуында мұғалім қандай рөл атқарады?\\r\\n-	Жауап: Маңызды. Ол еліктеу нысаны болуы керек. \\\"Дос\\\" деңгейіне түспеңіз. Аралықты сақтаңыз. Өзін-өзі бағалау керек. Тұлғаның икемділігінің сипаты, өзін-өзі жүзеге асыру және өзін-өзі жасау әдісін уақтылы оңтайлы таңдау мүмкіндігін тудырады.\\r\\n-	Сұрақ: Қазіргі білім беру жүйесінде нені жақсартуға немесе өзгертуге болады деп ойлайсыз?\\r\\n-	Жауап: Кәсіптің мәртебесі мен жұмыс жағдайларын өзгерту арқылы мұғалімдердің ынтасын арттыру. Балаларды басқа оқу тіліне толығымен ауыспас бұрын кем дегенде 10 жыл ана тілінде үйрету. Білім беру сапасын жақсарту үшін қаражатты пайдаланудың айқын тиімділігін ескере отырып, білім беруге, ұйымдарды қаржыландыруға жеткілікті ресурстар бөлу.\\r\\n-	Сұрақ: Сіз өз жұмысыңызда қандай педагогикалық принциптер мен құндылықтарды ұстануға тырыстыңыз?\\r\\n-	Жауап: Әділ болу. Бұл қажет! Олар бәрін байқайды.\\r\\n-	Сұрақ: Бүгінде карьерасын енді бастаған жас педагогтерге қандай кеңестер берер едіңіз?\\r\\n-	Жауап: Алдымен Сіз жағымды, орта қағидатына сай мінез-құлықты өзіңіз қалыптастыруыңыз керек. Сіз қандай тәрбиеші болғыңыз келеді? Әділ болыңыз және құрмет көрсетіңіз. Студенттерге айқайламаңыз, оларды әзілдемеңіз, ренжітпеңіз немесе мазақ етпеңіз, алданда бұйырып сөйлемеңіз. Ол жұмыс істейтін контингентпен ортақ тіл таба білу. Егер байланыс болмаса-білім жоқ. Берілген тапсырманы өзі жасауға әкелу керек. Маған қалай қараса, мен солай қараймын деген болмайды. Адамды тану-көру үшін көп байланыс жасалады. Студент мұғалімнің жетістіктерін көруі керек. \\\"Қолөнермен достасуға асықсаң,  ұжымда өмір сүру оңайырақ\\\". Ашық және мейірімді болыңыз.\\r\\n-	Рахмет, Франческа Петровна! Денсаулық пен қуат беріп, ұзақ жасаңыз!.\\r\\n', NULL);

